window.__D("text/pelach-harimon/c007",{"p":[[4801940198,"<b>ולהבין</b><sup data-n=\"5478\">17</sup> יש להבין בד\"כ ההפרש בין בחי' עמידה ובין בחי' הילוך הנה המלאכים נק' עומדים כמ\"ש ונתתי לך מהלכים<sup data-n=\"5479\">18</sup> בין העומדים האלה וגם הנשמה נק' עומד כמ\"ש באלי' חי ה' אשר עמדתי לפניו<sup data-n=\"5480\">19</sup> כו' רק הנשמה כשמתלבשת בגוף עי\"ז באה לבחי' מהלך כמאמר ונתתי לך מהלכים כו' ר\"ל כשמקיימת תומ\"צ בגשמי' כו'. והענין יובן ע\"פ הידוע שיש ב' בחי' ממכ\"ע וסוכ\"ע<sup data-n=\"5481\">20</sup>, בחי' ממכ\"ע הוא אור הבא בדרך התלבשות עד\"מ הנפש המחי' את הגוף שאור וחיות הנפש נמזג באברים בכל אבר לפי ערכו ומתאחד עמו בתכלית עד שמשניהם יחד דייקא נעשה הולדה חדש<sup data-n=\"5482\">21</sup> כמו עד\"מ אור וחיות הנמזג באבר המוח מתאחד עמו בתכלית עד שמשניהם יחד דייקא נולד השכלת שכל כי החיות בעצמו הוא פשוט ונבדל מגדר שכל וגם אבר המוח עצמו לא יוליד שכל רק כשמתמזגים יחד אז נעשה האור וחיות הממוזג מקור להולדת שכל, [... ואע\"פ שאין ערוך מרוחני' אל הגשמי' מ\"מ ע\"י כח המפליא לעשות מתחברים יחד עד שנעשו דבר אחד ממש כו'. ..] וכ\"ה מזיגת החיות בלב להוליד מדות כו' וכן מזיגת החיות באברי המעשה נעשה ממנו מקור להולדת תנועה והילוך כו', ולכן יש חילוקי מדריגות בבחי' החיות מצד מזיגת האברים כי החיות בעצם הוא פשוט ורוחני ולא יתחלק כו' כידוע. כ\"ה למעלה הבחי' הנק' ממכ\"ע הוא בחי' אור וחיות האלקי המתלבש בעולמות שמזה נמשך בהם בחי' ביטול לאלקות [... וכל מי שיש בו בחי' ביטול יותר החיות יותר הוא בבחי' נצחיות כידוע בשם הה\"מ נ\"ע בענין יראת הוי' לחיים<sup data-n=\"5483\">22</sup>. ..], ובא בחילוקי מדריגו' בכל עולם לפי ערכו כמו בעולם הבריאה החיות הוא בגילוי יותר לכן נמצא בו ביטול יותר, ובעולם היצי' מתצמצם החיות צמצום שני מתמעט האור וחיות יותר לכן אין ביטול כ\"כ ועד\"ז בעולם העשי' מתצמצם יותר כו', ועל זה נאמר ואתה מחי' את כולם<sup data-n=\"5484\">23</sup> אתה הוא בחי' הדיבור בדבר ה' שמים נעשו<sup data-n=\"5485\">24</sup> והוי\"ו דואתה הוא בחי' הקול המקור לדיבור<sup data-n=\"5486\">25</sup> כו', אך בחי' סוכ\"ע הוא בחי' אא\"ס עצמו שמקיף כל העולמות בהשוואה, ואין הכוונה סובב ומקיף מלמעלה<sup data-n=\"5487\">26</sup> רק כמו העיגול שאין בו מעלה ומטה<sup data-n=\"5488\">27</sup> כך הוא נמצא בכל העולמות בהשוואה כי לפניו אצי' ועשי' שוין<sup data-n=\"5489\">28</sup> שכולם אין ערוך אליו בהשוואה, לכן בגילוי לית מח' תפיסא בי'<sup data-n=\"5490\">29</sup>, אפי' מחה\"ק דא\"ק כו', ובהעלם לית",[["5478","17","<b>ולהבין</b>: ב ניתוסף: זה."],["5479","18","<b>ונתתי לך מהלכים</b>: זכרי' ג, ז. ראה לעיל ע' תלב ובהערה 43."],["5480","19","<b>באלי' חי ה' אשר עמדתי לפניו</b>: מל\"א יז, א־ יח, טו [בדילוג]. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשעו. פרשיות התורה ח\"ב ע' תשכט ובהנסמן במ\"מ לשם. שה\"א צח, ב ובהערה 14. תו\"ח בשלח ח\"א קסד, ב. לעיל ע' שמה."],["5481","20","<b>ממכ\"ע וסוכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["5482","21","<b>חדש</b>: אב: חדשה."],["5483","22","<b>בשם הה\"מ נ\"ע בענין יראת ה' לחיים</b>: משלי יט, כג. ראה לעיל ע' קנח ובהערות 49-48."],["5484","23","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["5485","24","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["5486","25","<b>הקול המקור לדיבור</b>: ראה גם שע\"ת קכו, ב."],["5487","26","<b>ואין הכוונה סובב ומקיף מלמעלה</b>: ראה תניא פמ\"ח סז, סע\"ב. לעיל ע' קס ובהערה 64."],["5488","27","<b>העיגול שאין בו מעלה ומטה</b>: ראה מאמרי אדה\"א נ\"ך ע' תמז. וש\"נ. תו\"ח שמות ח\"א לז, ד. וש\"נ."],["5489","28","<b>אצי' ועשי' שוין</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' יג. וש\"נ. תו\"ח שמות ח\"א קלה, א. וש\"נ."],["5490","29","<b>לית מח' תפיסא בי'</b>: ראה תק\"ז בהקדמה יז, א."]]],[4801940255,"אתר פנוי מיני'<sup data-n=\"5491\">30</sup> אפי' המקום הגשמי דעשי' כו', אך מציאותו בהעלם הוא עיקר קיום כל העולמות כו', אך כ\"ז הוא כסדר השתלשלו' אינו מאיר בגילוי רק בחי' ממכ\"ע אבל בחי' סוכ\"ע הוא בהעלם, אך ע\"י קיום התורה ומצות בגשמי' ממשיכים בחי' סוכ\"ע בבחי' התגלות בנשמה וכמאמר אשר קדשנו במצותיו<sup data-n=\"5492\">31</sup> שמאיר קדושה עליונה דבחי' סוכ\"ע בבחי' גילוי בנשמה כו'.\n<b>ועתה</b> יובן ההפרש בין בחי' הילוך לבחי' עמידה, שבחי' המלאכים נק' עומדים להיותם מקבלים הארה בעלמא מבחי' ממכ\"ע המאיר דרך קול ודבר ה' שזהו בחי' ואתה מחי' את כולם כנ\"ל, ואפי' הנשמות שעלו במח'<sup data-n=\"5493\">32</sup> אינם מקבלים רק מבחי' אורות המתלבשים בכלים דאצי' לכן נק' ג\"כ עומדים אבל כשהנשמה מתלבשת בגוף ומקיימת תומ\"צ עי\"ז נמשך בחי' סוכ\"ע ובא לידי גילוי אור, וגילוי אור זה מאיר בנשמה שהוא בבחי' א\"ס בבחי' בלי גבול לכן נק' מהלך, בעילוי אחר עילוי לאין שיעור [... כידוע דאא\"ס הוא למעלה עד אין קץ<sup data-n=\"5494\">33</sup> כו'. ..]. והטעם לזה מה שע\"י המצות גשמיים דייקא הנעשים בעוה\"ז הגשמי ממשיכים אור הסוכ\"ע, היינו מצד כח התהוות הגשמי' מן הרוחני' אינו בא מבחי' השתלשלו' רק מצד כל יכול כמבואר באגה\"ק במאמר איהו וחיוהי<sup data-n=\"5495\">34</sup> כו', נמצא שבחשכות העוה\"ז שהוא הפירוד שלו שהוא מכח הסוכ\"ע כאשר מהפכים אותו לאור דהיינו שיהי' בבחי' ביטול כלי ומכון לשבתו ית' ע\"י המצות שעושים מדברים הגשמיים כו' אזי נמשך הסוכ\"ע ובא בבחי' גילוי אור כו', משא\"כ ע\"פ השתלשלו' הגם שבעוה\"ז הגשמי מאיר כח הסובב הוא בהעלם כו' רק ע\"י המצות בא לידי גילוי אור [... כמבואר במאמרי יביאו לבוש מלכות<sup data-n=\"5496\">35</sup> כו'. ..], ולכן ארז\"ל היום לעשותם<sup data-n=\"5497\">36</sup> ולמחר לקבל שכרם כו'. ובזה יובן מה שארז\"ל אשר אנכי מצוך היום, בכל יום יהיו בעיניך כחדשים<sup data-n=\"5498\">37</sup>, ואיך יכול להיות כחדשים הלא אותם התפילין שהניח אתמול הוא מניחם למחר כו' אך הכוונה שהאור המאיר על ידם בכל יום הוא אור חדש לגמרי.\n<b>והענין</b> הוא כי בבחי' ממכ\"ע יש ג\"כ בחי' העלם וגילוי ובכל יום נתחדשו מע\"ב, רק החידוש הזה אינו חידוש גמור רק מה שכבר נמדד בהעלם בא לידי גילוי [... וראשית ההעלם הוא בחי' מחה\"ק ושם נמדדו כל פרטי ההשתלשלו' במקום",[["5491","30","<b>לית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. לקו\"ת בהר מא, א. שם בהוספות נב, ג."],["5492","31","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."],["5493","32","<b>הנשמות שעלו במח'</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248. לקמן מאמר ד\"ה רפאיני הא' על יד הערה 52."],["5494","33","<b>דאא\"ס הוא למעלה עד אין קץ</b>: ראה ז\"ח יתרו לד, ג. ת\"ז תי\"ט (מ, ב). תו\"ח נח סט, ב ובהערה 11."],["5495","34","<b>התהוות הגשמי'. . באגה\"ק במאמר איהו וחיוהי</b>: ס\"כ (קל, רע\"ב)."],["5496","35","<b>במאמרי יביאו לבוש מלכות</b>: תו\"א צ, א. צא, ג. צב, א."],["5497","36","<b>היום לעשותם</b>: ואתחנן ז, יא. ראה ערובין כב, א."],["5498","37","<b>אשר אנכי מצוך היום. . כחדשים</b>: ואתחנן ו, ו. ראה לקח טוב שם. מאמרי אדה\"א דברים ח\"א ע' רסו ואילך. וש\"נ. לעיל ע' קמב הערה 14."]]],[4801940308,"וגם ההתחדשות שיתחדשו בכל שיתא אלפי שני<sup data-n=\"5499\">38</sup> בזמן כבר נמדד בהעלם במחה\"ק ולכן אינו נק' חידוש גמור. ..], משא\"כ כאשר אור הסוכ\"ע בא לידי גילוי שאינו נמדד בכלים נק' אור חדש לגמרי שלא הי' מעולם בהעלם כו' [... ולכן א' כחדשים בכף הדמיון כו' כי הכלי שהוא המצוה בעצמה אינו חדשה רק האור המאיר על ידה הוא חדש לגמרי כו' וד\"ל. ..], וזהו ג\"כ ענין מצות התשובה<sup data-n=\"5500\">*39</sup> שהיא בעוה\"ז<sup data-n=\"5501\">39</sup> דייקא כמאמר כל אשר תמצא ידך כו' כי אין מעשה<sup data-n=\"5502\">40</sup> כו', וכמארז\"ל המקדש את האשה<sup data-n=\"5503\">41</sup> ע\"מ שאני צדיק גמור שאע\"פ שהוא רשע גמור מקודשת שמא הרהר תשובה בלבו, והנה צדיק גמור ורשע גמור הם שני הפכים כי צדיק גמור כבר היפך הרע שבנפשו לטוב כו' ורשע גמור גבר על הטוב עד שנסתלק ממנו לגמרי כידוע בלק\"א<sup data-n=\"5504\">42</sup> וע\"י הרהור א' בלבד יוכל להתהפך מן הקצה לקצה כו'. אך הענין הוא ג\"כ מטעם הנ\"ל מצד שבעוה\"ז מאיר בחי' סוכ\"ע ושם אין המצות והעוונות תופסים מקום כלל כמאמר אם חטאת מה תפעל לו<sup data-n=\"5505\">43</sup> ואם צדקת<sup data-n=\"5506\">44</sup> כו' לכן כשמאיר אור הסובב בגילוי ע\"י התשובה שהרהר בלבו יוכל להתהפך מן הקצה לקצה שיהי' צדיק גמור אע\"פ שעד הנה הי' רשע גמור כו'. אך א\"כ אינו מובן כיון שהמצות אינם תופסים מקום בבחי' הסובב איך ע\"י מעשה המצות מעורר אור הסובב לבוא לידי גילוי כיון שאינם תופסים מקום כלל כו'.\n<b>אך</b> הענין יובן ע\"פ המאמר תען לשוני<sup data-n=\"5507\">45</sup> כו' כי כל מצותיך צדק, והענין הוא ע\"ד דוגמא מנתינת הצדקה שאחד נותן לחבירו שלא הרויח אצלו כלום רק כך עולה ברצונו שיתן לו צדקה כך המה המצות אינם מעוררים גילוי הסובב ע\"פ טבע [... כמו כמים הפנים<sup data-n=\"5508\">46</sup> כו' כן לב האדם כו' שזהו ע\"פ טבע ההשתלשלות כו'. ..] רק כך עלה ברצונו בתורת צדקה שכאשר יעשו מצוה אחת להתעטף בציצית כו' או להניח תפילין יתגלה עי\"ז אור הסובב ויבוא לידי גילוי בנשמה כו', נמצא שאין העשי' בעצמה פועלת המשכת אור הסובב כו' רק הרצון הוא הפועל כו', והנה רצון הוא אותיות צינור<sup data-n=\"5509\">47</sup> כמו שהצינור מצמצם שפע המים העוברים על ידו שיתקבלו בכלי ולא ילכו לאיבוד כו' כ\"ה הוא ברצה\"ע שממשיך אור הסובב שיתגלה בכלים שע\"י הכלים נמשך האור בסט' דקדושה דייקא שרש נש\"י ואינו הולך לאיבוד שיהי' ממנו",[["5499","38","<b>שיתא אלפי שני</b>: ראה ר\"ה לא, א. מאמרי אדה\"א בראשית ע' נג. וש\"נ."],["5500","*39","<b>מצות התשובה</b>: ראה לקו\"ש ר\"ה כרך ד ע' 1144 ובהערה 5. משפטים כרך ו ע' 329. קדושים כרך יז ע' 210 ואילך ובהערה 40. נשא כרך לח ע' 18 ואילך."],["5501","39","<b>התשובה שהיא בעוה\"ז</b>: ראה סידור שחרית לב, א. לד, ב. לקו\"ת פינחס עה, ב ואילך. לקמן מאמר ד\"ה רפאיני הא' ובהערה 69."],["5502","40","<b>כל אשר תמצא ידך. . כי אין מעשה</b>: קהלת ט, י."],["5503","41","<b>המקדש את האשה</b>: קדושין מט, ב. ראה גם לעיל ע' תסב ובהערה 35."],["5504","42","<b>בלק\"א</b>: ספי\"א."],["5505","43","<b>אם חטאת מה תפעל לו</b>: איוב לה, ו [ושם: בו]."],["5506","44","<b>ואם צדקת</b>: איוב שם, ז [ושם: אם — ראה גם לעיל מאמר ד\"ה והתהלכתי תרט\"ו הערה 17]."],["5507","45","<b>תען לשוני</b>: תהלים קיט, קעב."],["5508","46","<b>כמים הפנים</b>: משלי כז, יט."],["5509","47","<b>רצון הוא אותיות צינור</b>: ראה זהר הרקיע לזהר בראשית נא, א (כה, ב). מאמרי אדה\"א בראשית ע' לו. וש\"נ."]]],[4801940358,"יניקת החיצוני' ח\"ו [... כי הגם שהחיצוני' מקבלי' מבחי' המקיף כמאמ' רם על כל גוים הוי'<sup data-n=\"5510\">48</sup> מצד דקמי' כחשיכה כאורה<sup data-n=\"5511\">49</sup> זהו מחיצוני' החיות בלבד אבל הפנימי' נמשך לישראל דוקא ע\"י המצות ממכי\"ק<sup data-n=\"5512\">50</sup>. ..], וזהו הטעם דשמירת הל\"ת שכן נתצמצם ברצה\"ע שירצה את המצוה ויומשך על ידה בבחי' גילוי ולא ירצה את העבירה לכן אפי' האור שכבר נמשך מסתלק ע\"י החטא כו' [... כמאמר עבירה מכבה מצוה<sup data-n=\"5513\">51</sup> כו'. ..] כו' וד\"ל. אך ע\"י התשובה מעוררים למעלה מן הצינור אשר שם אין תופסים מקום המצות והעוונות וממשיכים אור חדש בבחי' הצינור שיתהפך מבחי' לאו להן כו' וד\"ל. והטעם לזה כי מצות התשובה היא ג\"כ מצוה רבה ונשאה וממשיך ממקור הרצון אור חדש למלאות כל החסרונות ולהעביר כל הפגמים וממילא נמשך הפנימי' דרך הצינור אור חדש [ולא כמו באה\"ע שנמשך רק החיצוני' כו' וד\"ל], ונעשה החזרת הרצון שיהא מרוצה וחביב כו' כמבואר בלק\"א<sup data-n=\"5514\">52</sup> כו' וד\"ל [... וביאור הענין לפע\"ד הנה הרצון נק' כאשר נמשך לדבר פרט להיות רוצה באיזה דבר ולא ירצה בהיפוכ\"ו אך עצם הרצון הוא מקור כל רצון ומשם יכול להחליף להיות רוצה בדבר שלא רצה עד הנה כך למעלה הרצון במצות ה' להיות רוצה במ\"ע ולשנוא היפוכו שהוא הדבר האסור כ\"ז נק' רצון פרטי [הגם שהוא כולל תרי\"ג מ\"ע ומל\"ת] אבל המקור לכל מיני רצון הוא הנק' רעווא דכל רעוין<sup data-n=\"5515\">53</sup> ונק' בעל הרצון<sup data-n=\"5516\">54</sup> וגם זאת הוא ירידה לגבי עצמותו, אך להיות שאינו מוגבל בדבר פרטי לזאת יוכל משם להיות נמשך שירצה היפוך רצונו שעד הנה כו', ולשם מגיע מצות התשובה לזאת יוכל להיות משם סליחת עוונות וגם להתהפך מסילוק הרצון שיתהווה חזרת הרצון להיות מרוצה וחביב כקודם החטא כו' וד\"ל. ..].\n<b>וזהו</b> מ\"ש אין כל חדש תחת השמש<sup data-n=\"5517\">55</sup> אבל לעילא מן שמשא יש חדשות כו', הענין הוא דבחי' יסוד אבא נק' שמש<sup data-n=\"5518\">56</sup> כו', והנה בו גופא יש ד' בחי' אבי\"ע<sup data-n=\"5519\">57</sup>",[["5510","48","<b>רם על כל גוים הוי'</b>: תהלים קיג, ד."],["5511","49","<b>כחשיכה כאורה</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. סידור סדר הגדה רצז, רע\"ד. עט\"ר דרוש לעשי\"ת ע' נא. סה\"מ תרכ\"ז ע' תצד."],["5512","50","<b>ממכי\"ק</b>: ממאמר כתב יד קדשו (של הצ\"צ). התוכן — ראה אוה\"ת כאן ע' תרעח ואילך.\nכ\"ה בכ\"מ בכתבי ר\"ה ומהם: לעיל במאמר ד\"ה לה\"ע קרי\"ס כמה פעמים. ד\"ה אשה כי תזריע תרכ\"ג (ג\"פ). לקמן ד\"ה רפאיני תר\"ח על יד הערה 31. פלח הרמון שמות כמצויין במפתח שמות ספרים ואנשים ע' תלח מערכת מכי\"ק. וכנראה שזהו הוספת הצ\"צ — על אמירת המאמר — בעת כתיבת המאמר. אמנם אין זה העתקת לשונו של הצ\"צ כפי שמופיע במאמריו, כ\"א התוכן."],["5513","51","<b>עבירה מכבה מצוה</b>: סוטה כא, א. ראה רמ\"ז לזהר רע\"מ צו כח, ב (וכן צ\"ל שם — בדפי הספר כב, סע\"ב ואילך). לקו\"ת ראה כ, א. מאמרי אדה\"א הנחות תקע\"ז ס\"ע שטז ואילך. וש\"נ."],["5514","52","<b>מרוצה וחביב. . בלק\"א</b>: אגה\"ת פ\"ב."],["5515","53","<b>רעווא דכל רעוין</b>: ראה זהר ספדצ\"נ תרומה קעו, ב. לעיל ע' תלג ובהערה 56."],["5516","54","<b>בעל הרצון</b>: ראה גם בענין בעל הרצון לעיל ע' סז ובהערה 10."],["5517","55","<b>אין כל חדש תחת השמש</b>: קהלת א, ט [ושם ואין — ראה מאמרי אדה\"א דברים ח\"א ע' רסו. וש\"נ]. זהר לך צא, ב."],["5518","56","<b>יסוד אבא נק' שמש</b>: ראה גם אוה\"ת (כאן) ע' תרעט. (לעיל) ע' תרמג. ישעי' כרך א ע' קצח. ביאוה\"ז — להצ\"צ — אמור כרך ב ע' תתקסד. ע' תתקסז."],["5519","57","<b>יסוד אבא. . אבי\"ע</b>: ראה גם אוה\"ת (כאן) ע' תרעט. (לעיל) ע' תרמג."]]],[4801940404,"[... כידוע דבחכ\"ע דאצי' יש ג\"כ בחי' אבי\"ע<sup data-n=\"5520\">58</sup> חכ' שבחכ' היא אצי' שבה בינה שבחכ' הוא בחי' בריאה שבה מדות חג\"ת דחכ' הוא בחי' יצירה שבה נה\"י דחכ' הוא בחי' עשי' שבה וכל הבחי' מתעלין ע\"י היסוד שבחכ' שנק' יסו\"א נמצא שבו ג\"כ יש כל הבחי' כו' וד\"ל. ..], והנה בי\"ע שבו נק' בי\"ע שבאצי' והיינו מה שיש בו כח ומקור להשפיע בי\"ע כו', ובחי' זאת נק' שמש להיות מקור להוות הנבראים מאין ליש שלכן נק' הוי' ע\"ש שהוא מהווה<sup data-n=\"5521\">59</sup> מאין ליש ע\"י הנרתק דשם אלקים<sup data-n=\"5522\">60</sup> משא\"כ אצי' שבאצי' שבו הוא עצמו' פנימי' אור אבא והוא גילוי אור שלמעלה מהשתלשלות והוא בחי' אור הגנוז כו' [... שלמעלה משני המאורות אפי' כמ\"ש בבחי' שני המאורות הגדולים<sup data-n=\"5523\">61</sup> היינו שוין בקומתן ואור הגנוז שנברא ביום הא' הוא למעלה מהן כו'. ..], והוא המתגלה ע\"י המצות והוא בחי' אור חדש בכל עת מטעם הנ\"ל שאינו מוגבל בזמן ומקום ואינו בבחי' העלם וגילוי כו' וד\"ל. וזהו מה רב טובך<sup data-n=\"5524\">62</sup> אשר צפנת ליריאך צפנת בגי' כתר<sup data-n=\"5525\">63</sup> [... והגם שמבואר למעלה שהוא בחי' פנימי' אור אבא מ\"מ מאיר בו ג\"כ אור הכתר כו'. ..], והיינו שמאיר ע\"י המצות תרי\"ג דאורייתא וז' דרבנן כו' בגי' כתר<sup data-n=\"5526\">64</sup> כו'. והנה המשכת אור חדש שלמעלה מהשתלשלות נק' הילוך להיותו בלתי מוגבל ונק' אור חדש בעצם כו', משא\"כ האור המתחדש בכ\"י ע\"י ההשתלשלות כמאמר המחדש בטובו<sup data-n=\"5527\">65</sup> כו' נק' עמידה להיותו ביטול מוגבל במקום וזמן ואינו נק' חדש בעצם, רק התחדשות מהעלם אל הגילוי כו' וד\"ל.\n<b>והנה</b> בשבת נאמר שירו לה' שיר חדש<sup data-n=\"5528\">66</sup> מצד שמתגלה בחי' הסובב בבחי' גילוי בממלא בבחי' או\"פ שהוא בחי' אור חדש לגמרי כנ\"ל ולכן זמן תולדות נשמות חדשות הוא בשבת<sup data-n=\"5529\">67</sup> דייקא כו' וד\"ל, והיינו אור הגנוז שמאיר בשבת כו' וד\"ל [... והגם שבנשמות הגבוהות שיש להם אהבה דבכל מאודך מאיר גם בימות החול גילוי אור הסובב בממלא בבחי' פנימי' אפשר לומר שבשבת מאיר בחי' גבוה יותר בבחי' פנימי והיינו שרש המצות כמ\"ש בבחי' תרי\"ג אורחי' דגולגלתא<sup data-n=\"5530\">68</sup> שעל זה אנו מבקשים קדשינו במצותיך<sup data-n=\"5531\">69</sup> כמבואר במ\"א וד\"ל].",[["5520","58","<b>דבחכ\"ע. . אבי\"ע</b>: ראה גם אוה\"ת שבועות כרך ו ר\"ע א'תשלד."],["5521","59","<b>הוי' ע\"ש שהוא מהווה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים ש\"ד, ספ\"י. שער היחוה\"א פ\"ד. פ\"ז. הערה בסה\"מ ת\"ש ע' 40."],["5522","60","<b>הנרתק דשם אלקים</b>: שער היחוה\"א רפ\"ד."],["5523","61","<b>שני המאורות הגדולים</b>: בראשית א, טז."],["5524","62","<b>מה רב טובך</b>: תהלים לא, כ."],["5525","63","<b>צפנת בגי' כתר</b>: ראה מאו\"א מערכת צפנת ס\"י. אוה\"ת עה\"פ ס\"ג. תזריע ע' עד. בלק ס\"ע א'ל. עקב ע' תקעו. משלי ע' תריב. סה\"מ תרל\"ב ח\"א ע' סח. ס\"ע קעט. המשך מים רבים תרל\"ו ח\"א ע' רכט. תער\"ב ח\"ב ע' א'לה."],["5526","64","<b>תרי\"ג. . וז'. . כת\"ר</b>: ראה לעיל ע' קלב. וש\"נ."],["5527","65","<b>המחדש בטובו</b>: ברכת יוצר."],["5528","66","<b>שירו לה' שיר חדש</b>: תהלים צח, א."],["5529","67","<b>תולדות נשמות חדשות הוא בשבת</b>: ראה ביאוה\"ז אמור פ, ד ואילך. אוה\"ת נח ע' נט ואילך (ביאוה\"ז נח ע' טז ואילך)."],["5530","68","<b>תרי\"ג אורחי' דגולגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א."],["5531","69","<b>קדשינו במצותיך</b>: תפלת העמידה לשבת. ראה גם לעיל ע' שנד ובהערה 94."]]],[4801940447,"<b>ומעתה</b> יש להבין איך שבבחי' הילוך הנ\"ל יש ב' מיני הילוך, הילוך בבחי' פנים והילוך בבחי' אחוריים, ויש להקדים ענין מארז\"ל<sup data-n=\"5532\">*70</sup> ברומי' דקראי דלפעמים כתוב ועמדו זרים<sup data-n=\"5533\">70</sup> כו' ולפעמים כתוב ואספת דגנך<sup data-n=\"5534\">71</sup> ותירצו כאן כשישראל עושין רצונו של מקום וכאן כשאין עושין כו' וידוע הקושיא דהלא ואספת דגנך נאמר בפ' שני' דק\"ש ושם נאמר והי' אם שמוע תשמעו<sup data-n=\"5535\">72</sup> כו' ותירץ הה\"מ נ\"ע שמפני שאינו כתוב בכל מאודיך<sup data-n=\"5536\">73</sup> בפ' שני' לכן קורא אותן אין עושי'. ולהבין זאת דהלא אם מקיים כל המצות וגם באה' דבכל לבבכם כו' וכי מפני שאין לו אה' דבכל מאודיך יקרא בשם אין עושין רצונו כו'. אך הענין יובן בהקדם ביאור ופי' דעושין רצונו של מקום כו', כי הנה מקום הוא בחי' ממכ\"ע<sup data-n=\"5537\">74</sup> בחי' מל' אור וחיות המתלבש בבחי' מקום מעלה ומטה כו' ועושין רצונו היינו שממשיכים רצון העליון שהוא בחי' סוכ\"ע בבחי' ממכ\"ע ויתגלה בגילוי גמור בבחי' אור פנימי כו', ובחי' זאת לא יוכל להיות כ\"א כשיש לו אה' דבכל מאודיך שזהו הזזת פנימי' ועצמי' נקודת הלב לבוא לידי גילוי באה' והיא אה' בלתי גבולי' ולכן אין שום מניעה אל האה' [... כידוע דבבחי' יחידה בבואה דבבואה לית להו<sup data-n=\"5538\">75</sup> ולכן אין את זה לעומת זה<sup data-n=\"5539\">76</sup> המנגדה כו'. ..], ולכן היא העולה בבחי' עצמי' אא\"ס הסוכ\"ע ומעוררו לבוא לידי גילוי בבחי' או\"פ משא\"כ כשאין לו אה' דבכל מאדך רק אה' דבכל לבבכם כו' שאז האה' לא תוכל לעורר בחי' הסוכ\"ע [... מצד שהיא נמשכת מבחי' ממלא וגם יש לה מונעים ומנגדים המגבילים ולא תוכל לעורר א\"ס הבלתי מוגבל כו'. ..], רק עצם העשי' של המצוה תעורר הסוכ\"ע [... כי עשי' לעילא<sup data-n=\"5540\">77</sup> ששרשה בבחי' כל יכול כנ\"ל. ..], ולכן לא יומשך אור הסובב בגילוי בבחי' פנימי רק תשאר בבחי' מקיף שהוא ג\"כ בחי' אור ופועל השמירה מן הרע כמאמר שומר מצוה<sup data-n=\"5541\">78</sup> כו' וזהו הטעם שהמצות נק' לבושים<sup data-n=\"5542\">79</sup> מחמת שאינם נמשכים רק בבחי' מקיף [... ולפעמים נק' בשם<sup data-n=\"5543\">80</sup> פירות<sup data-n=\"5544\">81</sup> היינו כשנעשים ע\"פ אה' דבכל מאודיך כנ\"ל וד\"ל. ..], ולכן נק' אין עושים רצונו של מקום כי אינם ממשיכים רצה\"ע בבחי' פנימי הנק' מקום רק בבחי' מקיף כו' וד\"ל. ולכן כשיש לו אה' דבכל מאודיך ונמשך בחי' הסובב בגילוי בבחי' פנימי מלאכתן נעשה ע\"י אחרים כי א\"צ להתלבש בלבושי המתברר רק הבירורים מתבררים ממילא ונמשכים",[["5532","*70","<b>מארז\"ל</b>: ראה גם לעיל ע' תסב הערה 36."],["5533","70","<b>ועמדו זרים</b>: ישעי' סא, ה."],["5534","71","<b>ואספת דגנך</b>: עקב יא, יד."],["5535","72","<b>והי' אם שמוע תשמעו</b>: שם יא, יג."],["5536","73","<b>ותירץ הה\"מ. . בכל מאודיך</b>: ראה או\"ת עקב ד\"ה מפני מה (נג, סע\"ג ואילך). לעיל ע' תסב ובהערה 40."],["5537","74","<b>מקום. . ממכ\"ע</b>: ראה גם אוה\"ת יחזקאל כרך א ס\"ע תב ואילך. סה\"מ תרל\"ה ח\"א ס\"ע קו ואילך. וש\"נ. לעיל ע' תסג וש\"נ."],["5538","75","<b>בבואה דבבואה לית להו</b>: יבמות קכב, א. ראה מאמרי אדה\"א דברים ח\"ב ע' תקמב ואילך ובהנסמן שם. שע\"ת נה, א."],["5539","76","<b>את זה לעומת זה</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד ואילך."],["5540","77","<b>עשי' לעילא</b>: ראה זהר בהר קח, ב. ביאוה\"ז בהר פב, סע\"ב ואילך. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תעא ואילך. סה\"מ תרע\"ח ע' שצו ואילך."],["5541","78","<b>שומר מצוה</b>: קהלת ח, ה. ראה גם לעיל ר\"ע קצו."],["5542","79","<b>שהמצות נק' לבושים</b>: ראה לעיל ע' תסג הערה 60 ואילך. וש\"נ."],["5543","80","<b>שהמצות. . נק' בשם פירות</b>: ראה סוטה מו, סע\"א."],["5544","81","<b>שהמצות נק' לבושים. . פירות</b>: ראה גם לעיל ע' תסד ובהערה 65."]]],[4801940485,"ומתכללים באור המאיר ומתלבש בו שהוא בחי' הסובב כנ\"ל, משא\"כ כשאין אור הסובב מאיר בו בגילוי אז צריך להתלבש בלבושי המתברר ולבררו וזהו מלאכתם נעשי' ע\"י עצמן ועל זה נאמר ואספת דגנך כו' וד\"ל.\n<b>והנה</b> בבחי' בע\"ת מאיר ג\"כ בחי' הילוך דבחי' אחוריים להיות ההתעוררות שבו בא מלמטה שהוא בחי' החיצוני' שהוא הרגשת הריחוק [... אך אפשר לומר שזהו בחי' בע\"ת כמו ראב\"ד שיצתה נפשו<sup data-n=\"5545\">82</sup> כו' ולא עשה אח\"כ מע\"ט כו' אך בע\"ת שנשאר בחיים אחר התשובה האמיתית מאה\"ר ועושה ומקיים תומ\"צ אזי ההילוך שלו בבחי' פנים להיות שאצלם נעשה בחי' אה' דבכל מאדך ביתר שאת מבצד\"ג שאצלם הוא הזזת עצם היחידה כו', משא\"כ בצד\"ג אינו רק גילוי אור היחידה כו' וד\"ל. ..].\n<b>ועם</b> כל הנ\"ל יובן ב' מיני הילוך הנ\"ל הילוך בבחי' פנים והילוך בבחי' אחוריים, כי הילוך נק' הגילוי דסוכ\"ע כנ\"ל וכאשר מאיר בחי' הסובב בבחי' פנימי אז מאיר מתחילה בבחי' מוחו ולבבו בתפילה בלבוש המח' כו' ואח\"כ מתלבש בו בעת לימוד התורה בדיבור ואח\"כ במעשה המצות ונמצא שנמשך אור הסובב ומתגלה בבחי' הפנימי' שלו ומפנימי' נמשך לחיצוני' שלו, ולכן נק' הילוך בבחי' פנים כו' כי תחילת הגילוי שלו הוא בבחי' הפנימי' וממילא מתגלה בבחי' חיצוני' כו'. וזהו ענין פ' ראשונה דק\"ש שנאמר בו סדר ההילוך מלמעלה למטה מתחילה ההעלאה דאה' דבכל מאדך ואח\"כ ההמשכה מתחילה והיו הדברים<sup data-n=\"5546\">83</sup> כו' על לבבך במח' [... כי הרהורי הלב עולין אל המוח לחשב ולהרהר בהם כו'. ..], ואח\"כ ושננתם<sup data-n=\"5547\">84</sup> בדיבור ואח\"כ וקשרתם<sup data-n=\"5548\">85</sup> במעשה כי הוקשה כל התורה כולה לתפילין<sup data-n=\"5549\">86</sup> כו', משא\"כ בפ' שני' דק\"ש נק' הילוך בבחי' אחוריים כי אור הסובב הנק' הילוך אינו מאיר רק בבחי' מקיף והמקיף הוא מתלבש בחיצוני' בבחי' המעשה המצות הנק' לבושים רק אעפ\"כ נמשך תוס' הארה במוח ולב לכן נאמר בו סדר ההילוך מלמטה למעלה בתחילה וקשרתם<sup data-n=\"5550\">87</sup> ואח\"כ ולמדתם<sup data-n=\"5551\">88</sup> כו' וד\"ל. ובזה יובן ג\"כ מאמר פר\"א כשישראל עושין<sup data-n=\"5552\">89</sup> רש\"מ שותים מאוצר העליון והיינו ממטר השמים כמאמר יפתח ה' לך<sup data-n=\"5553\">90</sup> את אוצרו הטוב כו', והיינו כנ\"ל שהוא בחי' גילוי סוכ\"ע שנק' שמים משא\"כ כשאין עושין רצונו ש\"מ שותין ממימי אוקיינוס שנק' ג\"כ אוצר כמ\"ש נותן באוצרות תהומות<sup data-n=\"5554\">91</sup> כו'<sup data-n=\"5555\">92</sup>, והיינו דבאהבה דבכל לבבכם נמשך ג\"כ תוס' אורות רק מבחי' עלמא",[["5545","82","<b>ראב\"ד שיצתה נפשו</b>: ע\"ז יז, א. (ולהעיר מסה\"מ תרמ\"ו ע' יט)."],["5546","83","<b>והיו הדברים</b>: ואתחנן ו, ו. ראה גם לעיל ע' תלא ובהערה 32."],["5547","84","<b>ושננתם</b>: ואתחנן שם, ז."],["5548","85","<b>וקשרתם</b>: שם ו, ח."],["5549","86","<b>הוקשה כל התורה כולה לתפילין</b>: ראה קדושין לה, א. סידור ערב שבת קסד, ב. תו\"ח וארא ח\"א סט, ב הערה 423. סה\"מ תרכ\"ט ע' רכה. לקו\"ש חנוכה כרך ה ע' 226."],["5550","87","<b>וקשרתם</b>: עקב יא, יח."],["5551","88","<b>ולמדתם</b>: עקב שם, יט."],["5552","89","<b>מאמר פר\"א כשישראל עושין</b>: ראה גם לעיל ע' תלג ובהערה 64."],["5553","90","<b>יפתח ה' לך</b>: תבוא כח, יב."],["5554","91","<b>נותן באוצרות תהומות</b>: תהלים לג, ז."],["5555","92","<b>כו'</b>: כ\"ה בגוכת\"י."]]],[4801940519,"דאתכסיא שנק' ים לבחי' עלמא דאתגלי' שנק' יבשה<sup data-n=\"5556\">93</sup> ובחי' זאת באה בבחי' פנימי [... ולכן א' שותה שהוא בחי' פנימי. ..], משא\"כ אור הסובב שנק' שמים אינו מאיר רק בבחי' מקיף ומתלבש במעשה המצות בבחי' לבושים שהוא בחי' חיצוני' כנ\"ל וד\"ל.\n<b>והנה</b> לע\"ל כתיב והתהלכתי בתוככם שיהיו ב' מיני הילוך הנ\"ל. והענין הוא למה צריך לב' מיני הילוך הענין כי יש יתרון מעלה בבחי' פנים במה שהגילוי נמשך בבחי' פנימי כנ\"ל אך יש יתרון מעלה בהילוך שבבחי' אחוריים שמזדכך חיצוני' הכלי ביותר כו'. והנה ע\"י ההילוך בבחי' פנים דעכשיו יהי' נמשך לע\"ל בחי' גילוי הסובב בממלא אך ע\"י ההילוך בבחי' אחוריים דעכשיו יהי' לע\"ל עליות הממלא בסובב כו'. [... והיינו זיכוך הכלים דממלא לקבל אור הסובב ע\"ד חנוך ואליהו<sup data-n=\"5557\">94</sup> שעלו למרום<sup data-n=\"5558\">95</sup> כמ\"ש במקומו. ..], ושני הגילויים יהיו לע\"ל [... רק מבואר במ\"א במאמר והתהלכתי תר\"ב<sup data-n=\"5559\">96</sup> שהגילוי דלע\"ל יהי' בבחי' הילוך יותר נעלה והיינו מן המאציל לנאצלים עד שהילוך דעכשיו שהוא מאצי' לבריאה נק' עמידה לגבי הילוך דלע\"ל, אך אעפ\"כ יתגלה ההילוך דלע\"ל בהילוך דעכשיו כו' יעו\"ש. ..]. וזהו שאמר והתהלכתי בתוככם והיינו שיתגלה עצמי' אא\"ס בנשמות שבגופים דייקא והיינו עתידים צדיקים<sup data-n=\"5560\">97</sup> שיאמרו לפניהם קדוש כו' וד\"ל.\n<b>ואולך</b> אתכם קוממיות כו' הוא בחי' מאה אמה<sup data-n=\"5561\">98</sup> והיינו י\"ס מכתר עד המל' דאצי' שהם שלש אמות ושבע כפולות<sup data-n=\"5562\">99</sup> שהם ג\"ר וז\"ת וכ\"א כלול מיו\"ד עולה מאה והיינו מאה אמה [... ומש\"א קוממיות היינו שתי קומות דאו\"י ואור חוזר<sup data-n=\"5563\">100</sup> והכתר כולל בתוכו שתי קומות הנ\"ל וזהו הכף דכתר שכולל ע\"ס דאור ישר וע\"ס דאור חוזר<sup data-n=\"5564\">101</sup> ושניהם יחד יאירו בנש\"י, ואפ\"ל שזהו שני מדריגות דעוה\"ב<sup data-n=\"5565\">102</sup> המוזכר בדברי אדמו\"ר נבג\"מ<sup data-n=\"5566\">103</sup> שהקומה דאור ישר הוא בחי' להנחיל אוהבי יש<sup data-n=\"5567\">104</sup> יש האמיתי והוא עונג המתיישב בכלי והקומה דאור חוזר הוא עונג הבלתי מתיישב בכלי שמצד זה הוא מתחדש בעילוי אחר עילוי וזהו בחי' אין להם מנוחה<sup data-n=\"5568\">105</sup> כו' וד\"ל. ..], אך לכאורה אינו מובן דלפ\"ז לא יאיר בנש\"י רק בחי' מאה אמה שזהו קומת",[["5556","93","<b>עלמא דאתכסיא שנק' ים. . עלמא דאתגלי' שנק' יבשה</b>: ראה גם לעיל ע' פב ובהערה 2."],["5557","94","<b>חנוך. . שעלו למרום</b>: ראה בראשית ה, כד. מאמרי אדה\"א קונטרסים ע' שעב. וש\"נ. תו\"ח בראשית כו, ב ובהערה 16."],["5558","95","<b>ואליהו. . למרום</b>: ראה מל\"ב ב, יא. לקמן מאמר ד\"ה וזכרתי הר\"ת הערה 104."],["5559","96","<b>במאמר והתהלכתי תר\"ב</b>: (נדפס לעיל) בסופו ד\"ה והנה כמו."],["5560","97","<b>עתידים צדיקים</b>: ב\"ב עה, ב."],["5561","98","<b>מאה אמה</b>: ב\"ב עה, א. סנהדרין ק, א. ראה גם לקו\"ש בחוקותי כרך ז ע' 198 ואילך."],["5562","99","<b>שלש אמות ושבע כפולות</b>: ס\"י פ\"א, מ\"ב."],["5563","100","<b>קוממיות. . שתי קומות דאו\"י ואור חוזר</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תרמו. וש\"נ."],["5564","101","<b>הכף. . ע\"ס דאור ישר וע\"ס דאור חוזר</b>: ראה סידור שחרית מו, ג. לעיל ע' קנא ובהנסמן שם."],["5565","102","<b>שני מדריגות דעוה\"ב</b>: ראה גם תו\"ח בשלח רטז, ב ובהנסמן שם. מובא גם בפלח הרמון בשלח ע' קכג."],["5566","103","<b>אדמו\"ר נבג\"מ</b>: כ\"ק אדה\"א."],["5567","104","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["5568","105","<b>אין להם מנוחה</b>: ראה ברכות בסופה. ראה גם תו\"ח שמות ח\"א ד, ג. וש\"נ."]]],[4801940547,"אדה\"ר אחר החטא<sup data-n=\"5569\">106</sup> ובמ\"א מבואר בענין ישכיל עבדי כו' וגבה מאד אותיות אדם<sup data-n=\"5570\">107</sup> ומבואר בס' הקבלה שבנשמת משיח יאיר הבחי' דאדה\"ר כמו שהי' קודם החטא<sup data-n=\"5571\">108</sup>. אך הענין יובן בהקדם מאמר דר' בנאה<sup data-n=\"5572\">109</sup> כו' נסתכלת בדמות דיוקני בדיוקני עצמו אל תסתכל, וענין דיוקני הוא בחי' אדה\"ר כמו שהי' קודם החטא שהוא בבחי' א\"ק<sup data-n=\"5573\">110</sup> כו', אך דמות דיוקני הוא בחי' מל' דא\"ק כמו שמתלבש בבחי' הכתר דאצי' והוא בחי' עתיק כו' ובחי' זאת האירה ביעקב מצד שהתחילו האבות לתקן חטא עה\"ד<sup data-n=\"5574\">111</sup> אך לא ניתקן עדיין בשלימות לזאת לא האירה בו רק דמות דיוקני שהוא בחי' הארה בעלמא מבחי' א\"ק והיינו המל' שבו שהוא בחי' זיו מעצמו' א\"ק אע\"פ שיעקב אע\"ה הוא בחי' נשמה כללי<sup data-n=\"5575\">112</sup>, אך לע\"ל לימות המשיח שיהי' שלימות הבירור לזאת במלך המשיח שהוא נשמה הכללי' לכללות נש\"י כי הוא יהי' בבחי' יחידה<sup data-n=\"5576\">113</sup> לכן בו יאיר בחי' דיוקני עצמו שהוא בחי' אדה\"ר כמ\"ש קודם החטא אך בכל ישראל יאיר בחי' דמות דיוקני הנ\"ל והיינו הכתר עם הפנימי' שבו שזהו בחי' מאה אמה כנ\"ל [... ונמצא שיש הפרש בין אדה\"ר כמו שהי' אחר החטא שלא האיר בו רק מאה אמה שהוא חיצוני' הכתר אך בנש\"י לימות המשיח יאיר בהם בחי' מאה אמה הנ\"ל עם בחי' פנימי' שבו שהוא בחי' עתיק כו' והוא בחי' דמות דיוקני כמו ביעקב אע\"ה כו' וד\"ל. ..]. וגם בחי' זאת הוא למעלה מבחי' משה שהי' קומתו עשר אמות<sup data-n=\"5577\">114</sup> בלבד שהוא ענין שם הוי' עם המילוי<sup data-n=\"5578\">115</sup> שהם עשר אותיות והיינו מחכ' ולמטה כו', אך לימוהמ\"ש יתעלו כל הנשמות לבחי' מאה אמה שהוא בחי' הכתר שלמעלה מהחכ' בפנימי' וחיצוני' כנ\"ל, ובחי' משיח [... שהוא בחי' משה<sup data-n=\"5579\">116</sup> בעצמו כמאמר מה שהי' הוא שיהי'<sup data-n=\"5580\">117</sup>. ..] יאיר בו בחי' אדה\"ר כמו שהי' קודם החטא כנ\"ל וד\"ל. [... ואפשר לומר שאח\"כ יומשך בחי' זאת דאדה\"ר קודם החטא בכללות נש\"י רק שהמשפיע בהם בחי' זאת יהי' ע\"י מלך המשיח כו'. ..].",[["5569","106","<b>מאה אמה. . אחר החטא</b>: ראה חגיגה יב, א כגי' הע\"י. רשב\"ם ב\"ב־ ורש\"י סנהדרין שבהערה 98. מאמרי אדה\"א ויקרא ח\"ב ע' תתפט. וש\"נ."],["5570","107","<b>ישכיל. . מאד אותיות אדם</b>: ישעי' נב, יג. ראה זהר רע\"מ פינחס רמו, ב. ב\"ר פ\"ח, ה. פ\"ט, יב."],["5571","108","<b>משיח. . דאדה\"ר. . קודם החטא</b>: ראה גם לעיל ע' שפז ובהערה 78."],["5572","109","<b>מאמר דר' בנאה</b>: ב\"ב נח, א."],["5573","110","<b>אדה\"ר. . א\"ק</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' טו. וש\"נ. תו\"ח ויקהל ח\"ב שפט, א. וש\"נ."],["5574","111","<b>שהתחילו האבות לתקן חטא עה\"ד</b>: ראה זהר וירא קב, ב. אוה\"ת ר\"ה כרך ו ע' ב'תמג. לקו\"ש תולדות כרך א ע' 56."],["5575","112","<b>שיעקב. . נשמה כללי'</b>: ראה אגה\"ק ס\"ז (קיא, סע\"ב)."],["5576","113","<b>במלך המשיח. . יחידה</b>: ראה גם לעיל ע' שכו ובהערה 10."],["5577","114","<b>משה. . עשר אמות</b>: באוה\"ת כאן ע' תרפב: בשבת בפרק המצניע דצ\"ב ע\"א."],["5578","115","<b>שם הוי' עם המילוי</b>: ראה עבודת הקודש ח\"ד פ\"כ."],["5579","116","<b>משיח. . משה</b>: ראה גם בענין משיח שהוא משה תו\"ח בראשית יג, ב ובהערה 12. שמות ח\"א א, ב. מג, ד. וש\"נ."],["5580","117","<b>מה שהי' הוא שיהי'</b>: קהלת א, ט."]]],[4801940135,"<b>בשברי</b> לכם מטה לחם<sup data-n=\"5581\">1</sup> ואפו עשר נשים לחמיכם<sup data-n=\"5582\">2</sup> כו', פי' בשברי לכם הוא ענין שבירת הלוחות הראשונות שנק' מטה לחם להיות שרשם מעה\"ח<sup data-n=\"5583\">3</sup> שנק' מטה ואח\"כ נתנו לוחות האחרונות באופן אחר והיינו שירדו ונתלבשו עשרת הדברות בבחי' עה\"ד טו\"ר [... וזהו ענין השבירה שהוא ענין הנפילה מדרגי', וע\"ד ששמענו שבדברות דלוחות הראשונות הי' הכוונה לא תרצח<sup data-n=\"5584\">4</sup> ל' גזירה שלא יְמ‘צ א מציאות הרציחה בעולם, וכן הי' כי ההוא אמר ולא יעשה<sup data-n=\"5585\">5</sup>, וזהו שיתבאר אח\"כ שמצד גילוי אור הגדול ממילא נתבררו כל הניצוצות ונכללו בו וממילא נפסק ונתבטל מציאות הרע לגמרי וע\"ד שיהי' לעתיד ואת רוח הטומאה<sup data-n=\"5586\">6</sup> אעביר כו', כך מצד גילוי אור הדיבור דלא תרצח נתברר החיות הנמצא בבחי' הרע דרציחה ונכלל בקדושה וממילא נתבטל מציאות הרציחה, כי אין חיות בלעדו הניצוץ דקדושה המלובש בו, אבל בדברות דלוחות האחרונות הדיבור דלא תרצח הוא ל' ציווי שתשמור א\"ע מרציחה כו'], ועי\"ז גם כל התו' ירדה ונתלבשה בעה\"ד טו\"ר לברר, ולכן מוכרח להיות ואפו כו' כמשי\"ת וד\"ל.\n<b>ולהבין</b> זה יש להקדים שרש ענין הקללות שבתוכחה שבפנימיותם מלובש ברכות והוא ע\"ד שאמרו תלמידי רשב\"י תיר<sup data-n=\"5587\">7</sup> תזרע ולא תחצד<sup data-n=\"5588\">8</sup>, והכוונה תוליד בנין ולא תקבור ייתהון, ולכאורה למה לא אמרו הברכה בגילוי בלי לבוש הפכו, אך הענין הוא שיש שתי בחי' עלמא דאתכסייא ועלמא דאתגלייא, ובחי' עלמא דאתגלייא הוא בבחי' מקום המודד אותו ונמצא שכל ההמשכות שבעלמא דאתגלייא נמדדו כבר במדה ושיעור מהעלם עצמי' המאציל רק שיכול להיות שהמה בהעלם עדיין מצד שלא באו למטה בגשמי' רק המה עדיין ברוחניו' מלובשים בבחי' מקום הרוחני לזאת צריך להמשיכם ע\"י אותיות הברכה מהעלם אל הגילוי, אך המשכה זאת כיון שכבר ישנה בהעלם לכן יכולים להמשיכה בבחי' אותיות אשר המה מעין האור והחיות שבתוכם שהמה אותיות של ברכה כו', אבל בחי' עלמא דאתכסייא אינו בבחי' מקום ולכן ההמשכה משם אינה במדה ושיעור כלל אפי' בבחי' מקום רוחני רק היא כלולה בהעלם עצמי' המאציל ולזאת האור וחיות הנמשך משם א\"א להתלבש בבחי' אותיות אשר המה מעין האור וחיות שבתוכם רק מוכרחים להתלבש בלבוש ההפכי שהוא אותיות דקללה ולכן הלבישו ברכתם בלשון דתזרע כו', מצד שהמשיכו הברכה ממקום היותר נעלה דבחי' עלמא דאתכסייא כו' וד\"ל.",[["5581","1","<b>בשברי לכם מטה לחם</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלמאמר זה ראה מאמר ד\"ה זה בלקו\"ת בחוקותי מח, א ואילך. אוה\"ת שם כרך ד ע' א'קפג ואילך. וראה גם המאמר שנדפס לאח\"ז."],["5582","2","<b>בשברי לכם. . לחמיכם</b>: בחוקותי כו, כו."],["5583","3","<b>מטה לחם. . מעה\"ח</b>: ראה גם (בנוסף להערה 1) לקו\"ת צו יז, ד. לקמן מאמר שלאח\"ז על יד הערה 78."],["5584","4","<b>לא תרצח</b>: יתרו כ, יג."],["5585","5","<b>ההוא אמר ולא יעשה</b>: בלק כג, יט."],["5586","6","<b>ואת רוח הטומאה</b>: זכרי' יג, ב."],["5587","7","<b>תיר</b>: תיבה זו אינה ברורה. ואולי מיותרת."],["5588","8","<b>תזרע ולא תחצד</b>: מוע\"ק ט, ב."]]],[4801940199,"<b>והנה</b> כן הוא עד\"ז בקללות שבתוכחה כי הנה ידוע דאורייתא סתים וגליא<sup data-n=\"5589\">9</sup> כמה דשמא קדישא סתים וגליא, כי קוב\"ה סתים וגליא, וגליא דאורייתא ממשיך גליא דקוב\"ה וסתים דאורייתא ממשיך סתים דקוב\"ה, והנה הברכות שבתורה הוא המשכות התו' עצמה בבחי' גליא שבה ולכן נמשכו באותיות של ל' ברכה בגילוי [... כי מה שא' אם בחוקותי<sup data-n=\"5590\">10</sup> כו' ונתתי גשמיכם<sup data-n=\"5591\">11</sup> כו' ועץ השדה יתן פריו זהו הכל המשכות וגילוי' דתורה אור, כי יש בחי' בתורה שנק' מטר ויש בחי' שנק' עץ השדה ופרי עץ כו'], אבל המשכות סתים דאורייתא הממשיך סתים דקוב\"ה א\"א לבוא באותיות המורים על ל' ברכה בגילוי רק מתלבשים באותיות הקללו' שבתורה, אבל באמת פנימיותם הוא ברכה מאד נעלי' היא<sup data-n=\"5592\">12</sup> ברכות והמשכות סתים דאורייתא שמלובש בזה סתים דקוב\"ה כו' וד\"ל [... והנה כללות ההמשכות המלובשים בקללות שבתורה המה מלובשים בפסוק זה דבשברי לכם<sup data-n=\"5593\">13</sup> כי הוא מדבר בהמשכות כללות סתים דאורייתא ושארי הפסוקים המה פרטי הגילויים בלבד ולכן יש לפרש פסוק זה בפרט וממנו יובן השאר כו'], ויש להבין ענין בשברי לכם דקאי על שבירת הלוחות כנ\"ל והגורם לזה הי' חטא אדה\"ר כמשי\"ת.\n<b>והנה</b> יש להבין ענין חטא אדה\"ר הנה ארז\"ל אילן שאכל אדה\"ר חטה היתה<sup data-n=\"5594\">14</sup>, ולכאורה איך נק' חטה עה\"ד טו\"ר הלא ידוע במנחה חדשה דשבועות<sup data-n=\"5595\">15</sup> שהמה שתי הלחם מחיטים<sup data-n=\"5596\">16</sup> דייקא שהמה מרמזים על המשכות התורה וידוע דאמרת אלוק צרופה<sup data-n=\"5597\">17</sup> ואיך יתכן לקרותה בשם עה\"ד טו\"ר. אך יש להקדים מתחילה ענין הידוע דחטה מאכל אדם ושעורה מאכל בהמה<sup data-n=\"5598\">18</sup>, וזהו שעורה שיעור ה'<sup data-n=\"5599\">19</sup> כי הנה ידוע דבחי' בהמה הוא בחי' שם ב\"ן<sup data-n=\"5600\">20</sup> שהוא בחי' מל'<sup data-n=\"5601\">21</sup> דאצי' מקור המהווה נשמות ומלאכים דבי\"ע, וידוע דהתהוותם הוא בריבוי והתחלקות לאין שיעור כמו מחנה מיכאל קפ\"א<sup data-n=\"5602\">22</sup> כו', וכמאמר אלף אלפין<sup data-n=\"5603\">23</sup> כו' ואין מספר לגדודיו<sup data-n=\"5604\">24</sup>, וידוע שזהו",[["5589","9","<b>דאורייתא סתים וגליא</b>: בלקו\"ת כאן: זהר בפ' אחרי דע\"ג, ע\"א. וראה גם לעיל ע' תלז."],["5590","10","<b>אם בחוקותי</b>: בחוקותי כו, ג."],["5591","11","<b>ונתתי גשמיכם</b>: שם כו, ד."],["5592","12","<b>היא</b>: תיבה זו הוכפלה בהכת\"י."],["5593","13","<b>בפסוק זה דבשברי לכם</b>: ראה גם אוה\"ת כאן ר\"ע א'קפה בשם המדרש. המאמר שנדפס לאח\"ז קרוב לתחילתו."],["5594","14","<b>אילן שאכל אדה\"ר חטה היתה</b>: ברכות מ, סע\"א. ראה גם לעיל ע' שכו. לקו\"ת צו יז, ד. מאמרי אדה\"א במדבר ח\"ב ע' תיח."],["5595","15","<b>במנחה חדשה דשבועות</b>: פינחס כח, כו."],["5596","16","<b>שתי הלחם מחיטים</b>: אמור כג, יז. ראה גם לעיל מאמר ד\"ה והניף הכהן תקפ\"ו בתחילתו."],["5597","17","<b>דאמרת אלוק צרופה</b>: משלי ל, ה."],["5598","18","<b>דחטה מאכל אדם. . בהמה</b>: ראה פסחים ג, סע\"ב. מאמרי אדה\"א במדבר ח\"ב ס\"ע שטז ואילך."],["5599","19","<b>שעורה שיעור ה'</b>: זהר בלק קפח, ב. ראה גם לעיל ע' שסז."],["5600","20","<b>בהמה. . שם ב\"ן</b>: ראה תניא ספמ\"ו. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ."],["5601","21","<b>ב\"ן. . מל'</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ג. שעה\"י קמה, א. הערה 14."],["5602","22","<b>מחנה מיכאל קפ\"א</b>: כנראה הוא ע\"פ מ\"ש בזוהר ח\"ג קנד, א. . וא\"כ צ\"ל כאן: קפ\"ו אלף. . ולא קפיד להעתיק גם מספר המאות שבזוהר שם (סה\"מ ת\"ש ע' 40 בהערה). ולהעיר שכ\"ה גם בכ\"מ ומהם — ראה לעיל ע' רס ובהערה 79. מאמרי אדה\"א ויקרא ח\"א ע' רכד. וש\"נ. הנחות תקע\"ז ע' לד. וש\"נ. תו\"ח שמות ח\"א ל, ב."],["5603","23","<b>אלף אלפין</b>: דניאל ז, י."],["5604","24","<b>ואין מספר לגדודיו</b>: חגיגה יג, ב."]]],[4801940256,"מסיבת ה' גבורות דבנין המל'<sup data-n=\"5605\">25</sup> שהמה מפררים ומחלקים השפע הכללי' האלקי' לריבוי חלקים וכמ\"ש אתה פוררת בעזך<sup data-n=\"5606\">26</sup> כו', ולהיות שהשפע אלקי' בלתי מוגבלת וגם הגבורות המחלקים הוא בחי' כח אלקי לזאת נעשה ריבוי והתחלקות לאין שיעור כו', וכמו שמצינו באותיות הדיבור המתחלקי' מהבל הלב שהוא ע\"י ה' מוצאות הפה<sup data-n=\"5607\">27</sup> כו' וד\"ל.\n<b>אך</b> כ\"ז הוא בחי' ההתהוות שלהם שנמשך מבחי' המל' הנק' בהמה שם ב\"ן אבל החיות שהוא בחי' הביטול שלהם לאלקי' חיים ומלך עולם<sup data-n=\"5608\">28</sup> שבא מצד ההשגה שלהם שמשיגים באלקות הנה שרש ומקור זאת ההשגה הוא מבחי' בינה כי אא\"ס לית מח' תפיסא בי'<sup data-n=\"5609\">29</sup> ואפי' הארתו וזיוו הוא ג\"כ בחי' אלקות בלתי בע\"ג ולא הי' יכולים הנבראים להשיגם כ\"א ע\"י התלבשות בבחי' בינה דאצי' ומשם נמשך לבינה שבמל' מקור השגות הנבראים כו', והנה ההשגה שלהם מוכרח להיות נמשך ג\"כ בבחי' ריבוי והתחלקות בכאו\"א לפ\"ע החומר והכלי שלו שזהו מש\"א נודע בשערים בעלה<sup data-n=\"5610\">30</sup> בכל חד לפום שיעורא דילי'<sup data-n=\"5611\">31</sup> ומזה נמשך ג\"כ בחי' הביטול בכאו\"א לפי מזגו ותכונתו [... ואם הי' נמשך יתר מכפי המדה הי' מתבטלים ממציאותם כענין הושיט אצבעו<sup data-n=\"5612\">32</sup> כו'], וזהו בחי' שעורה שהוא בבינה ונק' שיעור ה' שהוא בחי' ה\"ג המחלקים השפע דבינה ג\"כ כמו הה\"ג שבמל' בכדי שתהי' נמשכת בכאו\"א לפי ערכו [וכידוע דיש בחי' ה\"ג במח' שנק' פיתוחי חותם<sup data-n=\"5613\">33</sup> כמו שיש ה\"ג בדיבור כו'], וזהו ענין מאכל שהוא<sup data-n=\"5614\">34</sup> בחי' חיות כל הנבראים המתהווים מבחי' בהמה רבה שהיא בחי' המל' כו' וד\"ל. אך כ\"ז הוא בחי' ביטול היש בלבד והיינו חיות האלקי הנמשך בכל חד וחד כמו במיכאל באהבה, אכן בחי' חטה הוא בחי' מאכל אדם ושרשה הוא בחי' החכמה<sup data-n=\"5615\">35</sup> כי הנה ידוע דאדם בגי' מ\"ה<sup data-n=\"5616\">36</sup> שהוא בחי' הביטול בעצם שהוא בחי' אין בעצם, וחטה הוא מאכל אדם שממשיך מזון וחיות בנפשו בבחי' מ\"ה שבו לחזקו שיתוסף בו גילוי אור וחיות בכדי שיוכל להיות הביטול בעילוי אחר עילוי כו'.",[["5605","25","<b>ה' גבורות דבנין המל'</b>: ראה גם לעיל ע' רצב ובהערה 17."],["5606","26","<b>אתה פוררת בעזך</b>: תהלים עד, יג. ראה תו\"א מג\"א קכג, א. מאמרי אדה\"א ויקרא ח\"ב ע' תצח. וש\"נ."],["5607","27","<b>ה' מוצאות הפה</b>: ראה גם לעיל ע' שכג ובהערה 46."],["5608","28","<b>לאלקי' חיים ומלך עולם</b>: ע\"פ ברכת יוצר."],["5609","29","<b>לית מח' תפיסא בי'</b>: ראה ת\"ז בהקדמה יז, א."],["5610","30","<b>נודע בשערים בעלה</b>: משלי לא, כג."],["5611","31","<b>לפום שיעורא דילי'</b>: ראה זהר וירא קג, רע\"ב."],["5612","32","<b>הושיט אצבעו</b>: סנהדרין לח, ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' קסא. וש\"נ. תו\"ח שמות ח\"א ל, ב ובהערה 127."],["5613","33","<b>ה\"ג במח' שנק' פיתוחי חותם</b>: ראה גם לעיל ע' רסא ובהערה 84."],["5614","34","<b>שהוא</b>: אוצ\"ל: בהמה שהוא."],["5615","35","<b>חטה. . החכמה</b>: ראה גם קהלת יעקב מערכת חטה ג. תו\"א ויקהל קיד, ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפא. תו\"ח בא ח\"א צה, ג."],["5616","36","<b>דאדם בגי' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א הערה 14."]]],[4801940309,"<b>וביאור</b> הדברים יובן ממארז\"ל שאין התינוק יודע לקרות אבא<sup data-n=\"5617\">37</sup> עד שיטעום טעם דגן, והנה מה שקוראו אותו אבא אינו בהשגה והבנה איך שהוא אביו רק בחי' הכרה בלבד, והכרה זאת היא נמשכת מלמעלה מן הדעת לתוך הדעת והכרה כו', אך הכרה זאת פועלת בו בחי' הביטול מכל וכל להיות נמשך אחרי אביו עד מיצוי נפשו [וכ\"ה בנה\"א בחי' ההכרה וההמשכה לימשך אחרי מקור כל הנשמות שהוא אבינו האמיתי זהו מלמעלה מן הדעת הנמשך ומתלבש בתוך הדעת והכרה והוא הנק' בחי' אמונה שזהו ענין מצה, מיכלא דמהימנותא<sup data-n=\"5618\">38</sup> כו'], וכ\"ה למעלה באדם העליון שעל הכסא שהוא בחי' המדות דאצי' שרש ומקור של הנה\"א שהוא בחי' שם מ\"ה דאצי' הנה מאכל אדם זה שהוא תוס' אור וחיות הנמשך בו מבחי' עצמות אא\"ס ב\"ה [... דלאו מכל אינון מדות כלל<sup data-n=\"5619\">39</sup> ועלי' נאמר כי לא אדם<sup data-n=\"5620\">40</sup> כו'] הוא ע\"י החכ' [... שזהו בחי' מוחין דאבא הנמשך בז\"א] ונק' חטה כו' וד\"ל. אך א\"כ יקשה קושי' הנ\"ל ביותר דכיון דחטה הוא בחי' מוחין דאבא הממשיך חיות בשם מ\"ה דאצי' שהוא בחי' אין בעצם שאין בזה עדיין שום שרש ומקור ליניקת הרע וא\"כ איך נק' עה\"ד טו\"ר כו' וד\"ל. אך באמת יש שני בחי' בחטה כו' הא' בחי' כ\"ב אתוון דאורייתא<sup data-n=\"5621\">41</sup> בגי' חטה<sup data-n=\"5622\">42</sup> שזהו בחי' חכ\"ע מוחין דאבא כנ\"ל, והב' בחי' הנמשכת בבחי' המל' וזהו בחי' חטה חט ה'<sup data-n=\"5623\">43</sup> שח\"ט הוא לשון חסרון<sup data-n=\"5624\">44</sup> ובשבטים לא הי' אותיות ח' ט'<sup data-n=\"5625\">45</sup>, כמו והי' אני ושלמה בני חטאים<sup data-n=\"5626\">46</sup>, וה' חסדים הנמשכים בה אשר שרשם מחכ\"ע בחי' אבא<sup data-n=\"5627\">47</sup>, ובחי' זאת הוא בחי' אילן שאכל אדה\"ר שהוא בחי' עה\"ד טו\"ר, וזה גרם שבירת הלוחות אח\"כ כמשי\"ת.\n<b>וביאור</b> הענין הנה יש להבין ההפרש בין עבודת אדה\"ר לעבודת נשמות הבאים אחרי', כי הנה כמו שיש הפרש בין גוף אדה\"ר שהי' יציר כפיו של הקב\"ה ולא הי' ילוד אשה כלל ובין גופות הבאים אחריו שהמה נולדים מאב ואם כן הוא ההפרש בין נשמת אדה\"ר לנשמות הבאים אחריו, שנשמת אדה\"ר הוא מבחי'",[["5617","37","<b>שאין התינוק יודע לקרות אבא</b>: ראה ברכות מ, סע\"א. מאמרי אדה\"א דברים ח\"א ע' רמה. וש\"נ. תו\"ח בא ח\"א צה, ב. וש\"נ. לעיל ע' קה ובהערה 54."],["5618","38","<b>מצה מיכלא דמהימנותא</b>: ראה זהר רע\"מ בא מא, א. מאמרי אדה\"א ויקרא ח\"ב ע' תרלו. וש\"נ."],["5619","39","<b>דלאו מכל אינון מדות כלל</b>: ראה ת\"ז בהקדמה יז, ב."],["5620","40","<b>כי לא אדם</b>: שמו\"א טו, כט."],["5621","41","<b>בחטה. . כ\"ב אתוון דאורייתא</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, א. ב)."],["5622","42","<b>כ\"ב. . בגי' חטה</b>: ראה ת\"ז שם. פע\"ח שער חג השבועות שכ\"ג, פ\"א. טעמי המצות להאריז\"ל ר\"פ אמור. לקו\"ת שה\"ש כז, ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפא."],["5623","43","<b>חטה חט ה'</b>: ראה זהר רע\"מ תצא ערה, ב."],["5624","44","<b>שח\"ט הוא לשון חסרון</b>: ראה [בנוסף להערה 46] ס' שופטים כ, טז. מאמרי אדה\"א דברים ח\"ג ע' תתקיד. וש\"נ. נ\"ך ע' נא. סה\"מ תרל\"ב ח\"א ע' קמד. המשך תער\"ב ח\"ג ע' א'תנט."],["5625","45","<b>ובשבטים לא הי' אותיות ח' ט'</b>: ראה יומא עג, ב. זהר בהקדמה ג, א. תרומה קנב, א. בלק קפח, ב. לקו\"ת אמור לו, ג ואילך. סה\"מ תרכ\"ז ע' שלח וע' שלט. תרכ\"ט ס\"ע רמג ואילך."],["5626","46","<b>והי' אני ושלמה בני חטאים</b>: מל\"א א, כא [ושם: והייתי אני ובני שלמה]."],["5627","47","<b>וה' חסדים. . בחי' אבא</b>: ראה לקו\"ת אמור לו, ד."]]],[4801940359,"עלמא דדכורא בלי השתתפות מבחי' הנוק' כי נמשך בשרשו מאדם העליון שם מ\"ה ז\"א דאצי' ולכן כל עבודתו הי' בחי' ביטול עצמי לאא\"ס ונתעלה בבחי' ביטול זה בכל עת ורגע בעילוי אחר עילוי וביטול ועבודה זאת הוא בחי' העלאת מ\"ן שהי' מעורר בתמידות המשכת מ\"ד מלמעלה, וזהו כברא דמתחטא לקמי' אבוהי ועביד לי' רעותי'<sup data-n=\"5628\">48</sup> שפי' מתחטא הוא מתגעגע שהוא בחי' ביטול בעילוי אחר עילוי, וביטול זה גורם המשכת מ\"ד שזהו ועביד לי' רעותי', והנה אם לא הי' חוטא הנה הבירורים שלו הי' ג\"כ ממילא ומאיליו מצד שהי' פועל בביטול שלו המשכת אא\"ס בעילוי אחר עילוי ממילא היו נמשכים כל הניצוצות שנפלו למטה [בשבירת הכלים] והי' מתעלים בשרשם וכמשל האבוקה הגדולה שבהארתה נמשכים כל הניצוצים שיש בו וניכללים בה כו', ונמצא שעבודתו בקודש הי' למעלה מבחי' תורה דעכשיו [... רק ע\"י בחי' תו' הנק' עה\"ח] ולכן נק' אדם קדמאה<sup data-n=\"5629\">49</sup> מצד ששרשו בבחי' חכמה עילאה שמאיר בה בחי' הארת האין בעצם מצד שהוא בחי' ראשית הגילוי מאין כך הי' מאיר בו בחי' חכמה מ\"ה בעצם שהוא בחי' אין בעצם כו'. והנה גם השבטים לא הי' בהם אותיות ח\"ט מצד שרשם בז\"א שאין בזה תערובות מבחי' עה\"ד [כי ז\"א נק' אילנא דחיי<sup data-n=\"5630\">50</sup> כו']. והנה כ\"ז הוא בחי' נשמת אדה\"ר אבל נשמות הבאים אחריו כמו שגופם נולד מאב ואם בגשמיות כן שרש נשמתם למעלה הוא מבחי' ז\"א ונוק' ומצד בחי' זאת דנוק' שבהם המה באים בבחי' התלבשות למטה בעה\"ד טו\"ר דנוגה בכדי לברר בירורים, ולכן כל עבודתם והילוכם בקודש מוכרח להיות ע\"י בירור ודחי' הרע והפסולת ואח\"כ יוכלו לעלות בבחי' העלאת מ\"ן, וזהו כברתא דמתחטא לקמי' אבוהי ועביד לה רעותה שפי' דמתחטא ל' חסרון כנ\"ל שזהו בחי' בירור ודחי' הרע ואח\"כ יהי' ההעלאה, והעלאה זאת גורם המשכת מ\"ד שזהו ועביד לה רעותה כו'. וזהו חטה ח\"ט ה' שח\"ט הוא לשון חסרון שהוא בחי' העלי' ע\"י בירור ודחיות הרע בתחילה וה' הוא בחי' ה\"ח דאבא הנמשכים אח\"כ בבחי' המשכת מ\"ד כו' וד\"ל [והנה זהו הי' חטא אדה\"ר שאכל מעה\"ד ונשפל להתלבש בבחי' הרע דנוגה עד שמחמת זה מוכרח לברר בבחי' התלבשות בדבר המתברר ולדחות הרע משא\"כ מתחילה הי' הבירור שלו ממילא ומאיליו מצד הילוכו בקודש בבחי' ביטול כנ\"ל ולא הי' צריך להתלבש בדבר המתברר כו'].\n<b>והנה</b> מחמת חטא אדה\"ר שגרם התלבשות כל הנשמות בנוג\"ה צ\"ל ג\"כ ירידת התורה ג\"כ להתלבש בדבר המתברר, כי עיקר הבירור דנשמות הוא ע\"י חכמה שבתורה כמאמר בחכמה אתברירו<sup data-n=\"5631\">51</sup>, וזהו ענין שבירת הלוחות שזהו ירידת אור הלוחות מכמו שהי' בתחילה בבחי' עה\"ח להתלבש בבחי' עה\"ד טו\"ר שזהו ענין לוחות אחרונות ולכן הבירור דעכשיו מוכרח להיות ע\"י בירור הרע, ואח\"כ העלאת",[["5628","48","<b>כברא דמתחטא. . רעותי'</b>: לקמן: ברתא — וכ\"ה בזהר בלק קפח, ב. לקו\"ת אמור לו, ג ואילך. אוה\"ת משלי כרך א ע' תרמט."],["5629","49","<b>אדם קדמאה</b>: ת\"ז ת\"ע (קכ, א). זהר בראשית לא, ב. לד, א."],["5630","50","<b>ז\"א נק' אילנא דחיי</b>: ראה ע\"ח שער דרושי הצלם שכ\"ה, דרוש השלישי. שער הקליפות שמ\"ח, פ\"ב. פלח הרמון בשלח ע' קמ."],["5631","51","<b>בחכמה אתברירו</b>: ראה זהר היכלות פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. תו\"ח תשא ח\"ב שפד, ד ואילך."]]],[4801940405,"מ\"ן לגרום המשכת מ\"ד. וזהו שבחי' מעשרות שהוא בחי' העלאה העשירי יהי' קודש<sup data-n=\"5632\">52</sup> שזהו בחי' ההעלאה מכל הט' חלקים לקודש העליון, מוכרח להיות ע\"י דחי' הפסולת ובירור הרע מתחילה שזהו ענין המירוח דמוץ ותבן כו' וד\"ל. וזהו בשברי לכם מטה לחם שהוא בחי' שבירת לוחות הראשונות וניתנו לוחות האחרונות [שמסיבה זאת הי' ירידת אור מבחי' עה\"ח להתלבש בעה\"ד טו\"ר כנ\"ל], אך אעפי\"כ הוא בחי' לחם המחי' לנפש האדם כי כמו שהלחם אע\"פ שהוא למטה בגשמי' יותר מבחי' האדם כי הוא בחי' צומח והאדם בחי' מדבר ואעפי\"כ כשמתברר ומתעלה לשרשו שהוא למעלה משרש נפש האדם [שהוא בחי' התהו שקדם לתיקון<sup data-n=\"5633\">53</sup> לפני מלך מלך<sup data-n=\"5634\">54</sup> כו'], הוא מחי' לנפש האדם, כ\"ה בחי' התורה שאע\"פ שירדה למטה להתלבש בגשמיות דעה\"ד טו\"ר אעפ\"כ כשהאדם לומד אותה מתעלי' לשרשה [... בחי' ואהי' אצלו אמון<sup data-n=\"5635\">55</sup>, אצלו ממש כו'] ומחי' לשרש נשמת האדם, כמאמר כי אמרתך חייתני<sup data-n=\"5636\">56</sup>. אך צ\"ל ואפו עשר נשים לחמיכם פי' כמו שהלחם הגשמי א\"א להיות מחי' לנפש האדם כ\"א ע\"י שיתברר ויתעלה מתחילה מבחי' צומח לבחי' מדבר והיינו ע\"י שנעשה דם כדמו ובשר כבשרו כו' ואח\"כ הוא מחי' כו', אך א\"א לו להתברר ולהתאחד כ\"א ע\"י האפי' בתחילה משא\"כ בעודו עיסה לא יתאחד עמו, כן הוא בחי' התורה הנק' לחם<sup data-n=\"5637\">57</sup> מתחילה צריכה להתברר ולהתעלות ע\"י נפש האדם הלומד אותה ואח\"כ הוא מחי' אותו מצד שרשה שהיא למעלה משרש נה\"א, אך הבירור הוא ע\"י האפי' דייקא שזהו לימוד התורה באהבה ויראה<sup data-n=\"5638\">58</sup>, וענין האהבה הוא מס\"נ באחד<sup data-n=\"5639\">59</sup> לצאת מגדרי הכלי לא לחפוץ בשום דבר גשמי ורוחני רק להיות כלה שארי ולבבי<sup data-n=\"5640\">60</sup> לו לבדו ועי\"ז מתברר ונדחה כל מיני רע בנפש ואח\"כ לימוד התורה נעשה ג\"כ בירור הרע ועלי' הטוב בבחי' עולם<sup data-n=\"5641\">61</sup> לגרום המשכת מ\"ד להיות כי אמרתך חייתני כנ\"ל.\n<b>והנה</b> שרש אהבה זאת הוא בחי' רשפי אש ושרשה מבחי' התורה שניתנה אש שחורה ע\"ג אש לבנה<sup data-n=\"5642\">62</sup>, אך אהבה זאת מסותרת וצריך לעוררה מהעלם אל הגילוי ע\"י המוחין כו' בתפילה כו', וזהו ואפו עשר נשים שהוא בחי' הנשמות מעלמא דנוק', ועשר נשים הוא בחי' עשר כחות<sup data-n=\"5643\">63</sup> הנפש מוחין ומדות, ועי\"ז מתבררים מדות",[["5632","52","<b>העשירי יהי' קודש</b>: לשון הכתוב בחוקותי כז, לב."],["5633","53","<b>התהו שקדם לתיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ."],["5634","54","<b>לפני מלך מלך</b>: וישלח לו, לא."],["5635","55","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["5636","56","<b>כי אמרתך חייתני</b>: תהלים קיט, נ."],["5637","57","<b>התורה הנק' לחם</b>: ראה שבת קכ, א. לקו\"ש בהעלותך כרך ד ע' 1038 הערה 26. תניא פ\"ה ובמ\"מ הגהות והע\"ק לשם. סה\"מ תרכ\"ז ע' קמט. וש\"נ. וראה גם בהמאמר שנדפס לאח\"ז פיסקא והנה מתחלה."],["5638","58","<b>האפי'. . באהבה ויראה</b>: ראה לקו\"ת כאן בחוקותי מח, ג."],["5639","59","<b>מס\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["5640","60","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["5641","61","<b>עולם</b>: כ\"ה בהכת\"י."],["5642","62","<b>אש שחורה ע\"ג אש לבנה</b>: ראה רש\"י שה\"ש ה, טז ד\"ה שחורות. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תקעח."],["5643","63","<b>ועשר נשים. . עשר כחות</b>: ראה גם לקו\"ת כאן מח, ג."]]],[4801940448,"דנה\"ט כו' ואח\"כ לימוד התורה שהוא הבירור דעה\"ד בבחי' עולם למהוי אחד באחד<sup data-n=\"5644\">64</sup> היינו שיתאחד עה\"ד בעה\"ח ואז ממילא יומשך מה שלמעלה משניהם להיות תוס' אור בעה\"ח ועה\"ד כו' וד\"ל. וזהו בתנור אחד<sup data-n=\"5645\">65</sup> כו' למהוי אחד באחד. וזהו ג\"כ הסדר מפסח לעצרת וכמארז\"ל בפסח על התבואה<sup data-n=\"5646\">66</sup> בעצרת על פירות האילן, כי בפסח נמדד החיות בבחי' התגלות המוחין ומדות שבנה\"א [עיין בענין וספרתם תבין כל הנ\"ל], ואח\"כ קציר העומר בירור דנה\"ט לפ\"ע גילוי הכחות דנה\"א, ואז מתעלה למהוי אחד באחד, ואז נמשך אח\"כ גילוי חדש בעה\"ח ועה\"ד וזהו בעצרת על פירות האילן כו' וד\"ל. והנה אח\"כ<sup data-n=\"5647\">67</sup> הבירור דלמהוי אחד באחד אז והשיבו לחמיכם במשקל<sup data-n=\"5648\">68</sup> שנתעלו ב' בחי' דעה\"ח ועה\"ד בבחי' הנק' מתקלא בזוהר<sup data-n=\"5649\">69</sup>, וזהו ושקל בפלס הרים<sup data-n=\"5650\">70</sup> כו', ואח\"כ ואכלתם ולא תשבעו<sup data-n=\"5651\">71</sup> כי הנה ארז\"ל בכל יום יהי' בעיניך כחדשים<sup data-n=\"5652\">72</sup> שזהו כאשר מתגלה בחי' סתים דאורייתא כנ\"ל ושרש כו'<sup data-n=\"5653\">73</sup> הוא מבחי' שלמעלה מהזמן וכמאמרם מי איכא זקנה קמי'<sup data-n=\"5654\">74</sup> ולזאת אינו מתישן ולא יפול ענין השביעה כלל כו' וד\"ל [... והנה זהו כללות המכון דשבירת הלוחות להתלבש בעה\"ד טו\"ר שמוכרח להיות בזה התלבשות סתים דאורייתא שהוא ענין המאור שבה, ועי\"ז אחר הבירור יתגלה בחי' המאור למעלה מגילוי אור דעה\"ח כו' וד\"ל].",[["5644","64","<b>למהוי אחד באחד</b>: זהר תרומה קלה, סע\"א."],["5645","65","<b>בתנור אחד</b>: ראה גם לקו\"ת בחוקותי נ, א."],["5646","66","<b>בפסח על התבואה</b>: ר\"ה טז, א (במשנה)."],["5647","67","<b>אח\"כ</b>: כנצ\"ל: אחר."],["5648","68","<b>והשיבו לחמיכם במשקל</b>: המשך הכתוב בשברי לכם מטה לחם."],["5649","69","<b>מתקלא בזוהר</b>: ראה הנסמן בלקו\"ת כאן מח, ג."],["5650","70","<b>ושקל בפלס הרים</b>: ישעי' מ, יב."],["5651","71","<b>ואכלתם ולא תשבעו</b>: המשך הכתוב בשברי לכם מטה לחם."],["5652","72","<b>בכל יום יהי' בעיניך כחדשים</b>: ראה לקח טוב ואתחנן ו, ו. מאמרי אדה\"א דברים ח\"א ע' רסו ואילך. וש\"נ. לעיל ע' קמב הערה 14."],["5653","73","<b>כו'</b>: תיבה זו איננה ברורה."],["5654","74","<b>מי איכא זקנה קמי'</b>: ראה יבמות טז, ב. מאמרי אדה\"א קונטרסים ע' צב ד\"ה והנה. שעה\"י קפו, ג. שע\"ת כט, ב. תו\"ח תולדות קנג, א הערה 9. מאמר שנדפס לאח\"ז בסופו."]]],[4801940136,"<b>תו' אדמו\"ר נבג\"מ שא' יום ש\"ק פ' בחוקתי לסעודה ג' תקצטי\"ת בליבאוויץ</b>\n<b>בשברי</b> לכם מטה לחם<sup data-n=\"5655\">1</sup> ואפו עשר נשים לחמיכם בתנור אחד והשיבו לחמיכם במשקל ואכלתם ולא תשבעו<sup data-n=\"5656\">2</sup>. הנה כתי' שמע בני מוסר אביך וא' בזוהר מוסר אביך דא קוב\"ה<sup data-n=\"5657\">3</sup> פי' שהמוסר והתוכחות שבתורה אע\"פ שבגילוי המה תוכחות",[["5655","1","<b>בשברי לכם מטה לחם</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלכמה ענינים במאמר זה ראה גם המאמר שנדפס לפנ\"ז ובהנסמן שם.\nביאור על דרוש זה שנאמר בליל ה' פ' במדבר יודפס בעזה\"י בפלח הרמון במדבר."],["5656","2","<b>בשברי לכם. . ואפו. . והשיבו. . ולא תשבעו</b>: בחוקותי כו, כו."],["5657","3","<b>שמע בני. . אביך דא קוב\"ה</b>: משלי א, ח. זהר יתרו פה, א."]]],[4801940200,"ויסורים מ\"מ בפנימיותם הם תוקף הרחמים, וזהו מוסר אביך שמוסר שבתורה נמשך מבחי' אב הרחמים [ועד\"מ אב המייסר את בנו שמושל על אהבתו אליו בטבעו שחפץ להיטיב אליו ולקרבו, אך מצד הרחמים על הבן שרוצה להדריכו בדרך ישרה שנלקחה מעצמי' האהבה כמ\"ש בעצמי' נפשו שיש לו אל הבן למעלה מבחי' טבע שהוא בחי' חיות הנפש המלובש בגוף ולכן מושל ברוחו<sup data-n=\"5658\">4</sup> ומלביש אהבתו אליו בדרך ההפכי ומנגד לאהבה שהוא ענין ההכאות ויסורין, וע\"ד הקבלה עצמי' האהבה לנש\"י המלובש בכללות התורה אם בחוקתי תלכו<sup data-n=\"5659\">5</sup> כו' הוא מבחי' חסד דע\"י המלובש בגולגלתא<sup data-n=\"5660\">6</sup> שרש הברכה<sup data-n=\"5661\">7</sup> ה' חסדים המתפשטים למטה לצורך זו\"נ, ושרש האהבה המלובשת בתוכחות שבתורה הוא מבחי' גבורות דע\"י המלובש בח\"ס<sup data-n=\"5662\">8</sup> שרש ה\"ג המתפשטים למטה כו', ושרש הגבורות הללו יש בהם יתרון שנלקחים מפנימי' החסד והטוב כמו שהוא בשרשו בבחי' אוא\"ס למעלה מבחי' הלבשה בגולגלתא כו' כי פי' גבורות במקום גבוה כזה הוא תגבורת<sup data-n=\"5663\">9</sup> החסד והטוב ולא בבחי' צמצומים כמאמר הזוה\"ק לית שמאלא בהאי עתיקא<sup data-n=\"5664\">10</sup> כו', ובחי' גבורות המה מקור י\"ג מדה\"ר וכשנמשכים בבחי' חכמה עילאה פרצוף אבא נק' אז בשם אב הרחמים ולמטה נמשך מזה התוכחה שבתורה ואם לא תשמעו<sup data-n=\"5665\">11</sup> כו'], ולכן כל התוכחות יש בהם בחי' חיצוני' ופנימי' שמצד חיצוניותם הם בחי' דין [שהמה ה\"ג הנמשכים מבחי' ז\"א למל' להיות מלך במשפט יעמיד ארץ<sup data-n=\"5666\">12</sup> כו'] אבל מצד פנימיותם המה תוקף הרחמים [מצד שרשם בה' גבורות דע\"י, טובה תוכחת מגולה<sup data-n=\"5667\">13</sup> כו'], ולכן א' שמע בני מוסר אביך פי' שתשמע שהפנימי' המלובש במוסר אביך שהוא תכלית החסד והרחמים כו' וד\"ל [והנה כללות הטוב והחסד והרחמים המלובשים בתוכחות שבתורה הוא מלובש בפ' זה דבשברי לכם<sup data-n=\"5668\">14</sup> כו' ולכן יש לפרשו, וממנו יובן כל פרטי הגילויים המבוארים בשארי פסוקים שבתוכחה כו'].\n<b>והנה</b> מתחלה יש להבין מה שהתורה נק'<sup data-n=\"5669\">15</sup> בשם לחם כמ\"ש לכו לחמו בלחמי<sup data-n=\"5670\">16</sup> וכן את קרבני לחמי<sup data-n=\"5671\">17</sup> מה ענינה ולמה בשם לחם ולמי הוא נעשה בחי' לחם ופרנסה, הנה כתיב בטח בה' כו' ורעה אמונה<sup data-n=\"5672\">18</sup> היינו לזון ולפרנס את האמונה",[["5658","4","<b>ברוחו</b>: א: בגופו."],["5659","5","<b>אם בחוקותי תלכו</b>: בחוקותי כו, ג."],["5660","6","<b>חסד דע\"י המלובש בגולגלתא</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ו ופ\"ז."],["5661","7","<b>הברכה</b>: א: ליתא."],["5662","8","<b>גבורות דע\"י המלובש בח\"ס</b>: ראה ע\"ח שם."],["5663","9","<b>גבורות. . תגבורת</b>: ראה תו\"א נח ט, ג. סה\"מ תרכ\"ז ס\"ע רמט. וש\"נ. לקו\"ש תולדות כרך ל ע' 108. וש\"נ."],["5664","10","<b>לית שמאלא בהאי עתיקא</b>: ראה זהר אד\"ר נשא קכט, א. ע\"ח שער עתיק שי\"ב, פ\"ב. שער הארת המוחין של\"ב, פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."],["5665","11","<b>ואם לא תשמעו</b>: בחוקותי כו, יד."],["5666","12","<b>מלך במשפט יעמיד ארץ</b>: משלי כט, ד."],["5667","13","<b>טובה תוכחת מגולה</b>: משלי כז, ה."],["5668","14","<b>בפ' זה דבשברי לכם</b>: ראה גם המאמר שלפני זה ובהערה 13."],["5669","15","<b>מה שהתורה נק'</b>: א: כללות התו' שנק'."],["5670","16","<b>לכו לחמו בלחמי</b>: משלי ט, ה. וראה גם המאמר שלפנ\"ז הערה 57."],["5671","17","<b>את קרבני לחמי</b>: פינחס כח, ב."],["5672","18","<b>בטח בה' כו' ורעה אמונה</b>: תהלים לז, ג. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תריט ואילך. וש\"נ."]]],[4801940257,"להיות כי האמונה שבכללות נש\"י נק' בשם עטרה<sup data-n=\"5673\">19</sup> להיותה בבחי' מקיף וא\"א לה להתגלות בבחי' פנימי' בנר\"נ שבנפש ומכ\"ש בנה\"ט ולכן גנבא אפום מחתרתא רחמנא קרי'<sup data-n=\"5674\">20</sup> כי אע\"פ שיש לו אמונה זאת בתקפה מ\"מ עושה היפוך רצונו מחמת שהוא בבחי' מרחוק אצלו, והטעם להיותה בחי' אלקות למעלה מן הדעת ולזאת א\"א לה לבוא לתוך דעת והכרה [כי הוא בחי' ניצוץ אלקי שבנפש שנלקחה בשרשה מבחי' מל' דאצי' מקור נש\"י<sup data-n=\"5675\">21</sup> שמרומם בערך מבחי' נר\"נ דבי\"ע כו'] לזאת צריך לזון ולפרנס אמונה זאת להוסיף בה כח ועוז שתוכל להתגלות בנר\"נ בבחי' פנימי' עד שתעשה בבחי' מזון וחיות לנר\"נ כמאמר וצדיק באמונתו יחי'<sup data-n=\"5676\">22</sup> [ולכן ורעה אמונה יוכל לפרש בו ב' פי' הא' שתזון ותפרנס את האמונה והב' שתזון ותפרנס את נפשך עם האמונה, והא בהא תלי' כי ע\"י הפרנסה שמפרנסין לבחי' האמונה ניצוץ האלקי עי\"ז תוכל להיות נמשך בבחי' מזון וחיות בנפש כו' וד\"ל], שזהו מה שממשיכים בחי' הדעת בנפש מלמעלה מן הדעת כי הנה ענין הדעת הוא בחי' מחבר חכ' לבינה<sup data-n=\"5677\">23</sup> ובחי' חכ' הוא בחי' ראי' מקרוב שנתפס אלקות בבחי' קירוב בנפש אבל בחי' בינה הוא בחי' שמיעה<sup data-n=\"5678\">24</sup> מרחוק שמרחוק ה' נראה לו<sup data-n=\"5679\">25</sup> שאין נתפס אלקות אצלו בכחות נפשו בבחי' קירוב [רק בניצוץ האלקי בבחי' האמונה כו' וד\"ל], אבל ע\"י הדעת נמשך ונתגלה בחי' חכ' שבנפש בכל כחות הנפש, עד שיהי' נתפס אלקות בבחי' קירוב בכל כחות הנפש מבינה ולמטה, והמשכת הדעת הוא תלוי בבחי' מזון [כמאמר אין התינוק יודע לקרות אבא<sup data-n=\"5680\">26</sup> עד שיטעום טעם דגן כו'] הנמשך בעצמי' הנפש הנק' אמונה ע\"י התורה שהוא ענין שתי הלחם תושב\"כ ותושבע\"פ<sup data-n=\"5681\">27</sup> והוא ג\"כ ענין חט\"ה כ\"ב אתוון דאורייתא<sup data-n=\"5682\">28</sup>. אך אע\"פ שהתורה נעשה בחי' מזון לנפש מ\"מ מצד מזון התומ\"צ בלבד לא הי' ביכולת האמונה עדיין להיות נמשך בבחי' פנימי' דדעת והכרה אם לא ע\"י מזון העולה מלמטה למעלה שהוא בחי' העבודה דקרבנות שנק' לחמי וכן תפלה במקום קרבן<sup data-n=\"5683\">29</sup> ולזאת עיקר גילוי הדעת הוא בתפלה דייקא, ולכן בשחר כשקם אומר מודה אני<sup data-n=\"5684\">30</sup> כו' כי האמונה לא נתגלה עדיין רק בבחי'",[["5673","19","<b>האמונה. . עטרה</b>: ראה מאמרי אדה\"ז הקצרים ע' תסט. וש\"נ. שה\"א ו, א ובהערה 10. תו\"ח משפטים ח\"ב רפ, ב."],["5674","20","<b>גנבא אפום מחתרתא רחמנא קרי'</b>: ראה ברכות סג, א ע\"פ גי' הע\"י. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' ט."],["5675","21","<b>מל'. . מקור נש\"י</b>: ראה גם לעיל ע' קמג ובהערה 18."],["5676","22","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד."],["5677","23","<b>הדעת. . מחבר חכ' לבינה</b>: ראה גם לקו\"ת להאריז\"ל שמות ג, ד. לקו\"ת מטות פו, ב. ד. פז, ג. נשא כב, ב. כח, א. תו\"א משפטים עה, א. ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תערב. מאמר ד\"ה הוא הי' אומר תרל\"א [קונט' בר מצוה תרנ\"ג ע' לו ובהערה 31]."],["5678","24","<b>חכ'. . ראי'. . בינה. . שמיעה</b>: ראה תו\"א וירא טו, ד. מקץ מ, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' רפז. תקס\"ט ע' פט. שער האמונה מג, ב. תו\"ח שמות ח\"א כז, ג הערות 15-16."],["5679","25","<b>שמרחוק ה' נראה לו</b>: ע\"פ ירמי' לא, ב."],["5680","26","<b>אין התינוק יודע לקרות אבא</b>: ראה ברכות מ, סע\"א. מאמרי אדה\"א דברים ח\"א ע' רמה. וש\"נ. תו\"ח בא ח\"א צה, ב. וש\"נ. לעיל ע' קה ובהערה 54."],["5681","27","<b>שתי הלחם תושב\"כ ותושבע\"פ</b>: ראה זח\"א השמטות רס, א."],["5682","28","<b>חט\"ה כ\"ב אתוון דאורייתא</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, א. ב)."],["5683","29","<b>תפלה במקום קרבן</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["5684","30","<b>בשחר כשקם אומר מודה אני</b>: ראה שו\"ע אדה\"ז חאו\"ח מהדו\"ק ס\"א, ס\"ה. מהדו\"ת ס\"א, ס\"ו. סידור אדה\"ז במקומו. נדפס גם בהוספות לשו\"ע קה\"ת שם ע' קנג."]]],[4801940310,"הודאה ולכן בתחלת סדר התפלה או' הודו להוי'<sup data-n=\"5685\">31</sup> אבל בשמ\"ע או' ברוך אתה ה' שנעשה מבחי' הודאה בחי' ברכה והמשכה בגילוי שהוא כשבא האמונה בבחי' דעת בקירוב וזהו הכל<sup data-n=\"5686\">32</sup> ענין ג' דברים דתורה ועבודה וגמ\"ח שכללותם הוא בחי' מזון לפרנס את האמונה כו' וד\"ל.\n<b>וביאור</b> הדברים ילה\"ק ענין כי תשא<sup data-n=\"5687\">33</sup> כו' ונתנו איש כופר נפשו לה' כו', זה יתנו<sup data-n=\"5688\">34</sup> מחצית השקל תרומה להוי', כי הנה בזמן שבהמ\"ק הי' קיים<sup data-n=\"5689\">35</sup> היו נותנים מחצית השקל שהוא עשרה גרה כסף נקי לתרומת הלשכה<sup data-n=\"5690\">36</sup> וממנו היו לוקחים הקרבנות<sup data-n=\"5691\">37</sup> והקרבנות היו מקריבים ע\"ג המזבח ונשרפים באש שלמעלה שהוא ארי' דאכיל קורבנין<sup data-n=\"5692\">38</sup> ומזה הי' נעשה לחם למעלה כמ\"ש את קרבני לחמי לאשי כו', והנה כ\"ז הוא עכשיו בתפלה במקום קרבן כי הנה ענין כסף הוא בחי' האהבה<sup data-n=\"5693\">39</sup> שבכאו\"א אשר יש לו תשוקה ליכלל באלקים חיים ומלך עולם<sup data-n=\"5694\">40</sup> כמ\"ש נכספה וגם כלתה נפשי<sup data-n=\"5695\">41</sup> לחצרות הוי' ולזאת האה' נק' כסף מלשון נכסוף נכספתי<sup data-n=\"5696\">42</sup>, והנה באהבה זאת יש שני בחי' הא' בחי' האהבה שבנשמה שהו\"ע ההתקשרות מלמטה למעלה שזהו בחי' בנימין צדיק תחתון<sup data-n=\"5697\">43</sup> ימין מקרבת<sup data-n=\"5698\">44</sup>, והב' בחי' אהבה עליונה מבחי' הקב\"ה לנש\"י והוא ממשיך בחי' אהבתו ג\"כ בנש\"י ע\"י יוסף צדיק עליון<sup data-n=\"5699\">45</sup> וכמ\"ש צדיק הוי' בכל דרכיו<sup data-n=\"5700\">46</sup> כו', ואהבה זאת נמשך באהבה שבנשמה לפעול בחי' התעוררות התשוקה בתמידות שתהי' בלתי הפסק כלל ונק' רוחא קדמאה דשביק בה<sup data-n=\"5701\">47</sup> כו' והוא ג\"כ ענין גביע הכסף אשר שם יוסף צדיק עליון [יסוד ז\"א<sup data-n=\"5702\">49</sup> דאצי'] באמתחת בנימין<sup data-n=\"5703\">48</sup> צדיק תחתון. והנה בחי' אהבה זאת הנק' כסף מצד",[["5685","31","<b>הודו להוי'</b>: דהי\"א טז, ח. ראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת ובהערה 36."],["5686","32","<b>הכל</b>: א: בכל. וראה לקמן בפנים על יד הערה 69."],["5687","33","<b>כי תשא</b>: תשא ל, יב."],["5688","34","<b>זה יתנו</b>: תשא שם, יג [בדילוג]."],["5689","35","<b>מחצית השקל. . בזמן שבהמ\"ק הי' קיים</b>: ראה רמב\"ם הל' שקלים פ\"א, ה\"ח."],["5690","36","<b>לתרומת הלשכה</b>: ראה רמב\"ם שם פ\"ב, ה\"ד."],["5691","37","<b>וממנו היו לוקחים הקרבנות</b>: ראה רמב\"ם שם פ\"ד, ה\"א. רש\"י תשא ל, טו."],["5692","38","<b>ארי' דאכיל קורבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שער האמונה עט, ב הערה 13."],["5693","39","<b>כסף. . האהבה</b>: ראה גם תניא פ\"נ. תו\"א וישב כו, ד. תשא פו, ד. תו\"ח וארא ח\"א נג, ג. וש\"נ."],["5694","40","<b>באלקים חיים ומלך עולם</b>: ע\"פ ברכת יוצר."],["5695","41","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["5696","42","<b>נכסוף נכספתי</b>: פיוט ”ידיד נפש\". ויצא לא, ל: נכספתה — ראה מאמרי אדה\"א במדבר ח\"ב ע' תתסב בהערה. תו\"א תשא קיא, ד. סה\"מ תרל\"ב ח\"א ע' ע. תער\"ב ח\"ב ע' תתב. ע' תתלח."],["5697","43","<b>בנימין צדיק תחתון</b>: ראה זהר ויצא קנג, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתצה ובהנסמן במ\"מ לשם. מאמרי אדה\"א שמות ח\"ב ע' שצא. וש\"נ."],["5698","44","<b>ימין מקרבת</b>: סוטה מז, א."],["5699","45","<b>יוסף צדיק עליון</b>: נסמן בהערה 43."],["5700","46","<b>צדיק הוי' בכל דרכיו</b>: תהלים קמה, יז."],["5701","47","<b>רוחא קדמאה דשביק בה</b>: ראה זהר (סבא) משפטים צט, ב. מאמרי אדה\"א הנחות תקע\"ז ע' צט. וש\"נ. ש\"א כז, ב הערה 30."],["5702","49","<b>יוסף. . יסוד ז\"א</b>: ראה ע\"ח שער הצלם שכ\"ו, פ\"ג. ביאוה\"ז ויחי כט, ב. ד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקיז ובהנסמן במ\"מ לשם."],["5703","48","<b>גביע הכסף. . באמתחת בנימין</b>: מקץ מד, ב. ראה גם אוה\"ת מקץ ח\"ב ע' שמג. תער\"ב ח\"ב ע' תתב."]]],[4801940360,"התלבשותה בנר\"נ ובנה\"ט היא מעורבת בסיגים וצריך לברר כל חלקי'<sup data-n=\"5704\">50</sup> שנתפזרו בנה\"ט ולהעלותם עד שיוכללו בבחי' ביטול לאלקות ועי\"ז יוסיפו תת כח בעצם הנשמה, וזמן הבירור הוא בתפילה דייקא כו'. והענין הוא כמ\"ש מצרף לכסף<sup data-n=\"5705\">51</sup> וכור לזהב ואיש לפי מהללו כמו עד\"מ כשרוצים לצרף הכסף שיהי' נקי מפסולת אז נותנים אותה בשלהבת אש וטבע האש לפרר<sup data-n=\"5706\">52</sup> ולהבדיל הפסולת שבו לחוץ ועי\"ז נשאר הכסף נקי וכל מה שירבה בשלהבת יותר מתברר ויוברר הפסולת היותר דקה ויצא הכסף נקי ביותר, כך הוא בתפילה יש בחי' ארי' דאכיל קרבנין כו', ארי' אותיות ראי'<sup data-n=\"5707\">53</sup> שזהו בחי' חכ' שבנה\"א שיש בכאו\"א מישראל שהוא בחי' ראי' לאסתכלא ביקרא דמלכא<sup data-n=\"5708\">54</sup> שהוא כח מ\"ה שבנה\"א שהוא למעלה מהתלבשות בעשר כחות דנה\"ט כי אין דוגמתו באת זה לעומת זה<sup data-n=\"5709\">55</sup>, ומבחי' זאת הראי' נולדה בחי' אהבה כרשפי אש שזהו בחי' ארי' כו'<sup data-n=\"5710\">56</sup> וכח זה הוא המברר ומבדיל כל פסולת שבנה\"ט ומוציא הטוב הגנוז בו להיות נכלל בנה\"א וכמ\"ש הגו סיגים מכסף<sup data-n=\"5711\">57</sup> ויצא לצורף כלי, אך כמו שבגשמי' צריך להשים האש<sup data-n=\"5712\">58</sup> המנקה את הכסף בתוך כלי הנק' מצרף כך הוא בעבודה שבתפלה צ\"ל כלי לאהבה זאת דרשפי אש הבאה מצד הראי' דלאסתכלא כו' והוא בחי' ההתבוננות שבסדר התפלה שמתבונן איך שאין ערוך לך ואני הוי' לא שניתי<sup data-n=\"5713\">59</sup> עי\"ז מעורר אהבה ותשוקה ברשפי אש שבנשמה המלובשת בנה\"ט שתצא לידי גילוי מהעלמה, ואהבה זאת הוא כלי לאהבה כרשפי<sup data-n=\"5714\">60</sup> אש הנולד מבחי' כח מ\"ה הנ\"ל להיותה למעלה מבחי' התלבשות כו' והוא כדוגמת הקרבנות שארז\"ל שאע\"פ שאש יורד ע\"ג המזבח מ\"מ מצוה להביא מן ההדיוט<sup data-n=\"5715\">61</sup> כך בעבודה שבלב זו תפלה<sup data-n=\"5716\">62</sup> האהבה כרשפי אש שמצד הנשמה נק' אש שלמעלה וזהו ענין כולם בחכמה עשית בבינה<sup data-n=\"5717\">63</sup> שהוא בחי' כלי לחכמה ואעפ\"כ מצוה לעורר האהבה שמצד ההתבוננות ונק' אש של הדיוט כו', והנה זהו מה שסיים ואיש לפי מהללו שהוא ענין ההלוי' שבפסוד\"ז שמעורר האהבה שמצד ההתבוננות דרוממות אל כו'.\n<b>והנה</b> כ\"ז הבירור נעשה בתפילה דייקא שהוא ענין הבדלת הרע ולכן אומרים בתפלה אחר מסי\"נ שבק\"ש סלח לנו<sup data-n=\"5718\">64</sup> אבינו כי חטאנו, כי כל שנתפעל",[["5704","50","<b>חלקי'</b>: א: חלקי האהבה."],["5705","51","<b>מצרף לכסף</b>: משלי כז, כא."],["5706","52","<b>וטבע האש לפרר</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תרכד. וש\"נ."],["5707","53","<b>ארי' אותיות ראי'</b>: ראה ת\"ז ת\"ע (קכב, א). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'ל."],["5708","54","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["5709","55","<b>באת זה לעומת זה</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד ואילך."],["5710","56","<b>כו'</b>: א: הנ\"ל."],["5711","57","<b>הגו סיגים מכסף</b>: משלי כה, ד."],["5712","58","<b>האש</b>: א: את האש."],["5713","59","<b>ואני הוי' לא שניתי</b>: מלאכי ג, ו."],["5714","60","<b>כרשפי</b>: א: ברשפי. וכן לקמן."],["5715","61","<b>שאע\"פ שאש. . להביא מן ההדיוט</b>: ראה תו\"כ ויקרא א, ז. ערובין סג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ."],["5716","62","<b>זו תפלה</b>: ניתוסף ע\"פ א."],["5717","63","<b>כולם בחכמה עשית בבינה</b>: תהלים קד, כד. זהר תזריע מג, א."],["5718","64","<b>אומרים בתפלה. . סלח לנו</b>: ראה גם לעיל ע' קסז. ע' שנו. מאמרי אדה\"א קונטרסים ע' שג. וש\"נ. סה\"מ תרכ\"ז ע' רנ ואילך. ע' תלג. תרכ\"ט ע' רסב. תרל\"ב ח\"א ע' צג."]]],[4801940406,"ביותר במסי\"נ באחד<sup data-n=\"5719\">65</sup> לבוא מזה לואהבת כו' יותר ירגיש הריחוק בנפשו עד שגם חטא קל לפשע ומרד יחשב בעיניו שהוא כמשל הבדלת הפסולת היותר דקה כי הרגשת הריחוק הוא ענין פירוד והבדלת הרע, משא\"כ כשלא יתפעל במסי\"נ ובאהבה כרשפי אש כו' אז כל דרך איש ישר בעיניו ולא ירגיש הרע בנפשו, וכ\"ז מצד התערובות הרע בנפשו לא ירגיש כלל במציאותו שהוא מציאת הרע כו'. והנה העבודה הנ\"ל לעורר האהבה רשפי אש ולברר כל חלקי הטוב שבנה\"ט להיות ניכלל בעצם הנשמה [שזה נעשה מזון לעצם הנשמה הנק' אמונה כו' והוא בחי' מזון העולה מלמטה למעלה כדוגמת הקרבנות הנק' לחם כו' ] הוא בחי' מחצית השקל בלבד שהוא עשרה גרה שהוא ענין עשר כחות שבנה\"א העולים מלמטה למעלה להיות נכללים בבחי' ביטול כו' ולכן א' זה יתנו כו' מחצית השקל שנתינתם מלמטה למעלה הוא רק מחצית בלבד וזהו ענין תרומה לה' ארמותא<sup data-n=\"5720\">66</sup> לה' שהוא בחי' העלאה מלמטה למעלה, אכן כח ההעלאה זאת באה מצד המזון שמלמעלה למטה שהוא בחי' מחצית הב' שהוא בחי' המשכה ע\"י תומ\"צ מלמעלה למטה והמה נעשים בחי' לחם לעצם הנשמה [הנק' אמונה כנ\"ל], ולהוסיף בה כח שתוכל לברר ע\"י האהבה כרשפי אש כל בחי' חלקי הכסף שיצאו נקיים כנ\"ל, וכפ\"ע המשכה<sup data-n=\"5721\">67</sup> מלמעלה למטה ע\"י התומ\"צ כ\"ה ערך ההעלאה ובירור בתפלה כו' וזהו שקל הקודש שהוא מל' משקל כמשל<sup data-n=\"5722\">68</sup> השוקל במאזניים שכפ\"ע המשקל שמשים בכף הימיני שהוא מכביד ויורד למטה כן לפי\"ע זה עולה הסחורה הנשקלת בכף השמאלי וכ\"ה לפי\"ע ההמשכה מלמעלה למטה בעצם הנשמה ע\"י תומ\"צ כ\"ה לפי\"ע זה ההעלאה מלמטה למעלה כנ\"ל, וזהו ענין על ג' דברים העולם עומד<sup data-n=\"5723\">69</sup> כו' תו' ועבודה וגמ\"ח כי גמ\"ח הוא המשכה<sup data-n=\"5724\">70</sup> מלמעלה למטה ועבודה שבתפלה הוא ההעלאה<sup data-n=\"5725\">71</sup> מלמטה למעלה והתורה כלולה מהמשכה<sup data-n=\"5726\">72</sup> והעלאה<sup data-n=\"5727\">73</sup> כי קריאה בתושב\"כ באותיות שבה בלבד הוא בחי' המשכה ובתושבע\"פ שעיקר<sup data-n=\"5728\">75</sup> בה בחי' עיון<sup data-n=\"5729\">74</sup> זהו בחי' העלאה ולכן התו' מייחדת ומחברת<sup data-n=\"5730\">76</sup> ההעלאה דתפלה עם המשכות שמצד המצות מחמת שהיא כלולה<sup data-n=\"5731\">77</sup> משניהם יחד כו' וד\"ל.",[["5719","65","<b>במסי\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["5720","66","<b>תרומה לה' ארמותא</b>: ראה זהר תרומה קמז, א. תרכ\"ט ע' רב־ תרל\"ב ח\"א ע' צה ובהנסמן שם."],["5721","67","<b>המשכה</b>: א: כח ההמשכה."],["5722","68","<b>כמשל</b>: א: כמשקל."],["5723","69","<b>על ג' דברים העולם עומד</b>: ראה אבות פ\"א, מ\"ב."],["5724","70","<b>גמ\"ח הוא המשכה</b>: ראה תו\"ח בראשית כו, ג."],["5725","71","<b>ועבודה שבתפלה הוא ההעלאה</b>: ראה גם מאמרי אדה\"ז על ענינים ע' תטז. ד\"ח נד, א. מאמרי אדה\"א שמות ח\"א ע' שי. קונטרסים ע' תקעד."],["5726","72","<b>והתורה. . מהמשכה</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שכז. שה\"א כו, א. בהערה הבאה."],["5727","73","<b>והתורה. . מהמשכה והעלאה</b>: ראה גם ד\"ח נד, ב. ש\"א צא, א. מאמרי אדה\"א דברים ח\"ד ס\"ע א'תסו ואילך."],["5728","75","<b>שעיקר</b>: א: שמצווה."],["5729","74","<b>קריאה בתושב\"כ. . ובתושבע\"פ. . עיון</b>: ראה מאמרי אדה\"א בראשית ע' תקכז. וש\"נ. וראה גם שע\"ת קכא, ב ואילך."],["5730","76","<b>ומחברת</b>: ניתוסף ע\"פ א."],["5731","77","<b>כלולה</b>: א: בלולה."]]],[4801940449,"<b>והנה</b> כל הנ\"ל נק' מטה לחם שהוא ענין לחם דתורה הנמשך מבחי' מטה שהוא בחי' עה\"ח<sup data-n=\"5732\">78</sup> דאילנא דחיי וכמ\"ש עץ חיים היא<sup data-n=\"5733\">79</sup> למחזיקים בה כו' [והוא בחי' יסוד אבא מקור התו'<sup data-n=\"5734\">80</sup> ] ונמשך בג' קווין דתורה ועבודה וגמ\"ח עד שנמשך להיות בחי' מזון וחיות למקור נש\"י הנק' אמונה כנ\"ל [שזהו בחי' מזון מלמעלה למטה ומלמטה למעלה כנ\"ל] ועי\"ז פועל גילוי האמונה בבחי' דעת שהוא ענין ח\"י ברכאן דצלותא שזהו עיקר הכוונה כנ\"ל, ומבחי' מזון זה דעה\"ח הי' נמשך<sup data-n=\"5735\">81</sup> באדה\"ר קודם החטא שזהו ענין לעבדה ולשמרה<sup data-n=\"5736\">82</sup> רמ\"ח מ\"ע ושס\"ה ל\"ת כו', וכן בחי' זאת הי' בשעת לוחות הראשונות שקודם החטא העגל שאז קבלו ישראל התורה מבחי' עה\"ח שלמעלה מעה\"ד טו\"ר אבל חטא העגל שירדו ישראל ממדריגתם ונתלבשו בעה\"ד טו\"ר<sup data-n=\"5737\">83</sup> [אבל בתחלה בעת מ\"ת דעה\"ד פסקו זוהמתם<sup data-n=\"5738\">84</sup> וכמאמר חרות על הלוחות חירות ממה\"מ<sup data-n=\"5739\">85</sup> כו'] ואז נעשה שבירת הלוחות שזהו ענין בשברי לכם מטה לחם<sup data-n=\"5740\">86</sup> שהוא ענין ירידת התורה ג\"כ להתלבש בעה\"ד טו\"ר עד שיכול להיות לימוד התורה שלא לשמה וכמאמר למשמאילים בה<sup data-n=\"5741\">87</sup> כו', ועוד ירמוז ענין בשברי שלא יוכל התו' להתקבל להיות מזון לנשמה כ\"א ע\"י השבירה שהוא ענין הפירור לחלקים קטנים שהוא ענין העלם והתלבשות התורה בריבוי ההלכות בדברים גשמיי' וכמשל הרב המשפיע שכל לתלמידו אם הוא בר שכל גדול יוכל להביא את השכל במאמר א' קצר אבל כשכלי שכל התלמיד הוא בבחי' קטנות מוכרח לחלקו לריבוי חלקים ולהשפיע לו מעט מעט כו', וזהו ענין הטחינה בלחמה דתורה שהוא ענין פירור לחלקים קטנים כו'.\n<b>ועוד</b> צ\"ל ואפו עשר נשים כו' שהוא בחי' האפי' באש שעי\"ז יצא טעם הנעלם לידי גילוי להיות מזון וחיות לנפש וכ\"ה בלחמה דתורה ע\"י התפעלות רשפי אש האהבה דתפלה במס\"נ באחד [שזהו ואפו כו' בתנור אחד] עי\"ז יוכל התורה להתקבל בבחי' מזון וחיות לנפש<sup data-n=\"5742\">88</sup> משא\"כ בלא דו\"ר דתפלה לא יהי' מזון וחיות לנה\"א [משא\"כ קודם החטא אדה\"ר והעגל הי' צמיחת הלחם בלא טחינה ואפי' כלל וכן לחמה של תורה הי' נמשך מבחי' עה\"ח וכמו לעתיד תוציא הארץ גלוסקאות<sup data-n=\"5743\">89</sup> כו'], וזהו ואפו",[["5732","78","<b>מטה לחם. . עה\"ח</b>: ראה גם במאמר שלפנ\"ז ובהערה 3."],["5733","79","<b>עץ חיים היא</b>: משלי ג, יח."],["5734","80","<b>יסוד אבא מקור התו'</b>: ראה גם ע\"ח שער הארת המוחין של\"ב, רפ\"ח. תו\"ח וארא ח\"א עב, א ובהנסמן שם."],["5735","81","<b>נמשך</b>: ניתוסף ע\"פ א."],["5736","82","<b>לעבדה ולשמרה</b>: בראשית ב, טו. ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שצט־ בראשית ע' עג־ קונטרסים ע' שי."],["5737","83","<b>אבל חטא. . טו\"ר</b>: א: ליתא. וכנראה נשמט מפני תיבות הדומות: טו\"ר. . טו\"ר."],["5738","84","<b>בעת מ\"ת. . פסקו זוהמתם</b>: שבת קמו, רע\"א. ראה סה\"מ תרס\"ח ע' קלא."],["5739","85","<b>חרות. . חירות ממה\"מ</b>: תשא לב, טז. ראה שמו\"ר רפל\"ב. פמ\"א, ז. זהר בראשית לז, ב."],["5740","86","<b>לחם</b>: ניתוסף ע\"פ א."],["5741","87","<b>למשמאילים בה</b>: ראה שבת פח, ב. רש\"י שם סג, א ד\"ה למשמאילין. תו\"ח שמות ח\"א ג, ד. וש\"נ."],["5742","88","<b>וכ\"ה בלחמה. . לנפש</b>: ניתוסף ע\"פ א. וכנראה שנשמט מפני תיבות הדומות: מזון וחיות לנפש. . מזון וחיות לנפש."],["5743","89","<b>לעתיד תוציא הארץ גלוסקאות</b>: ראה שבת ל, ב. ראה גם תו\"ח שמות ח\"א כג, ב. וש\"נ."]]],[4801940486,"עשר נשים בחי' נוק' שנהפך סדר העבודה שבתחלה צ\"ל רשפי אש האהבה בתפלה מלמטה למעלה ולפי\"ע זה יהי' נמשך המשכת לחמה של תורה מלמעלה למטה כנ\"ל, משא\"כ כשהיו מקבלים מבחי' עה\"ח הי' נמשך<sup data-n=\"5744\">90</sup> בתחלה ההמשכה מלמעלה למטה ולפי\"ע זה הי' ההעלאה כו' [וזהו ירידה גדולה לנש\"י כי כשההמשכה הוא מצד המשפיע בתחלה אז נתקבל בחי' עצמי' המשפיע במקבל משא\"כ כשההשפעה היא מצד ההעלאה שבתחלה אינה רק לפ\"ע ההעלאה שבתחלה ולכן זהו בחי' מוסר אביך שהוא בחי' התלבשות התורה בגבורות וצמצומים גדולים כו'. אך מוסר זה מלובש בו מפנימי' אה\"ר<sup data-n=\"5745\">91</sup> לטובת ישראל להעלותם לבחי' יותר גדולה כו' כמשי\"ת], וכמשל המשקל שיש בזה ב' אופנים או להכביד במשא על כף הימיני ועי\"ז יעלה כף השמאלי או להגביה כף השמאלי ועי\"ז יורד כף הימיני מלמעלה למטה כו', אך יש בזה יתרון בלחם זה של תורה שנתלבש בעה\"ד טו\"ר ומתברר<sup data-n=\"5746\">92</sup> ע\"י התפלה יותר יותר<sup data-n=\"5747\">93</sup> מלחמה של תורה הנמשך מעה\"ח כו' והוא מש\"א אח\"כ והשיבו לחמיכם במשקל כו'.\n<b>וביאור</b> הדברים הנה ארז\"ל נובלות חכמה שלמעלה תורה<sup data-n=\"5748\">94</sup> שכל בחי' תורה שירדה בד' עולמות דאבי\"ע הוא מחכמה עילאה דאצי' שאינה רק נובלות והארה בעלמא מבחי' חכ' העצמי' הנק' חכמה שלמעלה שהוא בבחי' א\"ס ולכן באה התורה במדה ושיעור ברמ\"ח מ\"ע ושס\"ה ל\"ת משא\"כ עצמות חכמתו הוא בחי' א\"ס [כי הוא וחכמתו אחד<sup data-n=\"5749\">95</sup> כו'<sup data-n=\"5750\">96</sup> ] רק שהוא מקור המודד לבחי' חכמה שבתורה שירדה בהשתלשלות [וכמשל אמת הבנין המודד כל מיני מידה ובעצמו הוא אינו מן המדה כו'] ולכן בחי' סתים דאורייתא שהוא בחי' חכמתו העצמי' נאמר עלי' ארוכה מארץ מדה<sup data-n=\"5751\">97</sup> כו'. וזהו ענין שרש לחמה דתורה הנמשך מעה\"ח דחכמה עילאה שהוא בבחי' נובלות הנ\"ל הנמשך מחכ' העצמי' שבבחי' א\"ס כנ\"ל, אבל התורה שנתלבשה בעה\"ח טו\"ר ומתבררת ע\"י הביטול דנה\"א בתפלה שהוא בחי' מסי\"נ בק\"ש וקבלת עומ\"ש דתמליכהו<sup data-n=\"5752\">98</sup> כו' זאת התורה היא העולה בשרשו ומקורו בחכמה העצמי' שבא\"ס ממש. וזהו ענין דוד הי' מחבר תורה שלמעלה [שהוא בחי' נובלות הנ\"ל] בהקב\"ה<sup data-n=\"5753\">99</sup> שהוא בחי' חכמה העצמי' המיוחדת בא\"ס כו' והיינו מצד שהוא מקור נש\"י והי' בו בחי' מסי\"נ בק\"ש וקבעומ\"ש כמאמר הקים עול<sup data-n=\"5754\">100</sup> כו'. וזהו ענין",[["5744","90","<b>נמשך</b>: א: נעשה."],["5745","91","<b>אה\"ר</b>: א: מדה\"ר."],["5746","92","<b>ומתברר</b>: א: ומחברו."],["5747","93","<b>יותר יותר</b>: כ\"ה גם בא."],["5748","94","<b>נובלות חכמה שלמעלה תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["5749","95","<b>הוא וחכמתו אחד</b>: תניא פ\"ב."],["5750","96","<b>כו'</b>: א: ליתא."],["5751","97","<b>ארוכה מארץ מדה</b>: איוב יא, ט. ראה גם לעיל ע' סח ובהערה 18."],["5752","98","<b>דתמליכהו</b>: ראה זהר רע\"מ פינחס רכג, ב. עקב ערב, א. הנסמן במאמרי אדה\"א בראשית ע' לד."],["5753","99","<b>דוד הי' מחבר. . בהקב\"ה</b>: בסה\"מ תרל\"ו ח\"ב ע' רסד: ”בס' מעין החכמה מדרש רז\"ל. . וכ\"ה ברע\"מ פ' פנחס דף רכ\"ב ע\"ב\". שם ע' שכז: ”בס' הבהיר או בס' מעין החכ'\". תרכ\"ז ע' כד וע' לא ”במעיין החכ' או בס' הבהיר\". ראה ס' הבהיר סקצ\"ו ובאור בהיר לשם. מאמרי אדה\"א דברים ח\"ג ע' תשפג. וש\"נ. ח\"ד ע' א'רכא. וש\"נ. דרושי חתונה ח\"ב ע' תרכח בשם מדרש."],["5754","100","<b>הקים עול</b>: שמו\"ב כג, א. ראה גם לעיל ע' סט ובהערה 36."]]],[4801940520,"ממושבותיכם תביאו לחם תנופה<sup data-n=\"5755\">102</sup> מבחי' ק\"ש דמיושב נעשה ההעלאה לחמה של תורה במקורה חכ' העצמי' כו'<sup data-n=\"5756\">101</sup>.\n<b>וזהו</b> ענין והשיבו לחמיכם במשקל שהוא מקור המשקולת [הנק' מתקלא בס\"י<sup data-n=\"5757\">103</sup> כו'] שהוא בחי' חכמה העצמי' וזהו ערבים עלי ד\"ס<sup data-n=\"5758\">104</sup> יותר מיינה של תורה כו' כי יינה של תורה הוא בחי' תושב\"כ הנק' בחי'<sup data-n=\"5759\">106</sup> ספר<sup data-n=\"5760\">107</sup> שהוא בחי' ח\"ע כשבאה בבחי' התלבשות באותיות דבינה הנק' ספר והוא ע\"י הדעת הנק' סיפור, וזהו ענין בשלשה ספרים המוזכר בס\"י<sup data-n=\"5761\">108</sup>, אבל חכמים דתושבע\"פ נק' סופרים מצד שהגיעו ע\"י בחי' הביטול שלהם לחכ' העצמית הנק' סופר<sup data-n=\"5762\">105</sup> [שהוא הכותב את הספר] והוא מקור המשקולת כמאמר אי' סופר ואי' שוקל<sup data-n=\"5763\">109</sup> כו' ולכן ערבים עלי יותר מיינה של תורה כו'. והטעם לזה כי בחכמה מלובש תענוג ונמצא שהתענוג המלובש בחכמה העצמי' שהוא בחי' א\"ס גם התענוג הוא בבחי' א\"ס אבל התענוג המתלבש<sup data-n=\"5764\">110</sup> בחכ\"ע הוא ג\"כ במדה ושיעור כמו החכמה וזהו ערבים עלי שהוא בחי' עריבות ומתיקות בלי גבול כמאמר רווחא לבסומי שכיח<sup data-n=\"5765\">111</sup> כו' וכמשי\"ת].\n<b>והנה</b> זהו ג\"כ ענין ואכלתם ולא תשבעו כי הנה ארז\"ל והאיך לא אשא פנים לישראל<sup data-n=\"5766\">112</sup> והם החמירו ע\"ע עד כזית ועד כו' כי מן התורה הוא ואכלת ושבעת<sup data-n=\"5767\">113</sup> הוא הבירור וההעלאה ואח\"כ וברכת הוא בחי' המשכה ונמצא שנמדד ע\"פ חכמה דתורה דהעלאת מ\"ן כזה שבבחי' שביעה דווקא יכול לעורר המשכה אבל בחי' חכ'<sup data-n=\"5768\">114</sup> דתושבע\"פ מצד שעלו לבחי' מוסר<sup data-n=\"5769\">115</sup> מקור המדה<sup data-n=\"5770\">116</sup> לכן הי' ביכולתם להמשיך מדה אחרת של כזית שעי\"ז העלאת מ\"נ יוכל ג\"כ להיות ההמשכה ממקום גבוה כזה, וזהו ואכלתם ולא תשבעו שתוכלו להמשיך גילוי אוא\"ס ע\"י אכילה פחות מכדי שביעה כו'. ועוד יתפרש ואכלתם ולא תשבעו בבחי' התענוג שיהי' המשכה מבחי' תענוג בלתי מוגבל שאין בו שביעה כלל כידוע בענין עיני אדם לא תשבענה<sup data-n=\"5771\">117</sup> מבחי'",[["5755","102","<b>ממושבותיכם תביאו לחם תנופה</b>: אמור כג, יז. ראה לקו\"ת נשא כ, א."],["5756","101","<b>וזהו ענין. . כו'</b>: א: ליתא. וכנראה נשמט מפני תיבות הדומות: כו'. . כו'."],["5757","103","<b>מתקלא בס\"י </b>[א: בס\"ד]: בספרא דצניעותא. זהר תרומה קעו, ב. ראה גם לקו\"ת בחוקותי מח, ג."],["5758","104","<b>ערבים עלי' ד\"ס</b>: ראה ע\"ז לה, א וברש\"י שם."],["5759","106","<b>בחי'</b>: א: ליתא."],["5760","107","<b>דבינה הנק' ספר. . הדעת הנק' סיפור. . לחכ'. . סופר</b>: ראה גם סידור שחרית לשבת קעט, א. סה\"מ תרל\"ח ע' סה בשם הפרדס."],["5761","108","<b>בשלשה ספרים המוזכר בס\"י</b>: בתחילתו."],["5762","105","<b>תושב\"כ. . ספר. . דתושבע\"פ. . הנק' סופר</b>: ראה גם לקו\"ת תצא לח, ג. שה\"ש ז, א."],["5763","109","<b>אי' סופר ואי' שוקל</b>: ישעי' לג, יח. ראה תו\"א שמות נג, ב."],["5764","110","<b>המתלבש</b>: ניתוסף ע\"פ א."],["5765","111","<b>רווחא לבסומי שכיח</b>: ראה ערובין פב, ב."],["5766","112","<b>והאיך לא אשא פנים לישראל</b>: ראה ברכות כב, ב. במדב\"ר פי\"א, ז. לקו\"ת נשא כו, א."],["5767","113","<b>ואכלת ושבעת</b>: עקב ח, י."],["5768","114","<b>חכ'</b>: א: חכמים."],["5769","115","<b>מוסר</b>: שם: סופר."],["5770","116","<b>המדה</b>: שם: המדידה."],["5771","117","<b>עיני אדם לא תשבענה</b>: משלי כז, כ [ושם ועיני האדם]. ראה פלח הרמון שה\"ש ע' 124 ואילך. לקו\"ת שה\"ש לד, ג. סהמ\"צ להצ\"צ ע' קפח."]]],[4801940548,"ההסתכלות ביקרא דמלכא שהוא בחי' א\"ס וכמאמר מי איכא זקנה קמי' קוב\"ה<sup data-n=\"5772\">118</sup> [כי נער הייתי גם זקנתי<sup data-n=\"5773\">119</sup> שרו של עולם אמרו שהוא בחי' תענוג המורכב בחכמה הנמשך להיות מקור להשתלשלות שיפול בו התיישבות<sup data-n=\"5774\">120</sup> שאז כלה התענוג וכמאמר לכל תכלה ראיתי קץ כו'<sup data-n=\"5775\">121</sup> ], משא\"כ קמי' קוב\"ה שהוא תענוג<sup data-n=\"5776\">122</sup> בבחי' א\"ס לא יפול בו התיישבות<sup data-n=\"5777\">123</sup> כי בכל עת ורגע נמשך תענוג חדש בעילוי אחר עילוי כו' וזהו בכל יום יהיו בעיניך כחדשים<sup data-n=\"5778\">124</sup> כו' והיינו ג\"כ מטעם הנ\"ל דשרש התורה המתברר מעה\"ד טו\"ר מלמטה למעלה הוא העולה בבחי' מקור המשקולת הנק' מתקלא שהוא בחי' חכמה העצמי' דא\"ס לכן גם התענוג הוא בבחי' א\"ס כו' וד\"ל.",[["5772","118","<b>מי איכא זקנה קמי' קוב\"ה</b>: ראה יבמות טז, ב. במאמר שנדפס לפנ\"ז ובהערה 74."],["5773","119","<b>נער הייתי גם זקנתי</b>: תהלים לז, כה."],["5774","120","<b>התיישבות</b>: א: התיישנות."],["5775","121","<b>לכל תכלה ראיתי קץ</b>: תהלים קיט, צו."],["5776","122","<b>שהוא תענוג. . תענוג</b>: א: ליתא."],["5777","123","<b>התיישבות</b>: א: ליתא כנ\"ל. ראה הערה 120."],["5778","124","<b>בכל יום יהיו בעיניך כחדשים</b>: ראה לקח טוב ואתחנן ו, ו. לעיל ע' קמב ובהערה 14."]]],[4801940137,"<b>רש\"ד שאמר אדמו\"ר שליט\"א יום ש\"ק פ' במדבר שנת הר\"ת לפ\"ק</b>\n<b>וזכרתי</b> את בריתי יעקוב<sup data-n=\"5779\">1</sup> ואף את בריתי יצחק ואף את בריתי אברהם אזכור והארץ אזכור<sup data-n=\"5780\">2</sup>. להבין מה שהופך הסדר יעקב קודם ליצחק ויצחק קודם לאברהם. הנה כלל התירוץ הוא מחמת שא' אח\"כ והארץ אזכור ולא הזכיר שמים א\"כ מדבר בבחי' ארץ קדמה<sup data-n=\"5781\">3</sup> ובבחי' זאת הסדר מלמטה למעלה יעקב יצחק אברהם, משא\"כ כשמזכיר שמים קודם לארץ כמו בפ' אם לא בריתי<sup data-n=\"5782\">4</sup> יומם ולילה חוקות שמים וארץ לא שמתי שמדבר בבחי' שמים קדמו בבחי' זאת הסדר אברהם יצחק יעקב. ולהבין הטעם בזה גם להבין ענין יעקב מלא בוי\"ו שבכל התו' אינו רק פ\"א [ובתנ\"ך חמשה פעמים מלא<sup data-n=\"5783\">5</sup> וכנגדם חמשה פעמים אלי' חסר<sup data-n=\"5784\">6</sup> ] וכנגדו בפ' הנה אנכי שולח לכם<sup data-n=\"5785\">7</sup> את אלי' הנביא לפני בוא כו' חסר וי\"ו ואיתא בדברז\"ל שיעקב לקח במשכון הוי\"ו<sup data-n=\"5786\">8</sup> מאת אלי' בכדי שיבוא לבשר את בניו",[["5779","1","<b>וזכרתי את בריתי יעקוב</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ נדפס באוה\"ת בחוקותי כרך ב ע' תרפה ואילך (וסיומו בכרך ד ע' א'קפט).\nעוד ע\"ד המאמר ראה לקמן ברשימת הכת\"י כאן."],["5780","2","<b>וזכרתי את בריתי יעקוב. . והארץ אזכור</b>: בחוקותי כו, מב."],["5781","3","<b>ארץ קדמה</b>: חגיגה יב, א. ראה ב\"ר ספ\"א."],["5782","4","<b>אם לא בריתי</b>: ירמי' לג, כה."],["5783","5","<b>יעקב. . חמשה פעמים מלא</b>: א) כאן. ב) ירמי' ל, יח. ג) שם לג, כו. ד) שם מו, כז. ה) שם נא, יט."],["5784","6","<b>חמשה פעמים אלי' חסר</b>: א) מל\"ב א, ג. ב) שם, ד. ג) שם, ח. ד) שם, יב. ה) מלאכי ג, כג. וראה גם שו\"ת תרומת הדשן שבהערה 8."],["5785","7","<b>הנה אנכי שולח לכם</b>: מלאכי ג, כג."],["5786","8","<b>שיעקב לקח במשכון הוי\"ו</b>: באוה\"ת כאן: הובא בתה\"ד [ בתרומת הדשן] סי' רל\"ג. ראה גם רש\"י בחוקותי כאן. מדרש חסר ויתיר באוצר המדרשים אייזענשטיין ע' 197ב."]]],[4801940201,"לתה\"מ<sup data-n=\"5787\">9</sup>. ואינו מובן למה אלי' דוקא הוא שייך לבשורת תחה\"מ, וענין מה שלקח במשכון הוא פלא לגמרי.\n<b>ולהבין</b> כל הנ\"ל ילה\"ק ענין פ' הנ\"ל<sup data-n=\"5788\">10</sup> אם לא בריתי יומם ולילה שיש בזה ב' פי'<sup data-n=\"5789\">11</sup> הא' דקאי על ברית דתו', וענין ברית הוא מחבר ומקשר, והיינו שברית דתו' מחבר שני הפכים דיום ולילה, ופי' הב' דקאי על ברית מילה שהוא ג\"כ מחבר ומקשר יום ולילה, ושני הפי' אמת והיינו כמבו' בס\"י כרת לו ברית<sup data-n=\"5790\">12</sup> בין עשר אצבעות<sup data-n=\"5791\">13</sup> ידיו והוא ברית הלשון וכרת לו ברית המעור<sup data-n=\"5792\">14</sup> בין עשר אצבעות רגליו והוא ברית המעור, ומתחילה י\"ל מהו ענין יום ולילה, הנה ארז\"ל כברייתו של עולם ברישא חשוכא<sup data-n=\"5793\">15</sup> והדר נהורא. וביאור הדברים כי הנה אא\"ס אינו מהות ועצמות הא\"ס רק הארתו וזיוו, והוא מה שבכחו ויכולתו להשפיע עולמות, והוא כמו אור השמש שאינו עצמות השמש רק מה שמאיר ממנו לארץ ולדרים, וזהו ג\"כ ענין הי' הוא ושמו בלבד המוזכר בפר\"א<sup data-n=\"5794\">16</sup>, כי ענין השם אינו שייך ג\"כ לעצמות האדם רק מה שנפנה לזולתו<sup data-n=\"5795\">17</sup> לקוראו<sup data-n=\"5796\">18</sup> ע\"י השם. והנה הגם שהאור איננו מהותו ועצמותו ית' רק הארתו בלבד מ\"מ הארה זאת גופא הוא בחי' א\"ס וכל מה שמאיר ממנו הכל הוא בחי' א\"ס וא\"כ איך ימצא ממנו בחי' העולמות שהם בגבול ומדה והם ג\"כ בבחי' יש נפרד, לזאת צמצם א\"ע [... וענין הצמצום אינו בבחי' העצמות ח\"ו כי לא יתכן בו ענין צמצום כלל רק הצמצום הוא בבחי' האור, וגם בבחי' האור אין הפי' הסתלקות ח\"ו רק העדר הגילוי למקבלים כו' וד\"ל]. והיינו שנתעלם כללות האור עד שאין נגלה למקבלים רק נקודה אחת מכללות האור והוא בחי' היו\"ד דשם הוי'.\n<b>אך</b> הנה כתי' בי\"ה הוי' צור עולמים<sup data-n=\"5797\">19</sup> ודרז\"ל ביו\"ד נברא העוה\"ב<sup data-n=\"5798\">20</sup> והיינו שגם מן היו\"ד אין יכולים לקבל רק עולמות עליונים שנק' העוה\"ב [והוא בחי' אצי'] והגם שהם מקור לבחי' שפע פרטית בלבד כמו בחי' חכים הוא מקור להיות ממנו בחי' חכ' בלבד ולא השפעה אחרת וכ\"ה עד\"ז כל הי\"ס כו' מ\"מ הם בתכלית הביטול והיחוד אבל כשצריך להתהוות בחי' יש נפרד צריך להיות נמשך בחי' ה' מבחי' היו\"ד והיו\"ד מתלבש בו שזהו בחי' בינה, ובחי' בינה נמשך ע\"י הוי\"ו שהוא מדות דז\"א ומתלבש בבחי' ה' אחרונה שהוא בחי' המל' שיש בה ג' קוין שזהו מקור ג'",[["5787","9","<b>לתה\"מ</b>: כ\"ה גם בא. ראה גם אוה\"ת בחוקותי כרך א ע' רי. מלאכי ח\"א ע' תקמג."],["5788","10","<b>פ' הנ\"ל</b>: א: פי' הפ'."],["5789","11","<b>ב' פי'</b>: ראה אוה\"ת בחוקותי כרך א ע' רג. ירמי' כרך א ע' שפד."],["5790","12","<b>בס\"י כרת לו ברית</b>: ראה שם בסופו. פ\"א, מ\"ג."],["5791","13","<b>אצבעות</b>: תיבה זו נכפלה בכת\"י זה."],["5792","14","<b>המעור</b>: א: ליתא."],["5793","15","<b>כברייתו. . ברישא חשוכא</b>: שבת עז, ב (כגי') רש\"י. ראה תו\"ח וארא ח\"א מט, ג ואילך. הנסמן בסה\"מ תרכ\"ז ע' תנד."],["5794","16","<b>הי' הוא ושמו בלבד המוזכר בפר\"א</b>: ראה שם פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."],["5795","17","<b>לזולתו</b>: א: ליתא."],["5796","18","<b>השם. . שנפנה. . לקוראו</b>: ראה גם לעיל ע' שצה. וש\"נ."],["5797","19","<b>בי\"ה הוי' צור עולמים</b>: ישעי' כו, ד."],["5798","20","<b>ביו\"ד נברא העוה\"ב</b>: ראה מנחות כט, ב."]]],[4801940258,"העולמות דבי\"ע ששני העולמות דבריאה יצירה הוא כנגד ב' קוי הה'<sup data-n=\"5799\">21</sup> ובחי' עשי' כנגד רגל הקצר הנפסק שהוא בחי' אף עשיתיו<sup data-n=\"5800\">22</sup>, וזהו בה' נברא העוה\"ז<sup data-n=\"5801\">23</sup> שעוה\"ז הוא ג' עולמות הנבראים שנראים בבחי' יש נפרד וזהו\"ע בהבראם בה' בראם<sup data-n=\"5802\">24</sup> [... והגם שכוונת רז\"ל בה' נברא כו' הוא ה' ראשונה היינו שעיקר מקור ההתהוות הוא מבחי' בינה ה' ראשונה כמאמר אימא עילאה מקננא בכורסייא<sup data-n=\"5803\">26</sup> כו', אבל גילוי ההתהוות בפועל מאין ליש שיהי' נראה בבחי' יש נפרד הוא ע\"י ה' אחרונה<sup data-n=\"5804\">25</sup> בחי' המל' שזהו בחי'<sup data-n=\"5805\">27</sup> בראם כו' וד\"ל], אך גם בחי' ה' אחרונה הוא בבחי' הוי' ולא הי' נראים עדיין העולמות לבחי' יש רק ע\"י התלבשות בשם אלקים וזהו כי שמש ומגן הוי' אלקים<sup data-n=\"5806\">28</sup> שבחי' אלקים הוא כמו מגן ונרתיק להסתיר על אור שם הוי' שהוא בחי' פרסא המפסקת בין אצי' לבי\"ע<sup data-n=\"5807\">29</sup> והוא כמ\"ש והבדילה הפרוכת<sup data-n=\"5808\">30</sup> כו' כמו פרוכת המעלים את האור לבל יעבור מחוץ לפרוכת כו' כך הוא ענין הפרסא להעלים עצמות האור דאצי' רק אור של תולדה<sup data-n=\"5809\">31</sup> שאינו מעין אור הראשון כלל לכן נתהווה ממנו בחי' יש נפרד.\n<b>וביאור</b> ענין הפרסא יובן ע\"י משל רוחני כמו משלי שלמה<sup data-n=\"5810\">32</sup> כו', שההפרש בין ב'<sup data-n=\"5811\">33</sup> אותיות ההסבר שהם כלים לאור השכל ולכן נתגלה על ידם אור השכל משא\"כ המשל הוא ענין זר לגמרי שאינו כלי לאור השכל כלל וזולתו השומע ידמה שאינו דברי שכל רק מעשה בטלה, אך באמת גנוז בו שכל עמוק ומי שהוא חכם ובר שכל יוכל להבין ממנו אפס קצהו של השכל שהבנתו הוא רק הארה בעלמא מעמקות השכל ואינו מערכו כלל [רק מי שהוא חכם עמוק אדרבה יוכל להבין ממנו עמקות השכל כמ\"ש מה שלא יבינו ע\"י הסבר כו']. ועד\"ז יובן ענין הפרסא שמעלמת בתוכה ומתלבשת בה עצמות האורות דאצי' רק לנבראים אין נגלה ממנה רק הארה בעלמא אור של תולדה שאינו מעין אור הראשון כנ\"ל, וזהו\"ע כברייתו של עולם ברישא חשוכא כו' והיינו שבריאת העולמות הוא ע\"י צמצומים הנק' חושך, ובריאת עולמות עליונים שהוא בחי' ע\"ס דאצי' הוא ע\"י צמצום הראשון",[["5799","21","<b>ג' העולמות דבי\"ע. . הה'</b>: ראה גם לעיל ע' לא ובהערה 13."],["5800","22","<b>אף עשיתיו</b>: ישעי' מג, ז. ראה גם לעיל ר\"ע לב ובהערה 15."],["5801","23","<b>בה' נברא העוה\"ז</b>: ראה מנחות שם."],["5802","24","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב."],["5803","26","<b>אימא עילאה מקננא בכורסייא</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["5804","25","<b>בה' נברא. . ה' אחרונה</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' מד. ע' רכח. ח\"ב ע' תשפט. במדבר ח\"ב ע' ת."],["5805","27","<b>בחי'</b>: א: בה\"א."],["5806","28","<b>כי </b>[א: ליתא]<b> שמש ומגן הוי' אלקים</b>: תהלים פד, יב. ראה שער היחוה\"א רפ\"ד. מאמרי אדה\"א דברים ח\"ב ע' ת. וש\"נ. נ\"ך ע' שצה. וש\"נ."],["5807","29","<b>פרסא המפסקת בין אצי' לבי\"ע</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא."],["5808","30","<b>והבדילה הפרוכת</b>: תרומה כו, לג."],["5809","31","<b>אור של תולדה</b>: ראה ע\"ח שער דרושי (כללות) אבי\"ע שמ\"ב, פי\"ג. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שמא ובהנסמן במ\"מ לשם. תו\"ח ויקהל ח\"ב שפט, א. וש\"נ."],["5810","32","<b>משלי שלמה</b>: ראה גם לעיל ע' קח."],["5811","33","<b>ב'</b>: א: ליתא."]]],[4801940311,"הנק' חושך כמ\"ש ישת חושך סתרו<sup data-n=\"5812\">34</sup> וע\"י היו\"ד שנשאר אחר הצמצום ובריאת עולמות הנבראים הוא ע\"י הפרסא שהוא בחי' חושך גמור להסתיר האור עד שהעולם נראה בבחי' יש כו'. וזהו בחי' מדת יום ומדת לילה<sup data-n=\"5813\">35</sup> כי מדת יום הוא בחי' ע\"ס דאצי' שהם מקבלים אא\"ס בבחי' גילוי אור [והיינו שהנקודה דיו\"ד הנשאר מכללות האור דא\"ס מאיר בהם בבחי' גילוי כו'] משא\"כ עולמות הנבראים גם האור שלהם הוא מוסתר ונעלם ע\"י הפרסא ואינו מאיר בהם בגילוי ולכן נק' מדת לילה כו'.\n<b>והנה</b> בחי' יום ולילה כמ\"ש בבחי' שנה כן הוא בבחי' נפש ועולם, ועניינם בבחי' נפש הוא בחי' הודאה וברכה<sup data-n=\"5814\">36</sup>, כי כשקמים בבוקר אומרים<sup data-n=\"5815\">37</sup> כל זמן שהנשמה כו' מודים<sup data-n=\"5816\">38</sup> כו' וכן הודו לה'<sup data-n=\"5817\">39</sup>, שכ\"ז הוא בחי' הודאה מרחוק שמודה אעפ\"י שאינו משיג הענין מקרוב, כ\"ה למעלה אע\"פ שמשיגים איכות התהוות היש מאין וממילא היש בטל מ\"מ אינו משיג מהות עצם האין [שזהו בחי' ד\"ע כו'] רק מודה עליו בהודאה בלבד מרחוק וזהו נק' מדת לילה בנפש משא\"כ אח\"כ בש\"ע נמשך בחי' גילוי עצם האין בבחי' ראי' מקרוב [כמו סנהדרין שנק' עיני העדה<sup data-n=\"5818\">40</sup> ע\"ש שבחי' עצם האין הוא מאיר בבחי' גילוי בנפשם עד שרואים אמתתו כמ\"ש כו'] לכן או' ברוך שהוא בחי' ברכה והמשכה בגילוי, וזהו נק' מדת יום בנפש, וכ\"ה עד\"ז ההפרש בין אמונה לדעת, אך מבחי' האמונה בא לבחי' הדעת כמ\"ש וארשתיך לי באמונה<sup data-n=\"5819\">41</sup> ואח\"כ וידעת את ה' כו'. וכ\"ה עד\"ז בבחי' עולם יש בחי' יום ולילה, ובחי' יום הוא העוה\"ב שבו מאיר גילוי אלקות להיות נשמות נהנין מזיו השכינה<sup data-n=\"5820\">42</sup> אבל העוה\"ז דומה ללילה מצד שבחי' אלקות מוסתר ונעלם בו ועוד בזה\"ג שמוסתר יותר אור האלקי [... ע\"ד שאותותינו לא ראינו<sup data-n=\"5821\">43</sup> ] לכן נמשל ללילה כו' וד\"ל.\n<b>והנה</b> זהו בחי' יום ולילה כאשר המה מחולקים כמ\"ש ויהי ערב ויהי בוקר<sup data-n=\"5822\">44</sup>, אך עיקר הכוונה שיהי' יום אחד והיינו שיתחברו מדת יום ומדת לילה וזהו מה שארז\"ל כדי להזכיר מדת יום בלילה ומדת לילה ביום<sup data-n=\"5823\">45</sup> כו' וזהו ע\"י ברית דתורה",[["5812","34","<b>צמצום הראשון. . ישת חושך סתרו</b>: תהלים יח,יב. ראה גם מאמרי אדה\"א נ\"ך ע' שצז. וש\"נ. תו\"ח בא ח\"א קכג, ג. וש\"נ."],["5813","35","<b>מדת יום ומדת לילה</b>: נסמן בסמוך הערה 45."],["5814","36","<b>הודאה וברכה</b>: ראה סידור שער בהמ\"ז קח, סע\"ג ואילך. תו\"א בשלח סו, ב. תו\"ח ויחי רמ, א ובהערה 16. לעיל מאמר ד\"ה בשברי לכם תקצ\"ט ובהערה 31."],["5815","37","<b>כשקמים בבוקר אומרים</b>: בברכת אלקי נשמה."],["5816","38","<b>מודים</b>: אוצ\"ל מודה."],["5817","39","<b>הודו לה'</b>: דהי\"א טז, ח."],["5818","40","<b>סנהדרין שנק' עיני העדה</b>: שלח טו, ד. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן במ\"מ לשם. תו\"ח בא ח\"א קב, א ובהערה 248. סה\"מ תרל\"ח ע' קה."],["5819","41","<b>וארשתיך לי באמונה</b>: הושע ב, כב. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תמט."],["5820","42","<b>העוה\"ב. . נהנין מזיו השכינה</b>: ראה ברכות יז, א."],["5821","43","<b>שאותותינו לא ראינו</b>: תהלים עד, ט."],["5822","44","<b>ויהי ערב ויהי בוקר</b>: בראשית א, ה."],["5823","45","<b>כדי להזכיר. . ומדת לילה ביום</b>: ברכות יא, ב. יב, א."]]],[4801940361,"ומצות מילה כו'. והנה ענין להזכיר מדת יום בלילה היינו להביא האור הנק' יום ולהמשיכו בתוך החושך [והיינו ענין ולילה כיום יאיר<sup data-n=\"5824\">46</sup> לא שיתבטל הלילה ממציאותו רק שיאיר כמו אור היום כו'] וזהו ע\"י התו' שנק' ותורה אור<sup data-n=\"5825\">47</sup>. כי הנה ענין התורה הוא אור העצמות דא\"ס שמאיר בחכמה עילאה אשר הוא וחכמתו אחד<sup data-n=\"5826\">48</sup> ונמשך למטה בעוה\"ז הגשמי' שלא ע\"י צמצומים והשתלשלות המדריגות כלל, וענין ההמשכה בעוה\"ז הוא מה שמתלבש בצירופי אותיות גשמיים כמו שנים אוחזין בטלית<sup data-n=\"5827\">49</sup> ותרומות ומעשרות כו' וזהו כמ\"ש רבות עשית<sup data-n=\"5828\">50</sup> כו' נפלאותיך ומחשבותיך ממש נמשך אלינו שלא ע\"י ממוצעים כלל משא\"כ אגידה ואדברה כשהי' צריך להיות נמשך האור ע\"י ההשתלשלות עצמו מספר כי אין שיעור לריבוי הצמצומים והעלמות שנמשכים מחכמה עילאה עד שנמשך האור בעוה\"ז הגשמי לכן מתמעט במיעוט אחר מיעוט כו' [משא\"כ אור התורה אינו מתמעט כלל רק נמשך כמ\"ש בבחי' חכמה עילאה ממש, ולכן כשנמשך למטה מורה על תוקף האור יותר וכמ\"ש במ\"א בענין קול השופר שהולך וחזק מאד<sup data-n=\"5829\">51</sup> ולא כמו שארי קולות שהולכים ומתחלשים כו'], ונמצא שצירופי אותיות הגשמי' שהם מבחי' החשך דנבראים [... כי בגילוי הם שוים לשארי צירופי אותיות שאינם ד\"ת] ומ\"מ מאיר בהם אור העליון שהוא בחי' חכמתו של הקב\"ה להדיא שלא ע\"י השתל' כלל כנ\"ל וזהו ענין מה שמזכירים מדת יום בלילה, וזהו ענין כל העוסק בתורה בלילה<sup data-n=\"5830\">52</sup> פי' שהוא ממשיך בחי' תורה אור בבחי' לילה וחשך הגשמיים, וזהו גולל אור מפני חושך<sup data-n=\"5831\">53</sup> שהו\"ע צמצום האור להיות הנבראים בבחי'<sup data-n=\"5832\">54</sup> שנק' חושך, וחושך מפני אור היינו שנגלל החושך מצד שמביאים את האור בתוכו כו' שזהו ע\"י התורה כנ\"ל, וזהו משארז\"ל ג\"כ ברישא חשוכא שהו\"ע ההשתלשלות והדר נהורא היינו כשממשיכין את האור בתוך החושך ע\"י התורה, וזהו\"ע ברית דתורה המחבר יום ולילה.\n<b>וענין</b> ברית דמילה כי הנה ענין התורה היא בבחי' הדיבור שמדבר דברי תורה שהוא בבחי' הרוחני [וא\"כ אינו נמשך ע\"י התורה רק בחי' יום<sup data-n=\"5833\">55</sup> למעלה בבחי' מדת לילה שבאצי' שהוא בחי' המל' כמשי\"ת בביאור<sup data-n=\"5834\">56</sup> או גם בבחי' עולמות הנבראים דברי' יצי' כמבואר בסידור במאמר הקל קול יעקב<sup data-n=\"5835\">57</sup> אך לא בבחי' עולם העשי' כו'], אך בחי' המצות נעשים במעשה והנה רמ\"ח פיקודין הוא רמ\"ח אברים דמלכא<sup data-n=\"5836\">58</sup> כמו האבר שעל ידו נתגלה חיות הנפש לחוץ כמו ע\"י אבר היד נתגלה",[["5824","46","<b>ולילה כיום יאיר</b>: תהלים קלט, יב. ראה גם תו\"ח תצוה ח\"ב שכב, ב."],["5825","47","<b>ותורה אור</b>: משלי ו, כג."],["5826","48","<b>הוא וחכמתו אחד</b>: תניא פ\"ב."],["5827","49","<b>שנים אוהזין בטלית</b>: משנה ב\"מ ב, א."],["5828","50","<b>רבות עשית</b>: תהלים מ, ו."],["5829","51","<b>קול השופר שהולך וחזק מאד</b>: יתרו יט, יט."],["5830","52","<b>כל העוסק בתורה בלילה</b>: חגיגה יב, ב."],["5831","53","<b>גולל אור מפני חושך</b>: תפלת ערבית. ברכות יא, ב."],["5832","54","<b>בבחי'</b>: א: נראים בבחי' יש."],["5833","55","<b>רק בחי' יום</b>: א: בחי' יום רק."],["5834","56","<b>כמשי\"ת בביאור</b>: נדפס לקמן אחר המאמר."],["5835","57","<b>בסידור במאמר הקל קול יעקב</b>: ראה שם שער התפלה יט, א."],["5836","58","<b>רמ\"ח פיקודין הוא רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."]]],[4801940407,"בבחי' מעשה וע\"י הרגל בבחי' הילוך כו' כך ע\"י המצות מתגלה אא\"ס שבאצי' למטה בבי\"ע כו'<sup data-n=\"5837\">59</sup>, הם בבחי' כלים עליונים דאצי' אך שיומשך האור דא\"ס ויתלבש בבחי' הכלים דאצי' הוא ע\"י שמירה מן הל\"ת ולכן שס\"ה ל\"ת הן כנגד שס\"ה גידים<sup data-n=\"5838\">60</sup> והוא עד\"מ למטה גידי הדם המה מצמצמים חיות הנפש שיתלבש בתוך האברים ואח\"כ מתגלה ע\"י האברים לחוץ כך למעלה שמי עם י\"ה שס\"ה<sup data-n=\"5839\">61</sup> ועל ידם מתגלה האור בבי\"ע, והנה בחי' זאת דגילוי האור בבי\"ע נק' בשם רגל וכמ\"ש והארץ הדום רגלי<sup data-n=\"5840\">62</sup> שהוא בחי' כלי לקבל השפע הנמשך מבחי' רגלי ועז\"א כרת לו ברית בין עשר אצבעות רגליו והיינו כמו עד\"מ הברית הוא ממשיך הטיפה שכלולה מכל האברים בבחי' הולדה לחוץ כך ע\"י מצות מילה ושמירתה נמשך השפע מבחי' המצות כמ\"ש למעלה באצי' שנק' אברים דמלכא ומתגלה בבחי' לידה למטה בבי\"ע עד עשי' הגשמי' דייקא משא\"כ ע\"י התורה לא נמשך רק בבחי' הרוחני' כנ\"ל.\n<b>והנה</b> בחי' זאת הנמשך ע\"י המצות הוא ג\"כ ענין הזכרת מדת יום בלילה שהוא להביא האור בתוך החושך אך הוא נמשך למטה יותר בבחי' העשי', אך בחי' זאת יש בה יתרון שעל ידה הוא קיום האור דתורה מצד שזהו פנימי' המכוון כידוע דסוף מעשה עלה במחשבה תחילה<sup data-n=\"5841\">63</sup>, והוא כדוגמת הרגלי' שהם מעמידים הראש וכמאמר תכלית חכמה תשובה ומעשים טובים<sup data-n=\"5842\">64</sup> כו' וד\"ל. וזהו\"ע או יחזיק במעוזי<sup data-n=\"5843\">65</sup> יעשה שלום לי שלום יעשה לי, ששלום הראשון הוא חיבור הנעשה ע\"י התורה שהוא בחי' ברית הלשון בחי' הדעת המחבר יום ולילה ושלום השני הוא חיבור הנעשה ע\"י המילה שהוא הגילוי אור שנמשך ע\"י המצות למטה בבי\"ע הנק' לילה, וזהו אם לא בריתי יומם ולילה שברית דתורה ומילה הם מחברים יום ולילה אך ע\"י החיבור נעשה יומם בתוס' מ\"ם שזהו\"ע יתרון אור שבא מתוך החושך הנה כ\"ז הוא ענין להזכיר מדת יום בלילה שהוא ענין<sup data-n=\"5844\">66</sup> שילוב הוי' באדני<sup data-n=\"5845\">67</sup>. אך יש בחי' הזכרת מדת לילה ביום שהו\"ע יוצר אור ובורא חושך<sup data-n=\"5846\">68</sup> והיינו ע\"י ההתבוננות כאשר מתבונן בשרש שם אלקים המסתיר שהוא מבחי' עצמות הוי' וכמאמר וידעת היום<sup data-n=\"5847\">69</sup> והשבות אל לבביך כי הוי' הוא האלקים שפירושו שאלקים הוא הוי' וכמאמר ומבלעדי אין אלקים<sup data-n=\"5848\">70</sup>, שבחי' שם אלקים אינו נבדל ממנו ח\"ו, וא\"כ לפני עצמות הוי' אין מסתיר",[["5837","59","<b>כו'</b>: א: כי."],["5838","60","<b>שס\"ה ל\"ת. . שס\"ה גידים</b>: תרגום יוב\"ע בראשית א, כז. זהר וישלח קע, ב."],["5839","61","<b>שמי עם י\"ה שס\"ה</b>: ראה שמות ג, טו. ת\"ז בהקדמה ד, סע\"ב. ה, א. לקו\"ת פקודי ג, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ע תתקי. וש\"נ. תו\"ח בא ח\"א קיד, א. וש\"נ. סה\"מ תרכ\"ז ע' קכט. וש\"נ."],["5840","62","<b>והארץ הדום רגלי</b>: ישעי' סו, א."],["5841","63","<b>דסוף מעשה עלה במחשבה תחילה</b>: ע\"פ פיוט לכה דודי."],["5842","64","<b>תכלית חכמה תשובה ומעשים טובים</b>: ברכות יז, א."],["5843","65","<b>או יחזיק במעוזי</b>: ישעי' כז, ה."],["5844","66","<b>יתרון אור. . ענין</b>: ניתוסף ע\"פ א"],["5845","67","<b>שילוב הוי' באדני</b>: ראה מבו\"ש ש\"ג ח\"ב ספ\"ה. לקו\"ת ש\"ש סה, ד ובהנסמן במ\"מ לשם סד, ב. תו\"ח וארא ח\"א נ, א הערה 32. וראה גם לעיל ע' צה."],["5846","68","<b>יוצר אור ובורא חושך</b>: ישעי' מה, ז."],["5847","69","<b>וידעת היום</b>: ואתחנן ד, לט. ראה גם לעיל ע' שעב."],["5848","70","<b>ומבלעדי אין אלקים</b>: ישעי' מד, ו. ראה גם לעיל ע' קעד."]]],[4801940450,"כלל בחי' שם אלקים וכלא חשיב ולכן אנו אומרים אתה הוי' לבדך<sup data-n=\"5849\">71</sup> שכמו שקודם שנבה\"ע הי' לבדו כך עתה הוא לבדו ממש בלי שום שינוי כלל ועי\"ז נתבטל החשך ממציאותו ונכלל באור העליון, וזהו\"ע שילוב אדני בהוי'<sup data-n=\"5850\">72</sup> שהו\"ע להזכיר מדת לילה ביום, וזהו\"ע לך יום אף לך לילה<sup data-n=\"5851\">73</sup> מה יום ברשותך כי שרש בחי' לילה שהוא אלקים המסתיר הוא ג\"כ למעלה בבחי' אור שם הוי' וזהו אף לך לילה כו' [וכמ\"ש לך ה' הממלכה<sup data-n=\"5852\">74</sup> כו' וד\"ל]. ויובן זה מענין המשל ששרשו בעומק השכל דייקא ולכן נשתבחו כל החכמים כמו שלמה ור\"מ במשלים דייקא ולא בהשכלות העמוקות כי מי שיכול להמשיל משל לנמשל הוא מורה על עמקות חכמתו יותר וכל חכם היותר עמוק יכול להשפיל יותר ולכן אצל שלמה המלך ע\"ה הי' יכול להשפיל חכמתו העמוקה בשלשת אלפים משל<sup data-n=\"5853\">75</sup> שכ\"א הוא משל למשל שקדמו ור\"מ לא הי' משפיל רק בשלש מאות משלים<sup data-n=\"5854\">76</sup> כו', וכ\"ה למעלה שרש שם אלקים המסתיר הוא בעצמות האור דשם הוי', וכאשר מתבונן בזה נתבטל בחי' החשך המסתיר שהו\"ע התכללות מדת לילה ביום כנ\"ל וד\"ל.\n<b>והנה</b> זהו\"ע אם לא בריתי יומם ולילה חוקות שו\"א לא שמתי כי הנה שמים וארץ הם געה\"ע וגעה\"ת<sup data-n=\"5855\">77</sup> והגם שלא נז' בספרים רק ב' מיני ג\"ע<sup data-n=\"5856\">78</sup> זהו בד\"כ אבל בד\"פ יש ריבוא רבבות מדריגות בג\"ע זה למעלה מזה ויש בזה כמה עליות כמו מגעה\"ת לגעה\"ע העלי' ע\"י העמוד<sup data-n=\"5857\">79</sup> הידוע ועד\"ז בבחי' העלי' ממדריגה למדריגה<sup data-n=\"5858\">80</sup> יש עמוד המחבר שע\"י נעשה העלי' ונק' בחי' כל כתרגומו כי כל בשמים וארץ<sup data-n=\"5859\">81</sup> דאחיד בשמי' ובארעא וזהו\"ע רב כל<sup data-n=\"5860\">82</sup> כו', ושרש כולם הוא בחי' הנהר היוצא מעדן<sup data-n=\"5861\">83</sup>, כי להיות הנהר הוא מקור כל התענוגים שבג\"ע לזאת בכחו לחבר ממדריגה למדריגה העליונה ממנה, וזהו\"ע הנני נוטה עלי'<sup data-n=\"5862\">84</sup> כנהר שלום שהנהר הוא המחבר כו' ונק' בחי' הנהר הנ\"ל בחי' חוקות שמים וארץ וקיומו הוא מבחי' התומ\"צ הנק' בריתי כי להיות ע\"י תומ\"צ ממשיכים עצמות אא\"ס שבחכמה עילאה שהוא בחי' המעיין שלמעלה מן הנהר עי\"ז נמשך תמיד נביעות חדשות מן המעיין לנהר עד שנעשה נהר שאינו פוסק, וזהו\"ע בשמחה ובטוב לבב מרוב כל<sup data-n=\"5863\">85</sup> שבחי' שמחה וטוב",[["5849","71","<b>אנו אומרים אתה ה' לבדך</b>: בפסוקי דזמרה מנחמי' ט, ו [בדילוג]. וראה ישעי' לז, כ."],["5850","72","<b>שילוב אדני בהוי'</b>: ראה לעיל הערה 67."],["5851","73","<b>לך יום אף לך לילה</b>: תהלים עד, טז."],["5852","74","<b>לך ה' הממלכה</b>: דהי\"א כט, יא."],["5853","75","<b>שלמה. . בשלשת אלפים משל</b>: מ\"א ה, יב. ראה סה\"מ תרכ\"ט ע' צה. וש\"נ. תרס\"ו ע' רלז. וראה גם תו\"ח וארא ח\"א פג, ב. וש\"נ."],["5854","76","<b>ור\"מ. . בשלש מאות משלים</b>: סנהדרין לח, ב. ראה תו\"א מג\"א צא, ג. מאמרי אדה\"ז תקס\"ח ח\"א ר\"ע שצד. לקו\"ש וילך כרך ט ע' 202 ואילך."],["5855","77","<b>שמים וארץ הם געה\"ע וגעה\"ת</b>: ראה גם לעיל ע' קיא ובהערה 70."],["5856","78","<b>שלא נז' בספרים רק ב' מיני ג\"ע</b>: ראה גם לעיל ע' שצד ובהערה 39."],["5857","79","<b>ע\"י העמוד</b>: ראה גם לעיל מאמר ד\"ה והתהלכתי תרט\"ו ובהערה 57."],["5858","80","<b>למדריגה</b>: ניתוסף ע\"פ א."],["5859","81","<b>כי כל בשמים וארץ</b>: דהי\"א כט, יא [ושם: ובארץ]. ראה זהר בראשית לא, א. ת\"ז תמ\"ז פד, א: ותרגום יונתן. סה\"מ תרל\"ח ע' תנו: ות\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תשמב. וש\"נ."],["5860","82","<b>רב כל</b>: נסמן בהערה 85. ראה גם לקמן מאמר ד\"ה רפאיני הא' על יד הערה 50."],["5861","83","<b>הנהר היוצא מעדן</b>: בראשית ב, י."],["5862","84","<b>הנני נוטה עלי' </b>[א: אלי']: ישעי' סו, יב."],["5863","85","<b>בשמחה ובטוב לבב מרוב כל</b>: תבוא כח, מז."]]],[4801940487,"לבב שבמצוה הוא יותר טוב מרוב כל כי שרש בחי' רב כל הוא בחי' הנהר דבינה כו' משא\"כ בחי' שמחה וטוב לבב שבתומ\"צ מגיע בבחי' המעיין דחכ' שממנו מקור מוצא הנהר כו', משא\"כ כשח\"ו נפסק הברית דתומ\"צ היינו כשאינם עוסקים בתורה וגם שמקיימים המצות מ\"מ עושים אותם מצות אנשים מלומדה בקרירות ולא בשמחה וטוב לבב אז כתי' ונהר יחרב וייבש<sup data-n=\"5864\">86</sup> ח\"ו יחרב בבית ראשון ויבש בבית שני שהוא בחי' ה' עילאה וה' תתאה מקור מוצא ב' מיני ג\"ע געה\"ע וגעה\"ת והיינו שאינו נמשך בהם תוס' אור בתמידות להנביע חדשות רק בצמצום גדול כפי שנמדד ע\"פ קו המדה בתחילת ההשתל' כו', וזהו\"ע אם לא בריתי שכאשר אין הברית דתומ\"צ אז חוקות שמים וארץ לא שמתי שאין שום נביעה חדשה בנהר כו'. ועיקר יובש הנהר הוא עד\"מ הנהר גשמי שמתייבש מריבוי חמימות כ\"ה בעבודה מרוב חום תאוות עניני עוה\"ז והאש שבהם נפסק ונסתלק הענג אלקי שהוא בחי' נהר הנ\"ל.\n<b>ועצה</b> היעוצה לזה הוא עד\"מ גשמי כאשר יבש הנהר ונפסק אז חופרין בעומק יותר מן המעיין ואז ממשיכין נביעה חדשה למלאות הנהר על כל גדותיו כ\"ה למעלה ענין התשובה שהוא בחילא יתיר<sup data-n=\"5865\">87</sup> והיינו לעורר העומק שבנפש שהוא בחי' נקודת הרצון שלמעלה מן החכמה ועי\"ז מעוררים למעלה בחי' חשך העליון דישת חושך סתרו שהוא למעלה מבחי' מדת יום ומדת לילה [שהו\"ע<sup data-n=\"5866\">88</sup> ב' היחודים דשילוב הוי' באדני ואדני בהוי' כו'], וכאשר מגלה עמוקות מיני חושך<sup data-n=\"5867\">89</sup> זה שהו\"ע גילוי עצמות אא\"ס שלפני הצמצום, אז ממילא ממלאים כל החסרונות והפגמים שנעשה מחמת העדר קיום התומ\"צ, וזהו\"ע ממעמקים קראתיך הוי'<sup data-n=\"5868\">90</sup> שע\"י עומק הלב שלמעלה מן החכמה מעוררים המשכת שם הוי' מחדש כו'. והנה זהו\"ע ג' מיני אה', ואהבת בכל לבבך<sup data-n=\"5869\">91</sup> זהו ברית דמילה כי יש מילה ברוחני' ומלתם את ערלת לבבכם<sup data-n=\"5870\">92</sup> להסיר התאווה ומדות רעות וממילא יהי' האהבה בכל לבבך רק לה' לבדו, ובכל נפשך הוא ברית דתורה לקשר רוחא ברוחא ונשמתא כו', ובכל מאדך הוא בחי' התשובה שהוא למעלה מבחי' כלי הלב ונק' חילא יתיר כו' וד\"ל.\n<b>והנה</b> בחי' זאת הוא בחי' יעקב כי הנה יעקב א' אם יהי' אלקים עמדי<sup data-n=\"5871\">93</sup> ונתן לי לחם לאכול ובגד ללבוש והכוונה שבחי' אלקים שהוא בחי' החושך יהי' עמדי בבחי' טפל ובטל לגבי האור והיינו ע\"י ב' היחודים הנ\"ל דשילוב הוי' באדני ואדני בהוי' וזהו\"ע לחם לאכול ובגד ללבוש שהו\"ע התומ\"צ<sup data-n=\"5872\">94</sup> שנק' מזון ולבוש ועל",[["5864","86","<b>ונהר יחרב וייבש</b>: ישעי' יט, ה. איוב יד, יא. ראה זהר בהקדמה ו, ב. בראשית כו, א. שמות ט, ב. לקו\"ת במדבר יג, סע\"ג. מאמרי אדה\"א במדבר ח\"ב ע' תרלה ואילך. סה\"מ תרכ\"ז ס\"ע רט ואילך. וש\"נ."],["5865","87","<b>התשובה שהוא בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. תו\"ח שמות ח\"א לז, א. וש\"נ. לעיל ע' קפח ואילך."],["5866","88","<b>שהו\"ע</b>: א: ויחודם הוא ענין."],["5867","89","<b>מגלה עמוקות מיני חושך</b>: איוב יב, כב."],["5868","90","<b>ממעמקים קראתיך הוי'</b>: תהלים קל, א."],["5869","91","<b>ואהבת בכל לבבך</b>: ואתחנן ו, ה [בדילוג]."],["5870","92","<b>ומלתם את ערלת לבבכם</b>: עקב י, טז. ראה גם תו\"א מקץ לא, א. ג. תו\"ח שם ריט, ב ובהערה 25."],["5871","93","<b>אם יהי' אלקים עמדי</b>: ויצא כח, כ [בדילוג]."],["5872","94","<b>לחם לאכול ובגד ללבוש. . התומ\"צ</b>: ראה תניא פ\"ה. מאמרי אדה\"א שמות ח\"א ע' כב. ויקרא ח\"ב ע' תתכ. וש\"נ. דברים ח\"ג ע' א'עט."]]],[4801940521,"ידם נמשך האור ומתגלה בתוך החושך, אך זהו בחי' יעקב יו\"ד עקב<sup data-n=\"5873\">95</sup> שבחי' יו\"ד דחכמה עילאה נמשך ומאיר בעקב אבל אח\"כ א' והי' הוי' לי לאלקים שזהו\"ע מדתו העליונה בחי' התעוררות רחמים רבים שעי\"ז ממשיכין מבחי' אא\"ס עצמו אשר לפני הצמצום שהוא למעלה מבחי' היו\"ד דשם הוי' כנ\"ל, ולגבי עצמות אא\"ס גם הוי' כאלקים חשיב<sup data-n=\"5874\">96</sup> כי נמשך ע\"י צמצום האור כנ\"ל, ובחי' זאת נמשך ע\"י התשובה והתעוררות רחמים דייקא. ועם זה יובן ענין הנ\"ל שכאשר שמים קדמה לארץ שזהו כסדר ההשתל' בתחי' מדת יום שהוא בחי' יחו\"ע ואח\"כ מדת לילה בחי' יחו\"ת וזהו ג\"כ ענין שמים קדמה לארץ וגם אברהם קודם ליצחק [כי אברהם הוא בחי' החסד<sup data-n=\"5875\">97</sup> מקור בנין עולם האצי' ויצחק הוא בחי' גבו'<sup data-n=\"5876\">98</sup> מקור בנין המל'<sup data-n=\"5877\">99</sup> שהוא מקור הנבראים כו'], אבל כאן נאמר והארץ אזכור שמעוררים שרש הארץ שהו\"ע סוף מעשה כמו שעלה במחשבה תחילה שהוא לפני הצמצום וזהו א\"א כ\"א ע\"י זכרון ברית דיעקב שהו\"ע התשובה והתעוררות ר\"ר כו' וד\"ל.\n<b>ומעתה</b> י\"ל מש\"א יעקב מלא בוי\"ו, כי הנה בחי' יעקב נק' בריח התיכון<sup data-n=\"5878\">100</sup> שמבריח מן הקצה לקצה והיינו מן הקצה היותר עליון שהוא בחי' עצמות אא\"ס עד למטה בעשי' גשמי', והטעם בזה כי כאשר אין הגילוי נמשך רק מבחי' ממכ\"ע אז הגילוי הוא בדרך השתלשלות ולא יוכל לימשך בבחי' דומם גשמי משא\"כ כאשר הגילוי הוא מבחי' סוכ\"ע אז נמשך הגילוי גם בגוף הגשמי, וזהו\"ע תחה\"מ שיאיר אור הגילוי<sup data-n=\"5879\">101</sup> להחיות הגוף הגשמי הנעשה מעפר גשמי כי בבחי' סוכ\"ע שוה ומשוה<sup data-n=\"5880\">102</sup> כו'. והנה בחי' הגילוי דסוכ\"ע נעשה ע\"י בחי' וזכרתי בריתי יעקב שהו\"ע התשובה והתעוררות רחמים רבים אשר מעורר עצמות אא\"ס אשר לפני הצמצום כו' וזהו\"ע הוי\"ו המבריח מן הקצה לקצה כו'. והנה בחי' זאת הוא ג\"כ בחי' אלי' כי ההפרש בין אלי' לשאר הנביאים<sup data-n=\"5881\">103</sup> שבכולם נמשך גילוי אלקות בפנימי' לזכך נפשם משא\"כ אלי' עבודתו בקדש הי' להמשיך גילוי אלקות גם בחומר גופו הגשמי בחיצוני' עד שעלה בסערה השמימה<sup data-n=\"5882\">104</sup> כו' והיינו מצד שהמשיך מבחי'",[["5873","95","<b>יעקב יו\"ד עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ."],["5874","96","<b>הוי' כאלקים חשיב</b>: ראה גם לקו\"ת ש\"ש סז, ד. תו\"ח שמות ח\"א מח, ג ובהנסמן שם."],["5875","97","<b>אברהם. . החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["5876","98","<b>ויצחק. . גבו'</b>: ראה פרדס שער הכינויים שכ\"ב, פ\"ד. מאמרי אדה\"ז שם ובהנסמן במ\"מ לשם."],["5877","99","<b>גבו' מקור בנין המל'</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ה. מאמרי אדה\"א דברים ח\"א ע' ריח. וש\"נ. תו\"ח בשלח ח\"א רמד, א. וש\"נ. לעיל ע' רצא ואילך."],["5878","100","<b>יעקב נק' בריח התיכון</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ."],["5879","101","<b>הגילוי</b>: א: האלקי."],["5880","102","<b>שוה ומשוה</b>: ע\"פ פיוט (לימים נוראים) ”האוחז ביד מדת משפט\"."],["5881","103","<b>ההפרש בין אלי' לשאר הנביאים</b>: ראה גם לקמן בהביאור בסופו. תו\"ח בשלח ח\"א רז, א ובהנסמן שם. אוה\"ת בחוקותי ע' רי."],["5882","104","<b>אלי'. . שעלה בסערה השמימה</b>: ראה מל\"ב ב, יא. פרדס שער היכלות שכ\"ד, פי\"ג. פי\"ד. מאמרי אדה\"א נ\"ך ע' רלא. וש\"נ. סה\"מ תרל\"ב ח\"א ע' קיא. וש\"נ. תו\"ח בשלח ח\"א קצו, ג. וש\"נ."]]],[4801940549,"עצמות אא\"ס אשר שם הוי' כאלקים יחשב ולכן החזיר לבני דורו בתשובה [כי מתחילה היו עובדי הבעל כו'] עד שאמרו ב\"פ הוי' הוא האלקים<sup data-n=\"5883\">105</sup>, וב' פעמים הכוונה שהרגישו בחי' עצמות אא\"ס אשר שם הוי' כאלקים יחשב, ונמצא שבחי' אלי' הי' מעין הבחי' הנ\"ל שיאיר בתחה\"מ, ולכן יהי' הוא המבשר לתחה\"מ, רק ההפרש הוא שהוא עלה השמים מלמטה למעלה ובתחה\"מ יומשך למטה בעפר הגשמי, וראי' לזה כי עוה\"ב יהי' לנשמות בגופים<sup data-n=\"5884\">106</sup> ואעפ\"כ אין בו לא אכילה ושתי'<sup data-n=\"5885\">107</sup> והיינו מחמת שיתגלה בחי' סוכ\"ע ויוכל הגוף הגשמי להחיות מבחי' אלקות כו'. וזהו מה שלקח במשכון הוי\"ו דאלי' שהוא בחי' העלי' שלו מלמטה למעלה שהוא בחי' העלאת מ\"ן לבחי' סוכ\"ע שמבחי' זאת יתגלה אח\"כ ההמשכה מלמעלה למטה בתחה\"מ להחיות הגוף גשמי שזהו בחי' הוי\"ו דיעקב כו' וד\"ל.\n<b>וזהו</b> וזכרתי את בריתי יעקב שהוא התעוררות העצמי' דסוכ\"ע שלפני הצמצום, אך בחי' זאת יאיר ג\"כ בשני היחודים דשילוב הוי' באדני ואדני בהוי' [כי אעפ\"י שיאיר בחי' גבוה יותר מ\"מ גם הם לא יתבטלו ממציאותם ובהם גופא יאיר בחי' הנ\"ל] שזהו בריתי יצחק ובריתי אברהם, כי הנה מבואר במדרש<sup data-n=\"5886\">108</sup> ויקרא אלקים לאור יום<sup data-n=\"5887\">109</sup> זה אברהם ולחשך קרא לילה זה יצחק כמא' ותכהנה עיניו<sup data-n=\"5888\">110</sup> כו' כי יצחק הוא בחי' הגבורה מקור בנין המל' להיות נבראים בבחי' יש נפרד, אך עיקר הכוונה להמשיך בחי' גילוי אלקות בבחי' היש שמזה נעשה בחי' תענוג למעלה שנק' בחי' צחוק כמשל הצחוק שעושין לפני שרים<sup data-n=\"5889\">111</sup> שהוא מדבר שיש בו שינוי דייקא כך כאשר נברא יש מאין שהוא בחי' חושך וצמצום ואח\"כ ממשיכין בו בחי' אור אלקי ע\"י תומ\"צ מזה נעשה בחי' עונג גדול למעלה הנק' צחוק, וזהו\"ע הזכרת מדת יום בלילה ושילוב הוי' באדני, אך בחי' אברהם הוא בעצם מדת יום ומדת לילה נכלל בו שזהו\"ע העקידה שהוא לאכללא<sup data-n=\"5890\">112</sup> שמאלא בימינא<sup data-n=\"5891\">113</sup> כמאמר והאלקים נסה את אברהם<sup data-n=\"5892\">114</sup>, ונמצא שבחי' גילוי העליון הנ\"ל דבריתי יעקב יהי' נמשך גם בבחי' יצחק ואברהם אך העיקר הוא והארץ אזכור והוא מה שיומשך גילוי אלקות בדומם הגשמי להחיות הגופים גשמי' כו' וד\"ל.",[["5883","105","<b>ב\"פ הוי' הוא האלקים</b>: מל\"א יח, לט. ראה גם לקו\"ת ש\"ש סד, ג. ואילך"],["5884","106","<b>עוה\"ב יהי' לנשמות בגופים</b>: ראה גם מאמרי אדה\"ז תק\"ע ע' כו. מאמרי אדה\"א ויקרא ח\"א ע' קלה. הנחות תקע\"ז ע' קכה. וש\"נ. אוה\"ת פסח כרך ד ע' תתקצח. סה\"מ תרכ\"ט ס\"ע כא ואילך. וש\"נ. לעיל ע' שב."],["5885","107","<b>עוה\"ב. . אין בו לא אכילה ושתי'</b>: ראה ברכות יז, א."],["5886","108","<b>במדרש</b>: באוה\"ת כאן ע' תרצ: בזח\"א תולדות קמא סע\"ב. ראה שם ואילך."],["5887","109","<b>ויקרא אלקים לאור יום</b>: בראשית א, ה."],["5888","110","<b>ותכהנה </b>[א: ותכהן]<b> עיניו</b>: תולדות כז, א [ושם: ותכהין]."],["5889","111","<b>כמשל הצחוק שעושין לפני שרים</b>: ראה גם תו\"ח ח\"ש קכח, א ובהערה 13."],["5890","112","<b>העקידה שהוא לאכללא</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קל. תו\"ח תולדות קמז, ד. קנב, ד. מאמרי אדה\"א דברים ח\"ד ע' א'תלג. וש\"נ."],["5891","113","<b>לאכללא שמאלא בימינא</b>: ראה זהר ר\"פ קרח."],["5892","114","<b>והאלקים נסה את אברהם</b>: וירא כב, א."]]],[4801940138,"<b>רש\"ד מה ששמעתי מאדמו\"ר ואיני זוכר אם הוא ממש כמו שנשמע יום א' פ' הנ\"ל</b>\n<b>להבין</b> שרשי הדברים הנ\"ל<sup data-n=\"5893\">1</sup>, הנה מתחילה י\"ל בחי' מדת יום ובחי' מדת לילה<sup data-n=\"5894\">2</sup> מהו, ויובן ע\"פ מארז\"ל כברייתו של עולם ברישא חשוכא<sup data-n=\"5895\">3</sup> והדר נהורא להיות ידוע אשר ע\"ס דאצי' הם בתכלית היחוד בעצמות המאציל והיינו מחמת שאא\"ס מאיר בגילוי בתוך הכלים וזהו בחי' ז\"א דאצי' אשר כלול מע\"ס והוא מקור בלבד לעולמות הנבראים, אך כאשר צריך להיות נמשך האור מאצי' לבי\"ע להיות התהוות הנבראים בפו\"מ הוא ע\"י התלבשות האור במדת המלוכה, וגם בחי' מדת המלוכה אינה מאירה בנבראים בגילוי רק ע\"י פרסא המפסיק שהוא כדוגמת המשל המסתיר לגמרי אור השכל כו' כנ\"ל<sup data-n=\"5896\">4</sup>, ולכן כל הנבראים נק' בשם מדת לילה. אך זהו מדת יום בפ\"ע ומדת לילה בפ\"ע אבל בחי' ברית הוא מלשון התחברות והתקשרות, ומש\"א אם לא בריתי<sup data-n=\"5897\">5</sup> יומם ולילה קאי על ברית דתורה וברית מילה שמחבר יום ולילה להיות מהות אחד כמאמר ויהי ערב ויהי בוקר יום אחד<sup data-n=\"5898\">6</sup>. וביאור הדברים ע\"פ המבואר בס\"י כרת לו ברית<sup data-n=\"5899\">7</sup> בין עשר אצבעות ידיו והוא ברית הלשון ובין עשר אצבעות רגליו והוא ברית המעור ומבו' הקושי'<sup data-n=\"5900\">8</sup> בפרד\"ס<sup data-n=\"5901\">9</sup> דא\"כ הם עשרים בחי' ובאמת עשר ולא תשע ולא אחד עשר והתירוץ הוא שע\"ס דאצי' הם כנגד אצבעות הידים משא\"כ עשר אצבעות הרגלים הם ע\"ס דבי\"ע שהם בחי' צל והארה מע\"ס דאצי'.\n<b>וביאור</b> הדברים הנה שתי ידים הם באצי' [ולכן ביכולת להגביהם למעלה מן הראש] וכמארז\"ל נטה הקב\"ה ימינו<sup data-n=\"5902\">10</sup> וברא השמים שהוא ז\"א שהוא מבחי' החסד משא\"כ הארץ שהוא בחי' מל'<sup data-n=\"5903\">11</sup> בניינה מה\"ג<sup data-n=\"5904\">12</sup> וזהו נטה הקב\"ה שמאלו וברא את הארץ וכדוגמת הדיבור המתחלק ע\"י ה' מוצאות הפה ונמצא שתי ידים הם מקור שמים וארץ שהוא בחי' זו\"נ דאצי'. אך ארז\"ל גדולים מעשה צדיקים<sup data-n=\"5905\">13</sup> ממעשה שמים וארץ דאילו במעשה שמים כתיב אף ידי<sup data-n=\"5906\">14</sup> כו' יד א' בלבד משא\"כ במעשה",[["5893","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר זה הוא ביאור על מאמר ד\"ה וזכרתי הר\"ת שנדפס לפנ\"ז."],["5894","2","<b>מדת יום ובחי' מדת לילה</b>: ראה ברכות יא, ב. יב, א."],["5895","3","<b>כברייתו. . ברישא חשוכא</b>: שבת עז, ב (כגי') רש\"י. ראה תו\"ח וארא ח\"א מט, ג ואילך. הנסמן בסה\"מ תרכ\"ז ע' תנד."],["5896","4","<b>כנ\"ל</b>: בהמאמר פיסקא ולהבין כל הנ\"ל ואילך."],["5897","5","<b>אם לא בריתי</b>: ירמי' לג, כה. ראה אוה\"ת בחוקותי כרך א ע' רג. ירמי' כרך א ע' שפד. לעיל בהמאמר פיסקא ולהבין כל הנ\"ל."],["5898","6","<b>ויהי ערב ויהי בוקר יום אחד</b>: בראשית א, ה."],["5899","7","<b>בס\"י כרת לו ברית</b>: ראה שם בסופו. פ\"א, מ\"ג."],["5900","8","<b>הקושי' בפרד\"ס</b>: ראה שם בתחילתו."],["5901","9","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט ובהערה 293."],["5902","10","<b>נטה הקב\"ה ימינו</b>: ראה פדר\"א פי\"ח. תו\"א וארא נו, ב. וראה גם להבא לקמן לקו\"ת נשא כא, ב ואילך. סה\"מ תרל\"ג ח\"ב ע' שסה ואילך."],["5903","11","<b>השמים שהוא ז\"א. . הארץ. . מל'</b>: ראה גם לעיל ע' קנה ובהערה 9."],["5904","12","<b>מל' בניינה מה\"ג</b>: ראה גם לעיל ע' רצב."],["5905","13","<b>גדולים מעשה צדיקים</b>: ראה כתובות ה, א."],["5906","14","<b>אף ידי</b>: ישעי' מח, יג."]]],[4801940202,"צדיקים כתיב מקדש ה' כוננו ידיך<sup data-n=\"5907\">15</sup> ב' ידים, ומבוא' הקושי' דהלא גם מעשה שמים וארץ הוא ע\"י ב' ידים יד ימין ויד שמאל כנ\"ל, וכמבו' בכתוב אף ידי כו' שהוא יד שמאל וימיני טפחה כו'. אך התירוץ הוא דבמעשה שו\"א כל יד מאירה בפ\"ע ופועלת פעולתה משא\"כ במעשה צדיקים מתייחדים שני הידים כא' שמוכרח להיות מכח הנעלה משניהם והיינו ע\"י התורה שהוא בחי' ברית הלשון ששרשה בדעת הכולל חו\"ג<sup data-n=\"5908\">16</sup> ועכ\"ל<sup data-n=\"5909\">17</sup> ששרש הדעת הוא למעלה מהשפעת קוין והיינו כמבואר בס\"י וברית יחיד<sup data-n=\"5910\">18</sup> מכוון באמצע ששרש המחבר הנק' ברית הוא בבחי' יחיד שלמעלה מאחד<sup data-n=\"5911\">19</sup> שהוא בחי' חד ולא בחושבן<sup data-n=\"5912\">20</sup> י\"ס דאצי' כלל, ולכן גדולים מעשה צדיקים שהו\"ע התורה הנק' מקדש ה' שמאיר בו כח יותר עליון לכלול ב' הידים כא' כו' וד\"ל. וזהו בריתי יומם ולילה שהוא בחי' דעת הכולל חו\"ג שנק' יום ולילה<sup data-n=\"5913\">21</sup> כו'. ועוד יש לפרש בפי' בריתי שהוא בחי' ברית המעור והיינו כרת לו ברית בין עשר אצבעות רגליו, כי הנה כתיב והארץ הדום רגלי<sup data-n=\"5914\">22</sup> שבחי' רגל הוא הארה והשפעה הנמשכת מאצי' לבי\"ע ע\"י בחי' המל' דייקא, מלכותך מלכות כל עולמים<sup data-n=\"5915\">23</sup> [וכידוע בכתבי האריז\"ל דמנה\"י דז\"א נמשך בחי' מוחין במל'<sup data-n=\"5916\">24</sup> כו']. והנה המשכה זאת להמשיך מאצי' לבי\"ע הוא ע\"י המצות דייקא כידוע דרמ\"ח פיקודין הוא רמ\"ח אברים דמלכא<sup data-n=\"5917\">25</sup> שהוא תוס' אורות בבחי' החיצוני' הכלים דאצי' שעל ידם נמשך האור בבי\"ע וכמשל האבר המגלה חיות הנפש לחוץ דייקא כו', משא\"כ ע\"י התורה הגם שמתגלה תוס' אורות מ\"מ הוא רק להוסיף אורות באצי' והיינו לחבר מדת יום ולילה שבאצי' עצמו שהוא בחי' מל' דאצי' מקור הנבראים בלבד כו'.\n<b>והנה</b> כח זה גופא להמשיך בחי' המצות דאצי' שהם בחי' כלים דאצי' שיאירו למטה בנשמות במצות הגשמי' עד שעל ידם יאיר האור למטה בעשי' גשמי' הוא ע\"י ישראל דייקא שיש להם מצות מילה שהוא בחי' יסוד וכח היסוד הוא לחבר אצי' ובי\"ע והיינו שיומשך האור למטה כמו למעלה [ונק' ג\"כ ברית יחיד מצד שהוא עולה עד פנימי' הכתר<sup data-n=\"5918\">26</sup> כידוע] וכמשל ברית הממשיך כח רוחני מכל האברים להוליד בדומה לו בגשמי' כנ\"ל בתו'. וזהו\"ע שלש<sup data-n=\"5919\">27</sup> רגלים תחוג כו' כי",[["5907","15","<b>מקדש ה' כוננו ידיך</b>: בשלח טו, יז."],["5908","16","<b>בדעת הכולל חו\"ג</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ג. מאמרי אדה\"א בראשית ע' ד. וש\"נ. תו\"ח וארא ח\"א נז, ד הערה 14."],["5909","17","<b>ועכ\"ל</b>: כ\"ה בהכת\"י."],["5910","18","<b>בס\"י וברית יחיד</b>: ראה שם פ\"א, מ\"ג."],["5911","19","<b>יחיד שלמעלה אחד</b>: ראה גם לעיל ע' קצג. תו\"א וארא נה, ב. מאמרי אדה\"א בראשית ע' תק. וש\"נ. תו\"ח שמות ח\"א מז, א. וש\"נ. סה\"מ תרכ\"ז ע' קע. וש\"נ. תרכ\"ט ע' לא. וש\"נ."],["5912","20","<b>חד ולא בחושבן</b>: ת\"ז בהקדמה יז, א."],["5913","21","<b>חו\"ג שנק' יום ולילה</b>: ראה גם מאמרי אדה\"א שמות ח\"א ס\"ע קמא ואילך. נ\"ך ע' קכט."],["5914","22","<b>והארץ הדום רגלי</b>: ישעי' סו, א."],["5915","23","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."],["5916","24","<b>דמנה\"י דז\"א. . מוחין במל'</b>: ראה ע\"ח שער תקון הנוקבא של\"ד, פ\"ב כלל ו. שער כסה\"כ שמ\"ו, פ\"ה. פע\"ח שער ק\"ש שעהמ\"ט שט\"ז, פ\"ג."],["5917","25","<b>דרמ\"ח פיקודין הוא רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["5918","26","<b>היסוד. . שהוא עולה עד פנימי' הכתר</b>: ראה גם לעיל ע' עד."],["5919","27","<b>שלש רגלים תחוג</b>: משפטים כג, יד."]]],[4801940259,"אצל מלאכים כתיב ורגליהם רגל<sup data-n=\"5920\">28</sup> ישרה<sup data-n=\"5921\">29</sup> שאין להם רק שתי רגלים [שהוא בחי' נו\"ה כו' ולא יוכלו להמשיך רק הארה בעלמא] משא\"כ בנשמות יש להם רגל שלישי שהוא בחי' היסוד ולכן יש להם כח להמשיך עצמות האור כמ\"ש כו' [והנה בחי' זאת נק' בס\"י כרת לו ברית בין עשר אצבעות רגליו, כי כמו למעלה באצי' שו\"א הם זו\"נ ובנין הז\"א הוא מהחסדים הנק' יד ימין ובנין הנוק' הוא מהגבור' הנק' יד שמאל כן בבי\"ע בחי' עולם הברי' נק' שמים ושם הוא געה\"ע שמאיר בו רגל ימין ובחי' עולם העשי'<sup data-n=\"5922\">30</sup> נק' ארץ ושם הוא געה\"ת<sup data-n=\"5923\">31</sup> שמאיר בו רגל שמאל ובחי' יסוד הוא מייחד ומחבר גילוי האור ממש למטה עד עשי' גשמי' כו' וד\"ל]. וזהו או יחזיק במעוזי<sup data-n=\"5924\">32</sup> יעשה שלום לי ע\"י ברית דתו' שהוא בבחי' הדעת הנק' ברית הלשון, ושלום יעשה לי הוא ברית המעור המייחד אא\"ס בבי\"ע ע\"י המצות כו' וד\"ל.\n<b>וזהו</b> אם לא בריתי יומם, כי הנה יומם הוא תוס' אורות יותר מבחי' יום, והוא בחי' עננא דאהרן שהוא בחי' חסד דאבא<sup data-n=\"5925\">33</sup> [משא\"כ בחי' יום הוא חסד דז\"א כו'] וגילוי בחי' זאת הוא ע\"י המצות דייקא כי מחמת שהמצות הם בירורי נוגה הם ממשיכים אורות דתוהו וגורמים שיתגלה בחי' גבוה יותר הנק' יומם כו' וד\"ל. והנה כ\"ז הוא כשיש בחי' ברית דתומ\"צ שעי\"ז גורם תוס' אורות גם בהשתלשלות הנק' חוקות שמים וארץ, משא\"כ כשיש ביטול תורה ח\"ו ופגם הברית ח\"ו אז כתיב ונהר יחרב ויבש<sup data-n=\"5926\">34</sup> שנפסק בחי' תוס' אורות ואינו נמשך רק בחי' האור בצמצום וכידוע בזהר דמעת חורבן הבית גננא לא עאל בגנתא<sup data-n=\"5927\">35</sup> כי גננא הוא בחי' יסוד שמסתלק למעלה ואינו ממשיך תוס' אורות חדשים במל' רק מגרמי' אזדרע שנק' ספיחים כו'. והנה לזה אין מועיל ענין התומ\"צ רק ע\"י התשובה מעומקא דליבא והתעוררות רחמים רבים על נפשו מעורר מפנימי' ועצמות אא\"ס שלמעלה משם הוי' להמשיך אורות חדשים וכמשל כשיבש הנהר חופרים בעומק יותר, והו\"ע יחוד השני דהוי' הוא האלקי' כנ\"ל בתו', ועי\"ז מחזירים בחי' היסוד שיאיר במל' וכמאמר בשוב ה' את ציון<sup data-n=\"5928\">36</sup> ולא נאמר בשוב ה' לציון שהכוונה להשיב בחי' ציון שהוא בגי' יוסף<sup data-n=\"5929\">37</sup> בחי' יסוד<sup data-n=\"5930\">38</sup> למקומו שיאיר במל' כו' וד\"ל.",[["5920","28","<b>רגלים. . רגל</b>: ראה אוה\"ת משפטים ע' א'קעד ואילך. סה\"מ תרל\"ח ע' תלט ובהערה 60."],["5921","29","<b>ורגליהם רגל ישרה</b>: יחזקאל א, ז."],["5922","30","<b>הברי'. . געה\"ע. . העשי'. . הוא געה\"ת</b>: ראה גם לעיל ע' תו ובהערה 39."],["5923","31","<b>שמים. . געה\"ע. . ארץ. . געה\"ת</b>: ראה גם לעיל ע' קיא ובהערה 70."],["5924","32","<b>או יחזיק במעוזי</b>: ישעי' כז, ה."],["5925","33","<b>יומם. . עננא דאהרן. . חסד דאבא</b>: ראה אוה\"ת בחוקותי כאן ע' תרפז: זהר אמור ק\"ג ב'. . ופירש בסידור שער חג הסוכות [רנח, ב] שהוא חסד שבחכמה ע\"ש. וראה גם שם סדר הגדה חצר, ג."],["5926","34","<b>ונהר יחרב ויבש</b>: ישעי' יט, ה. איוב יד, יא."],["5927","35","<b>גננא לא עאל בגנתא</b>: ראה זהר תרומה קסו, ב ואילך. ביאוה\"ז להצ\"צ כרך ב ע' תתיח ואילך."],["5928","36","<b>בשוב ה' את ציון</b>: ישעי' נב, ח [בהוספת תיבת: ”את\"]. ראה זהר בשלח נה, ב. אוה\"ת ויקרא כרך א ע' רסא."],["5929","37","<b>ציון שהוא בגי' יוסף</b>: בלקו\"ת דברים א, ג: בלק\"ת [להאריז\"ל] פ' ויצא [ל, כד]."],["5930","38","<b>יוסף בחי' יסוד</b>: ראה זהר רע\"מ פינחס רלו, א. פרדס שעה\"כ שכ\"ג, פ\"י מערכת יוסף. לעיל מאמר ד\"ה בשברי לכם תקצ\"ט ובהערה 49."]]],[4801940312,"<b>ועתה</b> י\"ל ענין וזכרתי את בריתי יעקב<sup data-n=\"5931\">39</sup> מלא בוי\"ו<sup data-n=\"5932\">40</sup> והוא הוי\"ו שנטל במשכון מאלי'<sup data-n=\"5933\">41</sup> כי הנה ידוע בכהאריז\"ל שבחי' הקו מאיר בו מבחי' עצמות אא\"ס שלפני הצמצום<sup data-n=\"5934\">42</sup>, והנה עצם בחי' הקו\"ח הוא גנוז בא\"ק<sup data-n=\"5935\">43</sup> ורק הארתו מאיר באצי' והארה דהארה ממנו מאיר בבי\"ע. והנה לע\"ל בתחה\"מ יאיר בחי' עצם הקו\"ח הגנוז בא\"ק ועי\"ז יוכל להחיות גם הגוף גשמי והוא ענין הוי\"ו דיעקב, והנה הוי\"ו דיעקב מאיר בבחי' יוסף<sup data-n=\"5936\">44</sup> צדיק עליון אך בחי' אלי' זכה ג\"כ לבחי' עצם אור הקו\"ח ועי\"ז זיכך חומר גופו הגשמי עד שעלה בסערה השמי'<sup data-n=\"5937\">45</sup> כי אפי' משרע\"ה<sup data-n=\"5938\">46</sup> שהי' גבוה ממנו הרבה בבחי' הביטול דשם מ\"ה מ\"מ לא זיכך לחומר גופו כמו אלי' [ומה שלחם לא אכל הי' רק ארבעים יום<sup data-n=\"5939\">47</sup> ] מצד שבבחי' הביטול והבירור דשם ב\"ן הי' אלי' גבוה מכל הנבראים ולכן עלה בסערה השמי'. אך מצד שהבירור שלו הי' מבחי' בירור דשם ב\"ן [והוא בחי' צ\"ת] לכן עלה השמים בדרך עלי', ועלי' זאת גורמת המשכה שבתחה\"מ והוא הוי\"ו דיעקב ולכן יהי' הוא המבשר כו' וד\"ל.",[["5931","39","<b>וזכרתי את בריתי יעקב</b>: בחוקותי כו, מב."],["5932","40","<b>יעקב מלא בוי\"ו</b>: ראה גם לעיל בפנים המאמר ובהערה 5."],["5933","41","<b>יעקב. . במשכון מאלי'</b>: ראה רש\"י בחוקותי כאן. לעיל בהמאמר הערה 8."],["5934","42","<b>הקו מאיר. . שלפני הצמצום</b>: ראה ע\"ח דרוש עגו\"י ש\"א ענף ב. מבוא שערים ש\"א ח\"א, פ\"ב. הגהת הרמ\"ז לאוצ\"ח בתחילתו (הגהה יא). אוה\"ת (יהל אור) תהלים ע' קצ."],["5935","43","<b>עצם בחי' הקו\"ח הוא גנוז בא\"ק</b>: ראה גם אוה\"ת בלק ע' תתקפד."],["5936","44","<b>הוי\"ו דיעקב מאיר בבחי' יוסף</b>: ראה גם סה\"מ תרל\"ח ע' ל. וש\"נ."],["5937","45","<b>אלי'. . בסערה השמי'</b>: ראה מל\"ב ב, יא. לעיל בהמאמר הערה 104."],["5938","46","<b>אלי'. . משרע\"ה</b>: ראה גם לעיל בהמאמר ובהערה 103."],["5939","47","<b>שלחם לא אכל. . רק ארבעים יום</b>: ראה תשא לד, כח. עקב ט, יח."]]],[4801940139,"<b>להבין</b> שרשי הדברים דביאור הזוהר ע\"פ ונתתי משכני<sup data-n=\"5940\">1</sup> בתוככם<sup data-n=\"5941\">2</sup> ילה\"ק ענין ארוממך אלקי המלך<sup data-n=\"5942\">3</sup> ואברכה שמך לעולם ועד, שמך העצמי כו'. וביאור הדברים אי' בפר\"א קודם שנבה\"ע הי' הוא ושמו בלבד<sup data-n=\"5943\">4</sup>, וביאור ענין<sup data-n=\"5944\">5</sup> קודם שנברא היינו למעלה אפילו מבחי' א\"ק שגם הוא נק' אדם דבריאה<sup data-n=\"5945\">6</sup> כמבואר בע\"ח. והנה בחי' הוא ושמו הוא בחי' מאור ואור כי שמו הוא בחי' אור וזיו והיה<sup data-n=\"5946\">7</sup> שניהם בלבד כו' ונכללין<sup data-n=\"5947\">8</sup> בבחי' עצמו' אא\"ס שלפני הצמצום שהוא עדיין בחי' לבדו ממש כמאמר<sup data-n=\"5948\">9</sup>",[["5940","1","<b>להבין שרשי הדברים דביאור הזוהר ע\"פ ונתתי משכני בתוככם</b>: כנראה דרוש ר' הלל."],["5941","2","<b>הזוהר ע\"פ ונתתי משכני בתוככם</b>: בחוקותי קיד, א. בחוקותי כו, יא."],["5942","3","<b>ארוממך אלקי המלך</b>: תהלים קמה, א."],["5943","4","<b>בפר\"א קודם שנבה\"ע הי' הוא ושמו בלבד</b>: ראה שם פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."],["5944","5","<b>ענין</b>: ג: ליתא."],["5945","6","<b>א\"ק. . אדם דבריאה</b>: ראה ע\"ח שער סדר אצי' ש\"ג, רפ\"א."],["5946","7","<b>והיה</b>: אג: והמה."],["5947","8","<b>כו' ונכללין</b>: שם: פי' נמצאו נכללין."],["5948","9","<b>כמאמר</b>: שם: כמ\"ש."]]],[4801940203,"וכל מאמינים שהוא לבדו הוא<sup data-n=\"5949\">10</sup> (כמשי\"ת). והנה בבחי' הוא ושמו יש ב' פי', הא' ע\"פ המבואר בשער היחוד [פ\"י וי\"א] בענין בריש הורמנותא דמלכא<sup data-n=\"5950\">11</sup> גליף גליפו כו' שזהו כשעלה ברצונו הפשוט להיות חפץ חסד וטוב שזהו בחי' הארה בעלמא מבחי' חסד ההיולי הכלול ומיוחד בהעלם העצמו' עד שאינו נבדל כלל ממנו<sup data-n=\"5951\">12</sup> ולא שייך בו לומר אפי' לשון התאחדות יעו\"ש היטיב. והנה רצון הזה נשתלשל עד המל' והוא התלבשותו במח' דא\"א<sup data-n=\"5952\">13</sup> אך אח\"כ גליף גליפו הוא בבחי' חקיקת אותיו' שהוא מה ששיער בעצמו בכח<sup data-n=\"5953\">14</sup> מה שעתיד להיות בפועל ממש<sup data-n=\"5954\">15</sup>, אך הנה ידוע ומובן שהגם מה שעתיד להיות בפועל המה הכל דברי' מוגבלים אך בשרשם כמו שהמה משוערים בעצמו שזהו אמיתת מציאותם ושרש הוויתם אח\"כ בפועל ממש המה בבחי' א\"ס, והנה ע\"ז<sup data-n=\"5955\">16</sup> יובן ענין הוא ושמו כי הוא הוא בחי' מאור שזהו בחי' ח\"ח<sup data-n=\"5956\">17</sup> הנ\"ל שהוא מקור לבחי' גילוי אור אבל בעצמו אינו מתגלה כלל רק הוא סיבת כל הסיבות<sup data-n=\"5957\">18</sup> להתגלות בחי' האור שהוא בחי' האותיות דגליף גליפו כו'.\n<b>ויובן</b> מבשרי אחזה<sup data-n=\"5958\">19</sup> כשמתעורר בעצמו בבחי' חסד וטוב להשפיע שכל או ממון הנה השכל או הממון שמשפיע הוא עצם השפע ולא יגיע כלל לבחי' החסד שבלבו כי החסד נשאר בהעלם בלבו רק נעשה סיבה להשפעה בלבד כו' וד\"ל. וע\"ז<sup data-n=\"5959\">20</sup> יובן מש\"א בש\"ע כי אל טוב ומטיב אתה כו', כי אל<sup data-n=\"5960\">21</sup> טוב הוא בחי' טבע הטוב שהוא בחי' חסד ההיולי הכלול בעצמותו שהוא בחי' יחיד ממש, ומטיב הוא מה שעלה ברצון הפשוט<sup data-n=\"5961\">22</sup> להטיב שהוא הארה בעלמא מעצם הטוב כנ\"ל. ומברך השנים זהו בחי' ברכה והמשכה בבחי' האותיות דגליף גליפו כו' שנק' שנים ע\"ש שהמה משנים ממהות למהות היינו מבחי' א\"ס לבחי' בע\"ג כו'. ועד\"ז יובן ג\"כ ענין ברוך שאמר והי' העולם שזהו מה שאמר בעצמו<sup data-n=\"5962\">23</sup> מקור להוויית העולם, שזהו מה שעלה ברצון הפשוט<sup data-n=\"5963\">24</sup> להטיב, ואח\"כ ברוך הוא שזהו\"ע הדילוג בעצמותו להיות ברוך אומר ועושה שזהו מה דגליף גליפו שהוא בחי' אותיות המקור לעשי', והיינו מה ששיער בעצמו מה שעתיד להיות בפועל, אך הגם שכבר שיער כל הפרטים העתידים לבוא לידי פועל<sup data-n=\"5964\">25</sup> והוגבל המספר אבל מ\"מ כל מציאות פרטי להיותו",[["5949","10","<b>וכל מאמינים שהוא לבדו הוא</b>: חרוז בפיוט (לימים נוראים) ”האוחז ביד מדת משפט\"."],["5950","11","<b>בריש הורמנותא </b>[אג: הורמנא]<b> דמלכא</b>: ראה זהר בראשית טו, א. לעיל ע' תמד הערה 61."],["5951","12","<b>כלל ממנו</b>: אג: ממנו כלל."],["5952","13","<b>במח' דא\"א </b>[אג: דאנא אמלוך]: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ז: וכמ\"ש בזהר בפי' וימלוך אנא אמלוך. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד."],["5953","14","<b>ששיער בעצמו בכח</b>: ראה מק\"מ לזהר בראשית טו, א. מאמרי אדה\"א קונטרסים ע' רא. וש\"נ. לעיל ע' פה ובהערה 30."],["5954","15","<b>ממש</b>: אג: ליתא."],["5955","16","<b>ע\"ז</b>: עם זה על דרך זה ראה לקמן הערה 20."],["5956","17","<b>ח\"ח</b>: אג: חפץ חסד."],["5957","18","<b>סיבת כל הסיבות</b>: ראה פרדס שער אם הא\"ס הוא הכתר ש\"ב, פ\"א."],["5958","19","<b>מבשרי אחזה</b>: איוב יט, כו."],["5959","20","<b>וע\"ז</b>: ג: ועד\"ז. ראה לעיל הערה 16."],["5960","21","<b>אתה. . אל</b>: תיבות אלו ניתוספו ע\"פ אג."],["5961","22","<b>ברצון הפשוט</b>: שם: ברצונו."],["5962","23","<b>בעצמו</b>: שם: בעצם."],["5963","24","<b>ברצון הפשוט</b>: שם: ברצה\"ע."],["5964","25","<b>לידי פועל</b>: א: ליתא."]]],[4801940260,"כלול בעצמו הוא בבחי' א\"ס עדיין לזאת הוצרך<sup data-n=\"5965\">26</sup> להיות גוזר ומקיים שהוא בחי' העלם כל עצמותו להיות נמשך רק פרט א' מן העצם עד\"מ הרב המצמצם שכלו ומשאיר נקודה אחת צורך השפעת המקבל והוא בחי' הרשימו שנשאר אחר הצמצום, ואח\"כ עושה בראשית הו\"ע מחה\"ק דא\"ק<sup data-n=\"5966\">27</sup> דצופה ומביט עד סוף כל הדורות כו'<sup data-n=\"5967\">28</sup> וד\"ל.\n<b>ומעתה</b> י\"ל ענין הפי' הב' בענין הוא ושמו בלבד שזהו הכל בבחי' יחיד שלמעלה מאחד [עיין בשער היחוד פ\"י וי\"א הנ\"ל]. וביאור הדברים הנה אנו אומרים וכל מאמינים שהוא לבדו הוא, וכל מאמינים שהוא כל יכול, כי הנה הפילוסופים אמרו שמהפשוט לא יוכל להיות ריבוי והתחלקות<sup data-n=\"5968\">29</sup>, אבל טח מראות עיניהם [כמ\"ש בס' גבורות ה'<sup data-n=\"5969\">30</sup> לגור ארי'] כי בזה נתנו לו גדר שהוא מופשט ומובדל מריבוי והתחלקות אבל באמת הפשוט אמיתי אשר לא יוגדר בסוג וגדר כלל יוכל להיות ממנו הכל אפי' ריבוי והתחלקות, וזהו מה שאנו מאמינים שהוא כל יכול, אך אע\"פ שהוא כל יכול זהו רק אורו וזיוו בלבד אבל בעצמותו הוא לבדו ממש גם אחר שנבה\"ע כמו קודם שנבה\"ע ממש בלי שינוי כלל וכמ\"ש אני הוי' לא שניתי<sup data-n=\"5970\">31</sup> שאין שינוי לפניו ית' שכמו שקודם שנבה\"ע הי' לבדו ממש כך אחר שנבה\"ע הוא ג\"כ לבדו ממש בלי שינוי כלל, כי כל העולמות אינם תופסים מקום כלל לפניו ית' ולא שייך לומר עליהם כלא חשיב<sup data-n=\"5971\">32</sup> רק אחר שנעשה מקור להשתלשלות אז שייך לומר כלא, אבל באמת זהו ג\"כ מציאות דבר מה אבל בעצמותו ממש המה בטילים במציאות לגמרי עד שאינו נופל עליהם אפי' לומר כלא כו', וע\"ז<sup data-n=\"5972\">33</sup> יובן ענין הוא ושמו בלבד כי שמו הוא גילוי אורו בלבד הכולל ע\"ס שבבחי' יחיד שזהו מה שביכולתו שיומשך ממנו בחי' חכ' ונק' חכ' דא\"ס ומה שביכולתו שיומשך ממנו בחי' בינה זהו בחי'<sup data-n=\"5973\">34</sup> בינה דא\"ס רק שם כל הע\"ס המה בבחי' א\"ס<sup data-n=\"5974\">35</sup> פי' שמחכ' הי' יכול להיות נמשך חכמות עד אין שיעור ולא ד' מיני חכ' דאבי\"ע רק מה שנמשך ד' מיני חכ' הוא מצד ששיער כו' וכן מבחי' בינה כו', והנה מלבד שכל הע\"ס המה בבחי' א\"ס עוד הי' יכול להאציל ספי' עד אין קץ<sup data-n=\"5975\">36</sup> רק מצד מה<sup data-n=\"5976\">37</sup> ששיער בעצמו להאציל רק עשר כו'. והנה זהו בחי' כל יכול להאציל עד",[["5965","26","<b>להיותו כלול. . הוצרך</b>: ג: ליתא. וכנראה נשמט מפני תיבות הדומות: להיותו. . להיות."],["5966","27","<b>מחה\"ק דא\"ק</b>: ראה מאמרי אדה\"א דברים ח\"ג ס\"ע תתפז ואילך ובהנסמן שם ובע' תתפח."],["5967","28","<b>דצופה ומביט. . כו'</b>: ראה ברכת זכרונות. ר\"ה יח, א. סהמ\"צ להצ\"צ ע' פב. תו\"ח שמות ח\"א מח, ב. וש\"נ."],["5968","29","<b>הפילוסופים אמרו שמהפשוט. . ריבוי והתחלקות</b>: ראה גם סידור שער המילה קמב, ג (אוה\"ת שבועות ע' קיג־ סידור ע' שיז). ביאוה\"ז בשלח מ, א. מאמרי אדה\"א ויקרא ח\"ב ע' תתקיח בשם הפרדס ובהנסמן שם. דרושי חתונה ח\"ב ס\"ע תלז."],["5969","30","<b>בספר גבורות ה'</b>: ראה שם בהקדמה שני'."],["5970","31","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["5971","32","<b>חשיב</b>: אג: ליתא."],["5972","33","<b>וע\"ז</b>: א: ועם זה. ג: ועד\"ז."],["5973","34","<b>בחי'</b>: א: נק' בחי'."],["5974","35","<b>א\"ס</b>: אג: או\"מ( )."],["5975","36","<b>ספי' עד אין קץ</b>: ראה גם לעיל ע' תמה ובהערה 76."],["5976","37","<b>מה</b>: ניתוסף ע\"פ אג."]]],[4801940313,"אין קץ זהו רק<sup data-n=\"5977\">38</sup> בחי' גילוי אורו בלבד. והנה המקור הנושא וסובל גילוי אור כזה בבחי' א\"ס הוא מהו\"ע ית' נק' בשם מאור שהוא אמיתית הכל יכול וזהו בחי' הוא ושמו אבל שניהם נכללים בלבד, כי אע\"פ דאיהו תפיס בכולהו עלמין<sup data-n=\"5978\">39</sup> מ\"מ<sup data-n=\"5979\">40</sup> לית מאן דתפיס בי' פי' איהו הוא בחי' היחוד<sup data-n=\"5980\">41</sup> הנתפס בכל פרט שעי\"ז קיום גילוי האור כי האור אין לו מציאות בלעדי המאור, אך כ\"ז הוא לגבי דהשתלשלות אבל לגבי מהו\"ע ית' אינם תופסים מקום כלל כנ\"ל רק הוא לבדו ממש לאחר שנברא העולם כמו קודם שנברא<sup data-n=\"5981\">42</sup> בלי שינוי כלל, וא\"כ בעצמותו לא שייך לומר לא מאור ולא אור כי בטילים ממש עד שהמה אין ואפס שם ממש, וזהו מה שהשמיענו בפר\"א ענין הביטול האמיתי דהשתלשלות בבחי' יחוד האמיתי שהוא בחי' אין עוד מלבדו כו' וד\"ל.\n<b>והנה</b> אנו אומרים בברכת המעריב כו' גולל אור מפני חושך וחושך מפני אור ושמעתי מאדמו\"ר נבג\"מ<sup data-n=\"5982\">43</sup> בתו' דהמגביהי לשבת<sup data-n=\"5983\">44</sup> דגולל אור מפני חושך הוא בחי' הצמצום פי' גולל אור עצמותו ומעלים אותו עד שלא נשאר רק כנקודה אחת בלבד שהוא בחי' הרשימו כנ\"ל, וחושך מפני אור היינו מה שנותן כח בבחי' הקו\"ח שיאיר מבחי' החושך וההעלם. והנה שרש של שתי הבחי' הוא בבחי' עצמות אא\"ס הנק' יחיד ולכן א' גולל דקאי על בחי' א\"ס בעצמו כמ\"ש לבדו ממש הנק' יחיד. והנה מה דגולל אור מפני חושך שהוא בחי' הצמצום של האור עצמו עד שלא נשאר רק רשימו הוא מבחי' המאור של האור, אבל חושך מפני אור שהוא מה שמאיר ההעלם דחושך העצמי שיבוא לידי גילוי אור שזהו שני הפכים שמה שנתפס בבחי' מציאות העלם שיבוא לידי גילוי<sup data-n=\"5984\">45</sup> זהו מבחי' לבדו שלמעלה מבחי' מאור ואור ולפניו שוין העלם וגילוי חושך ואור ולכן יוכל להביא את מה שכבר נתפס במציאות העלם שיבוא לידי גילוי אור ממש. וזהו ההפרש בבחי' הקו\"ח בין פנימי' הקו לחיצוני' הקו, כי חיצוני' הקו נמשך מהנקודה שהוא בחי' הרשימו<sup data-n=\"5985\">46</sup> אשר שרש הרשימו נעשה מכח הצמצום מצד המאור שקודם לאור כנ\"ל ומצד זה הוא שרש הכלים<sup data-n=\"5986\">47</sup> דאצי' שהוא מדידת כל אור שיתפס במציאות מוגבל ומחולק מחבירו אבל פנימי' הקו שהם<sup data-n=\"5987\">48</sup> בבחי' עצמו' אא\"ס [שזהו בחי' לבדו שלמעלה מבחי' מאור ואור כנ\"ל], ומצד זה נעשה התכללות שמאלא בימינא כו' ע' בשער היחוד פ'<sup data-n=\"5988\">49</sup>.",[["5977","38","<b>רק</b>: ניתוסף ע\"פ אג."],["5978","39","<b>דאיהו תפיס בכולהו עלמין</b>: ראה זהר רע\"מ פינחס רכה, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קפב. תו\"ח נח סו, ג הערה 30."],["5979","40","<b>מ\"מ</b>: ג: ליתא."],["5980","41","<b>היחוד</b>: ג: המאור."],["5981","42","<b>שנברא</b>: ג: שנבה\"ע."],["5982","43","<b>מאדמו\"ר נבג\"מ</b>: כ\"ק אדה\"א."],["5983","44","<b>בתו' דהמגביהי לשבת</b>: ראה מאמרי אדה\"א בראשית ע' תד."],["5984","45","<b>שזהו שני. . גילוי</b>: ג: ממש."],["5985","46","<b>חיצוני' הקו נמשך. . הרשימו</b>: ראה גם מאמרי אדה\"א קונטרסים ח, א. וש\"נ. תו\"ח בשלח ח\"א קנ, ד. וש\"נ."],["5986","47","<b>הרשימו. . שרש הכלים</b>: ראה מאמרי אדה\"ז על ענינים ע' שיז. תקס\"ז ע' רמה. תו\"ח ויגש רל, ד ובהערה 41. שעה\"י קל, א. סה\"מ תרס\"ד ע' קלט."],["5987","48","<b>שהם</b>: ג: שרשו."],["5988","49","<b>פ'</b>: כא."]]],[4801940362,"<b>והנה</b> עם כל הנ\"ל יובן שרש המל' הנק' שלומי אמוני ישראל<sup data-n=\"5989\">50</sup> שהוא בחי' המל' שבכל ספי' שפועל התגלות הספי' שיוכל למשך ממנה ספי' שתחתיו שזהו התכללות דשני הפכים כמו למשל בחי' החכמה הוא בחי' אין ואיך יוכל למצוא ממנה בחי' בינה שהוא בחי' יש<sup data-n=\"5990\">51</sup> וכן איך לימשך<sup data-n=\"5991\">52</sup> מבחי' חסד בחי' גבורה זהו הכל ע\"י המל' שבספי' העליונה, והיינו משום דשורש המל' הוא בבחי' פנימי' הקו אשר שרשו הוא בבחי' פנימי' ועצמי' אא\"ס הנק' יחיד שלמעלה מבחי' מאור ואור הכלולים בו ולכן יוכל להיות ע\"י המל' התכללות דשני הפכים כמו בחו\"ב אין ויש ובחו\"ג חושך ואור כו' וד\"ל. אך גם בבחי' העצמי' הנק' לבד שלמעלה מבחי' מאור ואור העצמי כנ\"ל יש ג\"כ ב' בחי' הא' מה שמאיר בבחי' הקו שזהו<sup data-n=\"5992\">53</sup> בחי' פנימי' אבל יש בחי' מקיף מה שלא נתפס בבחי' הקו כלל ונק' ממלא וסובב בעצמותו ממש הנק' לבד. והנה בחי' המקיף הנק' סובב הוא המאיר בסופא דכל דרגין דייקא שהוא בחי' המל' כמו שנבנית מעשיראה דכולהו<sup data-n=\"5993\">54</sup> להוות מאין ליש בבי\"ע שזהו דווקא בסיום הקו כי לא יוכל בבחי' הקו להתקבל הארתו כו', וזהו תכלית המכוון מה שעלה ברצונו א\"א שזהו מלך על עם דווקא בפ\"מ כי בזה הוא בחי' הכח דלבדו ממש מה שלא נתפס אפי' בבחי' הקו\"ח וזהו תכלית הכוונה להיות לו דירה בתחתונים כו'. ולכן נק' המל' כסופא דילי'<sup data-n=\"5994\">55</sup> כמאמר נתאווה<sup data-n=\"5995\">56</sup> כו' כי התאוה הוא למעלה מן הטעם לגמרי שזהו למעלה אפי' משרש החכמה שבעצמו' כו'.\n<b>אך</b> הנה ידוע דגלו לאדום שכינה עמהם<sup data-n=\"5996\">57</sup> פי' כי אע\"פ שהשכינה בגלות שנוטלים היש דקדושה לעצמם להגביה עצמם כנשר מ\"מ שכינה עמהם עם נש\"י. ולהבין מהיכן יש להם כח הזה להגביה א\"ע כנשר<sup data-n=\"5997\">58</sup> היינו מצד אורות דתוהו שלא יכול הכלי לסבול האור מזה נתהווה מציאת הרע אך מה שניתוסף בהם כח הוא ג\"כ מעין ודוגמא זאת כי קוב\"ה בגלותא סליק לעילא לעילא<sup data-n=\"5998\">59</sup> פי' להיות שבזמן הבית",[["5989","50","<b>המל' הנק' שלומי אמוני ישראל</b>: שמו\"ב כ, יט. ראה זהר חוקת קפ, ב. ביאוה\"ז בחוקותי קמב, ג [ולהצ\"צ שם כרך א ע' תמא]. מאמרי אדה\"ז תקס\"ה ח\"א ע' תקיב. ח\"ב ע' תרד. אוה\"ת שמו\"ב כרך א ע' מה ואילך."],["5990","51","<b>החכמה. . אין. . בינה. . יש</b>: ראה הנסמן בביאוה\"ז להצ\"צ כרך ב ע' תתרא. מאמרי אדה\"א בראשית ע' ב. דרושי חתונה ח\"ב ע' תעג. סה\"מ תרכ\"ט ע' רעח."],["5991","52","<b>לימשך</b>: ג: יוכל למצוא."],["5992","53","<b>שזהו</b>: ניתוסף ע\"פ ג."],["5993","54","<b>מעשיראה דכולהו</b>: ראה זהר פינחס רנג, רע\"ב. ראה גם לעיל ע' פג. שעה\"י פמ\"ז. וראה גם לקוטי ביאורים — קה\"ת — לשם."],["5994","55","<b>כסופא דילי'</b>: לשון הזהר בחוקותי כאן קיד, א. ב."],["5995","56","<b>נתאווה</b>: ראה תניא רפל\"ו (ובהנסמן בליקוט פירושים לשם). ביאוה\"ז תזריע עב, ג. מאמרי אדה\"א הנחות תקע\"ז ע' שכט. שערי אורה צז, ב. לעיל ע' תנז. סה\"מ תרל\"ח ע' לט הערה 138."],["5996","57","<b>דגלו לאדום שכינה עמהם</b>: ספרי מסעי לה, לד. ראה הנסמן במאמרי אדה\"א דברים ח\"ב ע' תלה. תו\"ח שמות ח\"א א, ד. וש\"נ."],["5997","58","<b>מ\"מ שכינה. . כנשר</b>: ג: כו'."],["5998","59","<b>קוב\"ה בגלותא סליק לעילא לעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ג. וש\"נ. תו\"ח שמות ח\"א לט, סע\"א ואילך ובהערה 72."]]],[4801940408,"הי' בחי' אא\"ס הנק' קוב\"ה שזהו בחי' לבדו ממש שלמעלה מבחי' מאור ואור מאיר בב' בחי' דבחי' ממלא וסובב כנ\"ל שהוא מה שנתפס בבחי' הקו ומה שמאיר במל' סופא דכל דרגין בסיום הקו כנ\"ל באריכות, אך בזה\"ג נסתלק בעצמותו שזהו בחי' רם על כל גוים<sup data-n=\"5999\">61</sup> שמקבלים מבחי' רוממות עצמותו ממה שנסתלק בעצמותו<sup data-n=\"6000\">60</sup> שאז אינו תופס מקום כלל ענין ביטול היש דנשמות ומלאכי' שעי\"ז נתפשט מדת המלוכה שכ\"ז תופס מקום מצד שעלה ברצונו כך שנתאוה כו' וכנ\"ל בענין כסופא דילי' כו', אבל כשמתרומם בעצמותו אינו תופס מקום ואז מקבלים הגוים כמו שהם בבחי' נפרד תוס' כח להגביה עצמם כנשר כנ\"ל, אך בשעתא דסליק רעותא<sup data-n=\"6001\">62</sup> שהו\"ע ההשפלה לזכור על שכינת עוזו שזהו בשבת ויו\"ט מצד תשלום הבירורים נעשה עת רצון למעלה [פי' עת רצון שזוכר ומשפיל א\"ע בבחי' הרצון מה שבתחילה נסתלק ממנו בזה\"ז כו'<sup data-n=\"6002\">63</sup> ], אז סליק אגרין שהו\"ע ההתעוררות שגורם ההמשכה מבחי' מקיפים דתוהו ששרש זה הגילוי הוא מבחי' לבדו ממש שלמעלה מסובב וממלא המאיר מצד עצמותו הנק' לבד כי ממקום שעלה לשם ונסתלק משם גופא מאיר ההארה שזהו יותר נעלה בשבתות שבזה\"ג מזמה\"ב, ונחית דרגין הוא בחי' הכלים דבי\"ע שזהו תכלית הכוונה להיות מאיר בבי\"ע דייקא, אך בבי\"ע גופא סליק כותלי'<sup data-n=\"6003\">64</sup> מאיר<sup data-n=\"6004\">65</sup> בחי' עולם הבריאה ויצי' ועשי' בטילים ונכללין כביטול מנה במאתיים וטעם הדברים להיות כי שבת הוא המקור ושרש להיות מתברכין מיני'<sup data-n=\"6005\">66</sup> כל שיתא יומין ויו\"ט הוא הממוצע בין שבת לתפילות דימות החול כמו ששמעתי מאדמו\"ר שליט\"א<sup data-n=\"6006\">67</sup> בתו' דצו את בנ\"י<sup data-n=\"6007\">68</sup>. והנה ידוע דבי\"ע הוא כמו שרש ועיקר וענף לכן בשבת ויו\"ט מאיר עולם הברי' שרש ההשפעה ומזה ממילא נעשה תוס' ההשפעה בימי החול שהוא בחי' עיקר וענף כו' וזהו ע\"ד והחיות רו\"ש<sup data-n=\"6008\">69</sup> שהרצוא שרש ומקור השוב כו' וד\"ל.",[["5999","61","<b>רם על כל גוים</b>: תהלים קיג, ד. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רל ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ס\"ע א'לג ואילך. וש\"נ."],["6000","60","<b>שזהו בחי'. . בעצמותו</b>: ג: ליתא. וכנראה נשמט מפני תיבות הדומות: בעצמותו. . בעצמותו."],["6001","62","<b>בשעתא דסליק רעותא </b>: לשון הזהר בחוקותי כאן קיד, ב."],["6002","63","<b>בזה\"ז כו'</b>: ג: בזה\"ג כנ\"ל."],["6003","64","<b>סליק אגרין. . ונחית דרגין. . סליק כותלי'</b>: זהר בחוקותי כאן."],["6004","65","<b>מאיר</b>: כ\"ה בהכת\"י."],["6005","66","<b>שבת. . מתברכין מיני'</b>: זהר בשלח סג, ב. יתרו פח, א. ראה מאמרי אדה\"ז על מארז\"ל ע' רסא ואילך."],["6006","67","<b>מאדמו\"ר שליט\"א</b>: כ\"ק אדמו\"ר הצ\"צ."],["6007","68","<b>בתו' דצו את בנ\"י</b>: ראה גם לקו\"ת פינחס עו, ב."],["6008","69","<b>והחיות רצו\"ש</b>: יחזקאל א, יד."]]],[4801940140,"<b>רפאיני</b> ה' וארפא<sup data-n=\"6009\">1</sup> הושיעני ואושעה כי תהילתי אתה<sup data-n=\"6010\">2</sup> כו'<sup data-n=\"6011\">3</sup>. להבין ענין הכפל לשון שכפל לאמר וארפא כיון שה' ירפא אותו בודאי י ר‘פא כו'. וכן מש\"א<sup data-n=\"6012\">4</sup> ואושעה הוא כפל לשון כיון שה' יושיע לו בוודאי יו‘ש ע כו'. הנה מתחילה יש להבין ענין התפילה מהו, כי הנביא מדבר בעד כנס\"י אשר היא חולת אה'<sup data-n=\"6013\">5</sup> בגלותא ומבקש הנביא בעד כללות נש\"י שישלח להם ה' רפואה למחלתם האנושה גם בהיותם בגלות כמאמר ואף גם זאת<sup data-n=\"6014\">6</sup> בהיותם בארץ אויביהם לא מאסתים ולא געלתים לכלותם כו'. ולהבין ענין החולי דחולת אהבה מהו, הנה מפרש ענינה מתחילה במה שאמר אותי עזבו מקור מים חיים<sup data-n=\"6015\">7</sup>, כי הנה הקב\"ה נק' מקור מ\"ח כמו למטה בגשמי' מקור הנובע מים חיים בתמידות כו', ומתחילה י\"ל ענין המשל דמקור מ\"ח למטה בגשמי', כי הנה כתיב ונהר יוצא מעדן להשקות את הגן שמתחילה יוצא הנהר מעדן ומשקה את הגן ומהשקאת הגן נמשך ד' נהרות וכמאמר ומשם יפרד<sup data-n=\"6016\">8</sup> כו' ומהם נמשכים כל הנחלים והולכים אל הים<sup data-n=\"6017\">9</sup>, אך קודם שנמשכו המה ראוים לשתי' ובים נעשים מים מלוחים שאינם ראוים לשתי', אך במקום שהם הולכים הם שבים ללכת<sup data-n=\"6018\">10</sup> והיינו שנמשכים מן הים דרך כדור הארץ ועולים דרך גידי הארץ דארעא חלחולי מחלחלי<sup data-n=\"6019\">11</sup> ואז מתבררים ע\"י עפר הארץ ונעשים ראוים לשתי' כמקודם קודם שנמשכים בים ולא עוד אלא שנק' מים חיים, וזהו\"ע שארז\"ל שכל הנהרות המה מסולמא דפרת<sup data-n=\"6020\">12</sup> שהוא מה שנהר פרס הוא מקלח תחת הקרקע והמים שבו הולכים דרך גידי הארץ מלמטה למעלה כמו ע\"י סולם<sup data-n=\"6021\">13</sup> ונובעים בכל הנהרות כו' [ולכן אנו רואים בהם גילוי הנביעה כ\"א ממעיין שלו אעפ\"י שבאמת נמשכים מד' נהרות היוצאים מן הנהר שיוצא מעדן כו' וד\"ל].\n<b>והנמשל</b> יובן למעלה בכללות ההשתלשלות דהנה כתיב אתה הוי' לבדך<sup data-n=\"6022\">14</sup> אתה עשית את השמים ושמי השמים וכל צבאם הארץ וכל אשר עלי' הימים וכל אשר בהם כו', והזכיר כאן מתחילה בחי' אתה הוי' לבדיך שזהו בחי' יחו\"ע שהוא כמו שהכל בטל במציאות אצלו כביטול זיו השמש בשמש וכמאמר כולא קמי'",[["6009","1","<b>רפאיני ה' וארפא</b>: כנראה הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלמאמר זה ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' רטו. אוה\"ת בחוקותי כרך ב ע' תרצ [ועם הוספות במהדורת תשנ\"ג ובהנסמן במ\"מ לשם — נדפסו גם באוה\"ת ירמי' כרך א ע' שנה ואילך]. סה\"מ תרל\"ה ח\"ב ע' רצט [ובהנסמן במ\"מ לשם]. המאמר שנדפס לאח\"ז."],["6010","2","<b>רפאיני ה'. . כי תהילתי אתה</b>: ירמי' יז, יד."],["6011","3","<b>כו'</b>: כ\"ה בהכת\"י."],["6012","4","<b>הכפל לשון. . וכן מש\"א</b>: ראה אוה\"ת בחוקותי כאן ע' תרצ: וקושי' זו הקשה ג\"כ בזהר ח\"ג בהשמטות סי' יו\"ד דף ש\"ה ע\"א [בדפוס קאפוסט תקס\"ט, ולפנינו דש, סע\"ב]. נעתק באוה\"ת ירמי' כרך א' ע' שס."],["6013","5","<b>כנס\"י. . חולת אה'</b>: שה\"ש ב, ה."],["6014","6","<b>ואף גם זאת</b>: בחוקותי כו, מד."],["6015","7","<b>אותי עזבו מקור מים חיים</b>: ירמי' יז, יג [בהוספת תיבת: ”אותי\" (ירמי' ב, יג) — ראה לקמן פיסקא וע\"ז אמר. מאמרי אדה\"ז תקס\"ח ח\"א ע' רטו. תרל\"ה ח\"ב ע' רצט]."],["6016","8","<b>ונהר יוצא מעדן. . ומשם יפרד</b>: בראשית ב, י."],["6017","9","<b>כל הנחלים והולכים אל הים</b>: קהלת א, ז."],["6018","10","<b>הם שבים ללכת</b>: קהלת שם."],["6019","11","<b>דארעא חלחולי מחלחלי</b>: חגיגה כב, א."],["6020","12","<b>מסולמא דפרת</b>: בכורות נה, ב."],["6021","13","<b>מקלח. . ע\"י סולם</b>: ראה רש\"י שם."],["6022","14","<b>אתה הוי' לבדך</b>: נחמי' ט, ו [בדילוג. שמי — ראה גם במאמר שלאח\"ז על יד הערה 23]."]]],[4801940204,"כלא חשיב<sup data-n=\"6023\">15</sup>, ולכן נאמר אני הוי' לא שניתי<sup data-n=\"6024\">16</sup> שאין שום שינוי כלל בעצמות שם הוי' שכמו שקודם שנברא העולם הי' הוא לבדו ואין שני לו כן עתה הוא ג\"כ כן להיות שכל העולמות בטל במציאות לפניו ית' ולכן נאמר כאן אתה בה\"א שהוא בחי' דכר שהוא בחי' יחו\"ע כו', אך אח\"כ א' אתה עשית כו' בלא ה' שהוא בחי' נוק' שזהו בחי' מלכותך מלכות כל עולמים<sup data-n=\"6025\">17</sup> שהוא בחי' מל' דאצי' שנעשה מקור לג' עולמות בי\"ע, ולכן הזכיר כאן ג' מדריגות שאתה עשית כו', הא' השמים ושמי השמים שהוא בחי' עולם הבריאה והימים וכל אשר בהם הוא עולם היצי' ועשי' והארץ הוא עולם העשי' הגשמי, וכ\"ז אתה עשית שהוא בחי' המל' דאצי' מקור כח הפועלם מאין ליש כו'.\n<b>והנה</b> ביאור ענין ג' מדריגות אלו שנבראים<sup data-n=\"6026\">18</sup>, הנה כתי' יהי רקיע<sup data-n=\"6027\">19</sup> בתוך המים ויהי מבדיל בין מים למים ומבשרי אחזה<sup data-n=\"6028\">20</sup> כמו למטה באדם חצר הכבד הוא מבדיל בין אברי הנשימה והשכל לאברי המזון, כמו הלב והמוח המה כלים לשכל ומדות והריאה והקנה ומוצאות הפה המה כלים לקול ודיבור שכ\"ז הוא המשכה רוחני' משא\"כ אברי המזון כמו הקרביים ובני מעיים המה כלים לחיות גשמי עד שיוכל להיות שורה בהם גם פסולת שהוא היפוך החיות, כן למעלה יש בחי' מים עליונים שממעל לרקיע המבדיל שהו\"ע שמים ושמי השמים כי מים מצמיחים כל מיני תענוג<sup data-n=\"6029\">21</sup> וכן הוא בחי' האור אלקי המאיר בעולם הבריאה [שנמשך מבחי' בינה דאצי' כמאמר אימא עילאה מקננא בכורסייא<sup data-n=\"6030\">22</sup> כו'] הוא מצמיח תענוג רוחני ועונג אלקי שמובדל מבחי' פסולת לגמרי והו\"ע תענוג הנשמות שנהנין מזיו השכינה<sup data-n=\"6031\">23</sup> שהוא תענוג לאין קץ אשר כל יסורי עוה\"ז כדאי לסבול ואפי' יסורי גיהינם שהם יסורי רוחני' כדאים לסבול בכדי לקבל אח\"כ תענוג שבגעה\"ע וכמאמר מוטב דלדייני'<sup data-n=\"6032\">24</sup> ולית' לעלמא דאתי, וכיון שהוא תענוג לאין קץ מוכרח לומר שהוא מובדל לגמרי מבחי' יש המתאר ומגביל כו', וכן אפי' המלאכים דבריאה הנק' שרפים<sup data-n=\"6033\">25</sup> ביטולם הוא לאור האלקי הקדוש ומובדל מהם ורק הארה בעלמא מאיר בהם להחיותם, ולהיות שהמה משיגים בהשגה גמורה איך שהוא קדוש ומובדל כו' לכן ביטולם הוא בתכלית בלי שום תערובות יש, וזהו שרפים עומדים ממעל לו<sup data-n=\"6034\">26</sup> וכדוגמת אדם המשיג איזה",[["6023","15","<b>כולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. לעיל ע' רמט ובהערה 74."],["6024","16","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["6025","17","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."],["6026","18","<b>שנבראים</b>: אוצ\"ל: שבנבראים."],["6027","19","<b>יהי רקיע</b>: בראשית א, ו. ראה גם לעיל ע' קז ואילך. סה\"מ תרכ\"ז ע' שמג. וש\"נ."],["6028","20","<b>ומבשרי אחזה</b>: איוב יט, כו."],["6029","21","<b>מים מצמיחים כל מיני תענוג</b>: ראה תניא פ\"א."],["6030","22","<b>אימא עילאה מקננא בכורסייא</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["6031","23","<b>שנהנין מזיו השכינה</b>: ראה ברכות יז, א."],["6032","24","<b>מוטב דלדייני'</b>: חגיגה טו, ב. ראה גם לעיל ע' קט ובהערה 48. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תערב ובהנסמן במ\"מ לשם. תקס\"ז ע' שכ. מאמרי אדה\"א שמות ח\"ב ע' שטז. דברים ח\"א ע' נט."],["6033","25","<b>המלאכים דבריאה הנק' שרפים</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. ביאוה\"ז בשלח לט, ד. מאמרי אדה\"א דברים ח\"א ע' רסג. וש\"נ. שע\"ת סב, א הערה 10."],["6034","26","<b>שרפים עומדים ממעל לו</b>: ישעי' ו, ב. ראה גם לעיל ע' רכה ואילך."]]],[4801940261,"שכל שאז שכלו מקיף להשכל וא\"כ שכלו הוא למעלה מן השכל משא\"כ כשאינו משיג בדרך או\"פ אין שכלו מקיף כלל להשכל [ואדרבה שכלו מוקף מהשכל כו'].\n<b>והנה</b> כללות השפע המאיר בעולם הבריאה לנשמות שבו ולמלאכים שבו הנק' שרפים כ\"ז נק' מים עליונים שמעל לרקיע המבדיל, אך בחי' מים תחתונים הוא ההשפעה הנמשך דרך רקיע המבדיל שהוא בחי' השפעה הנמשכת בעולם היצי' ועשי' לבחי' המלאכים הנק' אופנים וחיות<sup data-n=\"6035\">27</sup> שאינם משיגים בחי' קדושתו של הקב\"ה בגילוי גמור לכן שואלים אי' מקום כבודו<sup data-n=\"6036\">28</sup> ולכן אומרים ברוך<sup data-n=\"6037\">29</sup> שצריך להיות נמשך אור האלקי בהעלם ולא בגילוי עד שיוכל להתקבל בהם איזה הארה בעלמא ולכן מורגש בהם אור האלקי כמאמר והאופנים וחיות הקודש ברעש גדול<sup data-n=\"6038\">30</sup> כו' ויש בהם בחי' תערובת יש וזהו בחי' מים תחתונים, וכדוגמת מי הים שהם מלוחים ואינם ראוים לשתי' כו', אך אח\"כ נמשך השפעה זאת למטה בעולם העשי' הגשמי וכאן בעולם הגשמי נתברר השפע ונעשה היפוך מיש לאין ע\"י נש\"י המלובשים בגופים ועוסקין בתורה ועושין מצות שעי\"ז מתברר היש דנוגה דעולם העשי' הגשמי ונכלל בקדושה האלוקי' בבחי' ביטול וזהו כדוגמת מים הנמשכים דרך עובי כדור הארץ הגשמי שנעשו מים ראוים לשתי' כך ע\"י הבירור דתומ\"צ נעשה מיש דנוגה בחי' אין אלקי להחיות הנה\"א בתוס' אור וחיות כו'.\n<b>וזהו</b> בחי' ג' מדריגות שהזכיר, השמים ושמי השמים הוא בחי' עולם הבריאה שהוא בחי' געה\"ע תענוג הנשמות וכל צבאם הם המלאכים הנק' שרפים שכולם הם במדריגות בריאה מאין ליש, ואח\"כ אמר הימים וכל אשר בהם שזהו בחי' עולם היצי' ועשי' הרוחני' עם המלאכים הנק' חיות ואופנים שע\"ז אמר וכל אשר בהם, והארץ וכל אשר עלי' אעפ\"י שהזכיר מקודם מ\"מ הוא אחרון בהשתלשלות כמאמר יקוו המים ואח\"כ ותראה היבשה<sup data-n=\"6039\">31</sup> שזהו בחי' עולם העשי' הגשמי' שבו מתלבשים הנשמות בגופים ומתבררים בירורים ע\"י תומ\"צ שאז נתברר ההשפעה וחיות שבו כדוגמת עולם הבריאה ולכן נק' בשם מים חיים ראוים לשתי' ולהחית הנפש כו', וזהו וצדקה כנחל איתן<sup data-n=\"6040\">32</sup> כי אותיות איתן משמשות לעתיד<sup data-n=\"6041\">33</sup> ונחל איתן הוא השפע אלקי' שבעולם הבריאה שהוא בחי' ההעלם שעתיד לבא לידי גילוי [כי ידוע דאימא עילאה מקננא בכורסייא שבה בחי' שם אהי'<sup data-n=\"6042\">34</sup> כו'] וצדקה הוא בחי' המתבררת בעולם העשי' ע\"י תומ\"צ הוא כמו נחל איתן שבעולם הבריאה ששם הוא החיות בלי תערובת יש כו', אך באמת לשון איתן הוא תוקף וחיזוק<sup data-n=\"6043\">35</sup> והיינו כי באמת",[["6035","27","<b>היצי' ועשי'. . אופנים וחיות</b>: ראה לעיל ע' רכד ובהערה 42."],["6036","28","<b>אי' מקום כבודו</b>: נוסח קדושת כתר."],["6037","29","<b>אומרים ברוך</b>: יחזקאל ג, יב. ברכת יוצר. ראה חולין צב, רע\"א ובתוד\"ה ברוך."],["6038","30","<b>והאופנים. . ברעש גדול</b>: ברכת יוצר. ראה גם סה\"מ תרל\"ד ע' רנד."],["6039","31","<b>יקוו המים. . ותראה היבשה</b>: בראשית א, ט [בדילוג]."],["6040","32","<b>וצדקה כנחל איתן</b>: עמוס ה, כד."],["6041","33","<b>אותיות איתן משמשות לעתיד</b>: ראה גם קו\"א לתניא קסא, א. לקו\"ת ר\"פ ראה."],["6042","34","<b>דאימא עילאה. . שם אהי'</b>: ראה ת\"ז תס\"ט קיד, א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תתמב."],["6043","35","<b>איתן הוא תוקף וחיזוק</b>: ראה בלק כד, כא."]]],[4801940314,"השפעה המתבררת בעולם העשי' ע\"י תומ\"צ עולה למעלה מבחי' עולם הבריאה ומרוממות הנשמות למעלה ממקור חוצבה שבעולם הבריאה<sup data-n=\"6044\">36</sup> רק<sup data-n=\"6045\">37</sup> לבחי' בינה שבעולם האצי' עצמו וכמאמר וצדקה תרומם גוי<sup data-n=\"6046\">38</sup> כו' ולכן נק' השפע אלקי' שבעולם העשי' בשם מים חיים<sup data-n=\"6047\">39</sup> להיות שמאיר בזה בחי' חיים העליונים שבעולם האצי' שהוא למעלה מבחי' בריאה כו' והוא בחי' הנהר עצמו כמ\"ש במקורו שלמעלה מהיות משקה לג\"ן ואפי' לג\"ן סדרים דאורייתא<sup data-n=\"6048\">40</sup> [כי הג\"ן הוא בחי' המל'<sup data-n=\"6049\">41</sup> דאצי' וג\"ן סדרים דאורייתא הוא בבחי' הז\"א דאצי', אך הנהר הוא בבחי' בינה<sup data-n=\"6050\">42</sup> שלמעלה מז\"א כו'], וזהו והיתה נפש אדוני צרורה<sup data-n=\"6051\">43</sup> בצרור החיים את ה' כי ע\"י המצות נעשי' לבושים וכצרור אבן במרגמה<sup data-n=\"6052\">44</sup> נזרק למרחוק כך ע\"י שנצררה הנשמה בלבושי המצות עולה ע\"ד הנהר היוצא מעדן שנק' מקור מים חיים כמ\"ש בבחי' אצי' והוא בבחי' ירידה מגעה\"ע לצורך עלי' בנהר שלמעלה מהג\"ן אפי' ג\"ן סדרים דאורייתא כנ\"ל, וזהו וצדקה כנחל איתן<sup data-n=\"6053\">*45</sup> שהוא בבחי' הבינה דאצי' הנק' נחל איתן* [ע\"ש התוקף וחיזוק כו' וגם כנ\"ל שמשמשות לעתיד ובחי' בינה הוא לע\"ל למעלה מעוה\"ב כו'] ועי\"ז נמשך השמחה ממהו\"ע בנשמה כידוע דשרש שמחה הוא בבינה<sup data-n=\"6054\">45</sup> כמ\"ש אם הבנים שמחה<sup data-n=\"6055\">46</sup> כו' כמשי\"ת.\n<b>והנה</b> בחי' זאת נק' מקור מים חיים שהוא בחי' מקור כל התענוגים כי מים מצמיחים כל מיני ומקור<sup data-n=\"6056\">47</sup> מים הוא מקור כל התענוגים כו' ובחי' זאת נמשך בשמחה של מצוה שהוא בחי' השמחה ממהו\"ע ית' שלמעלה מכל התענוגים של ג\"ע העליון וג\"ע התחתון כמאמר ישמחו בך<sup data-n=\"6057\">48</sup> כו', וזהו תחת אשר כו' בשמחה ובטוב לבב<sup data-n=\"6058\">49</sup> כו' שזהו יותר טוב מרוב כל שהוא בחי' ריבוי התענוגים<sup data-n=\"6059\">50</sup> שבגעה\"ע והתחתון כו', ובחי' זאת נק' מקור מים חיים [ובחי' זאת האירה בזמן הבית שכאו\"א מישראל הי' שמח ומתענג בעבודת המצות בבחי' השמחה ממהו\"ע ולא בבחי' המשכות המצות רק מצד עצם המצוה<sup data-n=\"6060\">51</sup> כו' וד\"ל]. וזהו\"ע ג\"כ ברכות המצות, כי ברוך אתה",[["6044","36","<b>הנשמות. . שבעולם הבריאה</b>: ראה גם לעיל מאמר ד\"ה והתהלכתי תרט\"ו ובהערה 32."],["6045","37","<b>רק</b>: כ\"ה בהכת\"י."],["6046","38","<b>וצדקה תרומם גוי</b>: משלי יד, לד [ושם צדקה — ראה גם לעיל ע' שנג ובהערה 88]."],["6047","39","<b>חיים</b>: כ\"ה בהכת\"י."],["6048","40","<b>לג\"ן סדרים דאורייתא</b>: ראה זהר מדהנ\"ע וירא קד, ב. מאמרי אדה\"א דברים ח\"ד ע' א'רג. וש\"נ. ראה גם לעיל ע' צא ובהערה 101."],["6049","41","<b>הג\"ן. . המל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ג מערכת גן. לעיל ע' קז ובהערה 30."],["6050","42","<b>הנהר. . בינה</b>: זהר (אדרא דמשכנא) משפטים קכג, ב."],["6051","43","<b>והיתה נפש אדוני צרורה</b>: שמו\"א כה, כט. ראה סה\"מ תרל\"ה כאן ע' דש הערה 66."],["6052","44","<b>וכצרור אבן במרגמה</b>: משלי כו, ח."],["6053","*45","<b>הבינה. . נחל איתן</b>: ראה גם המאמר שלאח\"ז על יד הערה 46."],["6054","45","<b>שמחה הוא בבינה</b>: ראה מאמרי אדה\"א נ\"ך ע' מח. וש\"נ. תו\"ח וארא פה, ג. לעיל ע' יט ובהערה 34."],["6055","46","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["6056","47","<b>מיני ומקור</b>: אוצ\"ל: מיני תענוג ומקור."],["6057","48","<b>ישמחו בך</b>: ע\"פ נוסח תפלת העמידה ליו\"ט."],["6058","49","<b>תחת. . ובטוב לבב</b>: תבוא כח, מז."],["6059","50","<b>מרוב כל. . ריבוי התענוגים</b>: ראה גם לעיל מאמר ד\"ה וזכרתי הר\"ת על יד הערה 82."],["6060","51","<b>השמחה. . מצד עצם המצוה</b>: ראה גם לעיל ע' תכ ובהערה 18."]]],[4801940363,"הוי' הוא המשכה מבחי' אתה הוי' לבדיך שהוא בחי' מהו\"ע אא\"ס [והוא ג\"כ אלקינו מקור נש\"י כידוע דישראל עלה במח'<sup data-n=\"6061\">52</sup> פנימי' ועצמי' למעלה ממחה\"ק מקור ההשתלשלות כו' וד\"ל] ומשם נמשך להיות מלך העולם שהוא בחי' מלכותך מלכות כל עולמים<sup data-n=\"6062\">53</sup> שזהו בחי' מקור העולמות כידוע דמה שיוכל להיות נמשך מציאות עולם נראה בבחי' יש הוא מצד כח המלוכה להיות שמדת המלוכה אינה מגלית השפעה מריחוק מקום<sup data-n=\"6063\">54</sup> מן העצם דייקא כו', ומשם אשר קדשנו בקידוש<sup data-n=\"6064\">55</sup> העליון שלמעלה מג\"פ קדוש כו' ג\"פ קדוש הוא ג' מדריגות דשמי השמים כו' הימים כו' הארץ שהם ג' עולמות דבי\"ע<sup data-n=\"6065\">56</sup> [ובשרש שרשן ג' מיני אדם<sup data-n=\"6066\">57</sup> כו'] אבל קדוש<sup data-n=\"6067\">58</sup> הוא בחי' עצמי' אלקות שבאצי' [ולמעלה בחי' פנימי' אא\"ס שלפני הצמצום], שע\"י המצות נתקדשו בנ\"י בקדש שלמעלה מקדוש<sup data-n=\"6068\">59</sup> בו', וזהו אשר מלשון באשרי<sup data-n=\"6069\">60</sup> כי אשרוני שהוא בחי' העונג ממהו\"ע שנמשך בעסק המצוה שנק' שמחה של מצוה כו'. וזהו עץ חיים היא<sup data-n=\"6070\">61</sup> למחזיקים בה שהוא בחי' התורה שנק' עץ החיים, ותומכי' הם המצות מאושר ממשיכים מבחי' תענוג העליון הפשוט שנק' אושר מל' כי באשרי כנ\"ל וד\"ל.\n<b>וע\"ז</b> אמר אותי עזבו מקור מים חיים, כי בזמן הגלות אבדו החוש לטעום טעם אלקי שיש בעצמות אלקות, כמאמר טעמו וראו<sup data-n=\"6071\">62</sup> כי טוב ה', ועי\"ז ממילא טועמים טעם ועונג בהרגשת עצמם דווקא, ולכן נק' כנס\"י חולת אהבה כמו החולה הטועם מר למתוק ומתוק למר כך בחי' כנס\"י בגלותא אינם טועמים טעם ועונג באהבה האלקי' [הנק' אהבה בתענוגים כו'] רק בחיצוניות ובקרירות כמאמר כי פנו אלי עורף<sup data-n=\"6072\">63</sup> כו', והטעם לזה כי מקור התענוגים המלובש במים המצמיחים ומכ\"ש בנהר עצמו מקור המים חיים אינו נרגש בגילוי אור כי הוא בבחי' ההעלם שלמעלה מבחי' גילוי אור. אך הסיבה להביאה לידי גילוי הוא בחי' הצימאון שהוא בחי' אש האלקי וכמ\"ש כמים קרים<sup data-n=\"6073\">64</sup> על נפש עיפה דייקא שאז נרגש בהם העונג, וידוע דאש אוכלה אש<sup data-n=\"6074\">65</sup> שכאשר מתגבר האש אלקי אזי מכלה האש זר שבתאוות ולגרמי', אבל",[["6061","52","<b>דישראל עלה במח'</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248. לעיל ע' תל."],["6062","53","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."],["6063","54","<b>אינה מגלית. . מקום</b>: כ\"ה בהכת\"י."],["6064","55","<b>בקידוש</b>: אוצ\"ל: בקודש."],["6065","56","<b>ג\"פ קדוש. . דבי\"ע</b>: ראה גם לעיל ע' שנ ובהערה 53."],["6066","57","<b>ג' מיני אדם</b>: ראה מאמרי אדה\"ז על ענינים בתחילתו ובהנסמן במ\"מ לשם. אוה\"ת על ענינים ע' עז. סה\"מ תש\"ח ע' 113 בהערה. הנסמן בסה\"מ תרל\"ב ח\"א ע' ד."],["6067","58","<b>קדוש</b>: אוצ\"ל: קדש."],["6068","59","<b>בקדש שלמעלה מקדוש</b>: ראה גם לעיל ע' תח ובהערה 57."],["6069","60","<b>אשר מלשון באשרי</b>: ויצא ל, יג. ראה ת\"ז ת\"ל (עד, ב). תל\"ט (עט, א). לקו\"ת בשלח א, ד. תו\"ח יתרו ח\"ב רסז, ג. וש\"נ."],["6070","61","<b>עץ חיים היא</b>: משלי ג, יח."],["6071","62","<b>טעמו וראו</b>: תהלים לד, ט."],["6072","63","<b>כי פנו אלי עורף</b>: ירמי' ב, כז."],["6073","64","<b>כמים קרים</b>: משלי כה, כה [ושם: מים — ראה מאמרי אדה\"א בראשית ע' תקסה. וש\"נ]."],["6074","65","<b>דאש אוכלה אש</b>: יומא כא, ב. ראה גם סה\"מ תרל\"ח ע' חצר."]]],[4801940409,"בזה\"ג מצד שפנו אלי עורף שבבחי'<sup data-n=\"6075\">*66</sup>* אלקות הוא בחיצוני' מורה שנתגבר האש זר שבתאוות ותענוגי עוה\"ז מאד ולכן הוא מכלה לאש האלקי ולכן כל עסקו באלקות הוא בחיצוניות ובקרירות מצות אנשים מלומדה<sup data-n=\"6076\">66</sup>, וכיון שכן לא יוכל להרגיש בחי' שמחה של מצוה שהוא בחי' התענוג ממהו\"ע שהוא מקור התענוגים שאינו נרגש אלא מצד תוקף הצימאון כנ\"ל, וזהו\"ע חולת אהבה דאהבה בתענוגים שאינו מרגיש התענוג ממהו\"ע כו'. והעצה היעוצה לזה הוא בחי' ההתבוננות מיני' ובי' מצד הריחוק דייקא, והיינו כאשר יתבונן איך שבחי' מהו\"ע אלקות הוא מקור כל התענוגים, עד שאפי' תענוג העליון שבגעה\"ע הוא בחי' הארה וזיו בלבד, והוא רחוק מזה ואינו טועם טעם כלל בבחי' המשכות אלקות שע\"י המצות ואין לו שום שמחה מצד המצוה רק העסק הוא בקרירות מצות אנשים מלומדה, אזי מצד התבוננות זאת יתמרמר מאד לבו בקרבו וממילא יוטהר כל מיני אש זר שנתערב בקרב ולב עמוק וממילא תגדל הצימאון לאלקים חיים עד שמחמת זה ירגיש התענוג לאלקות מצד מהו\"ע ממש כו'.\n<b>אך</b> באמת מה שמתבונן בעצמו על הריחוק ומתפעל בבחי' מרירות מזה, אינו מעביר האש זר לגמרי מקרב ולב עמוק, רק עיקר העברת האש זר הוא מלמעלה שזהו מבחי' סוכ\"ע דייקא דקמי' כחשיכא כאורה<sup data-n=\"6077\">67</sup> ולכן יוכל להפוך מחושך לאור, וכמאמר רוח עברה ותטהרם<sup data-n=\"6078\">68</sup> שזהו בחי' רוח ממרום דייקא זה יוכל להפוך מחושך לאור ולטהר כל מיני לכלוך, וראי' לזה מענין התשובה שהוא בעוה\"ז<sup data-n=\"6079\">69</sup> דייקא להיות שבעוה\"ז מאיר מבחי' סוכ\"ע ולזאת יוכל להשיב ולהעשות מרשע גמור גמור בחי' צדיק גמור משא\"כ בעוה\"ב שאינו מאיר רק מבחי' ממכ\"ע לזאת לא תוכל הנשמה להתהפך מצד עצמה, וזה אמר רפאיני ה' וארפא שהרפואה תהי' מלמעלה מבחי' סוכ\"ע שהוא בחי' שם הוי', ומ\"ש וארפא כפל לשון הנה ענין התשובה מביא רפואה<sup data-n=\"6080\">70</sup> כמאמר ארפא משובתם<sup data-n=\"6081\">71</sup>, ושב ורפא לו<sup data-n=\"6082\">72</sup>, וענין התשובה הוא בשעת התפילה שמזה נטהר הנפש מכל מיני רע כנ\"ל שהוא בחי' אש זר, אבל לעשות ולתקן בחי' הכלי בכדי שיתקיים בחי' חיות האלקי בקרבו זהו ע\"י רפואה דתורה כידוע דעל התורה כתיב רפאות תהי לשרך<sup data-n=\"6083\">73</sup> כו', מרפא לשון עץ חיים<sup data-n=\"6084\">74</sup>, והו\"ע תיקון הכלים כמו בגשמיות שאחר סממני הרפואה המסירים את קלקול הדמים הגורמים אש זר נותנים מזון טוב לתקן הכלים כו'.",[["6075","*66","<b>שבבחי'</b>: אוצ\"ל: שבחי'."],["6076","66","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם תניא פל\"ט (נג, ב). תו\"ח ויחי רמב, ג הערה 44. תצוה ח\"ב שלח, ג."],["6077","67","<b>כחשיכא כאורה</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. סידור סדר הגדה רצז, רע\"ד. עט\"ר דרוש לעשי\"ת ע' נא. סה\"מ תרכ\"ז ע' תצד."],["6078","68","<b>רוח עברה ותטהרם</b>: ע\"פ איוב לז, כא."],["6079","69","<b>התשובה שהוא בעוה\"ז</b>: ראה סידור שחרית לב, א. לד, ב. לקו\"ת פינחס עה, ב ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תתכג. וש\"נ. תו\"ח שמות ח\"א ז, א. וש\"נ. סה\"מ תרל\"ח ע' שכב. לעיל מאמר ד\"ה והתהלכתי תרכ\"ב על יד הערה 39."],["6080","70","<b>התשובה מביא רפואה</b>: יומא פו, א."],["6081","71","<b>ארפא משובתם</b>: הושע יד, ה."],["6082","72","<b>ושב ורפא לו</b>: ישעי' ו, י."],["6083","73","<b>רפאות תהי לשרך</b>: משלי ג, ח."],["6084","74","<b>מרפא לשון עץ חיים</b>: משלי טו, ד."]]],[4801940451,"<b>וענין</b> התיקון שע\"י התורה הוא ע\"ד מארז\"ל לעולם יהא אדם רך כקנה<sup data-n=\"6085\">75</sup> ואל יהא קשה כארז כידוע שיש ג' אמות אמ\"ש ושבע כפולות<sup data-n=\"6086\">76</sup> הבאים בדגש ורפה<sup data-n=\"6087\">*77</sup>*, וענין הדגש מורה חיזוק שזהו בחי' הגבורה דקו השמאל, ובד\"כ בכללות העולמות הוא בחי' עולם התוהו ששם הוא בחי' אורות תקיפים<sup data-n=\"6088\">77</sup> וחזקים ולכן מחמת שבירת הכלים נתהווה למטה ע' אומות<sup data-n=\"6089\">78</sup> שהם ג\"כ בבחי' תוקף וחיזוק לא לשבור ולהכנע בשום אופן בעולם וכמאמר כבד לב פרעה<sup data-n=\"6090\">79</sup>, משא\"כ בישראל אפי' פושעי ישראל מלאים חרטות<sup data-n=\"6091\">80</sup> כי שרשם הוא בחי' החסדים שבקו הימין שזהו בחי' רפא, ובכלל הוא בחי' עולם התיקון ששם הוא בחי' הביטול ביותר שלכן הם בבחי' התכללות<sup data-n=\"6092\">81</sup> זמ\"ז כידוע, וזהו יהא רך כקנה להפוך מדותיו הטבעים בבחי' הביטול דמדות דתיקון ואל יהא קשה כארז נה\"ט ששרשה מעולם התוהו ששם הוא בחי' תוקף האורות בבחי' קשה כארז כו'. וענין היפוך מדותיו הטבעים שיהיו בבחי' רך כקנה הוא ע\"י התורה דייקא, כי על התורה נאמר עוז ותושי'<sup data-n=\"6093\">82</sup> שהוא בחי' עז<sup data-n=\"6094\">83</sup> לנשמה האלקית ומתשת כח הרע דנה\"ט שהוא בחי' המדות טבעים שהם בבחי' תוקף קשה כארז נעשים ע\"י התורה בבחי' ביטול דרך כקנה כו' [והענין הוא דידוע דהתורה שרשה בג\"ר דחב\"ד שהוא בחי' שלש אמות אמ\"ש הנ\"ל, ונק' אמות להיותם מקור של שני המדות דחו\"ג כידוע דשכל א' יוכל להפוך מחסד לדין ומדין לחסד כמו כי יצר לב האדם<sup data-n=\"6095\">84</sup> כו', לזאת ע\"י חכמה דתורה אתברירו<sup data-n=\"6096\">85</sup> ונתהפך מחשוכא דנה\"ט לאור ועולה בשרשו וממשיך בחי' אורות דתוהו בכלים דתיקון שנמצא שמאיר מבחי' תוקף האור דעולם התוהו וזהו עז לנשמה מצד אורות דתוהו המאירים בה שנמשך בה בחי' קשה כארז דייקא בבחי' אלקו', אך מצד כלים דתיקון נעשה בחי' נה\"ט רך כקנה כו' וד\"ל].",[["6085","75","<b>לעולם יהא אדם רך כקנה</b>: תענית כ, סע\"א. ראה לקו\"ת אמור לז, ד. מטות פז, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשמז. וש\"נ. תו\"ח בראשית ט, א ובהערה 17. סה\"מ תר\"ל ע' ג. תרל\"ח ע' תלט."],["6086","76","<b>ג' אמות. . ושבע כפולות</b>: ס\"י פ\"א, מ\"ב."],["6087","*77","<b>בדגש ורפה</b>: ראה גם בענין דגש רפא אוה\"ת ירמי' כרך א ע' שנט ואילך."],["6088","77","<b>התוהו. . אורות תקיפים</b>: ראה ע\"ח שער המלכים שי\"א, פ\"א. תו\"ח בראשית ט, א ובהערה 6."],["6089","78","<b>ע' אומות</b>: סוכה נה, ב. במד\"ר פ\"ט, יד. ראה לקו\"ת ראה ל, ב. לא, ב."],["6090","79","<b>כבד לב פרעה</b>: וארא ז, יד."],["6091","80","<b>פושעי ישראל מלאים חרטות</b>: ראה אברבנאל שמו\"ב יג, טו (ושם הל' שבפנים — בשם: מאמר המדיני). ראשית חכמה שער היראה פ\"ג (ושם: וכן בספר חסידים אמרו — וכבר העירו שהתיבות: ”בספר חסידים\" ניתוסף ע\"י המו\"ל). סדר היום קהלת יא, ט (ושם: וכאמרם ז\"ל). מאמרי אדה\"א דברים ח\"ב ע' שסה. וש\"נ. תו\"ח משפטים ח\"ב רצג, ב. וש\"נ."],["6092","81","<b>עולם התיקון. . התכללות</b>: ראה תו\"א בשלח סה, ד. תו\"ח בראשית מא, א הערה 5. שמות ח\"א מד, ג ואילך."],["6093","82","<b>התורה. . עוז ותושי'</b>: ראה מכילתא דרשב\"י יתרו פי\"ט, טז. לקו\"ת ויקרא ו, ב. תו\"ח בשלח ח\"א קפד, א. וש\"נ."],["6094","83","<b>עז</b>: אוצ\"ל: עוז."],["6095","84","<b>כי יצר לב האדם</b>: נח ח, כא. ראה גם לעיל ע' שמב ובהערה 54."],["6096","85","<b>חכמה דתורה אתברירו</b>: ראה זהר היכלות פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. תו\"ח תשא ח\"ב שפד, ד ואילך."]]],[4801940488,"<b>וזהו</b> רפאיני הוי' שזהו בשעת התפלה שיוטהר כל מיני רע ועי\"ז יאיר מבחי' מקור מים חיים שהוא בחי' הנהר היוצא מעדן בתוס' אור כידוע דבע\"ת משכין לי' בחילא יתיר<sup data-n=\"6097\">86</sup>, ואח\"כ וארפא כל היום ע\"ד התורה לעשות בי<sup data-n=\"6098\">87</sup> כלים לאור זה שהוא בחי' הביטול דרך כקנה שהוא ע\"י התורה, ובחי' הביטול של הכלי הוא דייקא בחי' כלי לאור האלקי שיהי' מתקיים בו כידוע דאין אוא\"ס שורה אלא במי שבטל אליו כו' וד\"ל. ואח\"כ א' הושיעני ואושעה זה קאי על צדיקים גמורים שאינם חולים בחולת אהבה ומאיר בהם בחי' אהבה בתענוגים, ועליהם מבקש הנביא [כי הנביא מדבר בעד כלל ישראל מתחילה ביקש בעד אותם שעזבו מקור מים חיים שיתרפאו ממחלתם האנושה ואח\"כ ביקש בעד בחי' צדיקים גמורים שיזכו ג\"כ לבחי' תשובה כו' וד\"ל] הושיעני שזהו ענין לאתבא צדיקייא בתיובתא<sup data-n=\"6099\">88</sup>, כי הנה ענין הושיעני הוא מלשון וישע<sup data-n=\"6100\">89</sup> שהו\"ע בפנימי' המהות להאיר למטה ובקשת דוד שהוא בחי' כללות נש\"י פנו אלי<sup data-n=\"6101\">90</sup> כו'. והענין יובן בהקדים ענין התפילה שנק' צלותא בלשון הגמרא כי צלותא הוא מלשון הטי'<sup data-n=\"6102\">91</sup> כמאמר אצלי<sup data-n=\"6103\">92</sup> כו' שזהו בבחי' בעל הרצון<sup data-n=\"6104\">93</sup> שיהי' נמשך בבחי' רצון, כי באמת עצמות אא\"ס הוא מובדל אפי' מגדר רצון והרצון נמשך מאתו ית' ע\"י צמצומים כי רצון אותיות צינור<sup data-n=\"6105\">94</sup> שהוא המשכה בבחי' צמצום והמשכה זאת מן העצמות להיות רצון נק' בשם הפנה והטי' בלה\"ק [כי הטי' הוא מה שכופף א\"ע ממקום הגבוה להיות במקום נמוך יותר וד\"ל], וזהו\"ע התפלה שאומרים יה\"ר שהוא בחי' המשכת הרצון מלמעלה מן הרצון, וזהו\"ע הקב\"ה מנענע בראשו<sup data-n=\"6106\">95</sup> כי ראש הוא גולגלתא שהוא בחי' רצון<sup data-n=\"6107\">96</sup> ומוחין שהוא בחי' חכמה, והנענוע הוא מלמעלה מן הרצון שיהי' בחי' רצון וחכמה, ובחי' זאת נק' ש\"ע נהורין<sup data-n=\"6108\">97</sup> בל' הקבלה וזהו הושיעני שהו\"ע המשכת ש\"ע נהורין מלמעלה למטה ועי\"ז ואושעה מלמטה למעלה [כענין משכני אחריך נרוצה<sup data-n=\"6109\">98</sup> ] להיות נמשך בכל פנימי' ועצמות הנשמה אליך, וזהו\"ע והרוח תשוב אל האלקים<sup data-n=\"6110\">99</sup> אשר נתנה [וכמאמר כי תשוב אלי תשוב<sup data-n=\"6111\">100</sup> ] שגם צדיקים גמורים ישובו בתשובה בחילא יתיר כמו בעל תשובה כו' וד\"ל.",[["6097","86","<b>דבע\"ת משכין לי' בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. תו\"ח שמות ח\"א לז, א. וש\"נ. לעיל ע' קפח ואילך."],["6098","87","<b>ע\"ד. . בי</b>: אוצ\"ל: ע\"י. . בה."],["6099","88","<b>לאתבא צדיקייא בתיובתא</b>: ראה זהר רע\"מ בהעלותך קנג, ב. לעיל ע' תעג ובהערה 84."],["6100","89","<b>וישע</b>: בראשית ד, ד. ראה גם לעיל ע' קמו ובהערה 65."],["6101","90","<b>פנו אלי</b>: אוצ\"ל: פנה אלי — תהלים כה, טז. סט, יז. פו, טז. קיט, קלב."],["6102","91","<b>צלותא. . הטי'</b>: בסה\"מ תרכ\"ט ע' יב בשם טור ברקת. ראה לקו\"ת חוקת סז, א ואילך. האזינו עב, ג. אוה\"ת ואתחנן ע' שט."],["6103","92","<b>כמאמר אצלי</b>: ראה פלח הרמון תשא ע' שיד: אצלויי ודוך — ביצה יד, א. לקו\"ת חוקת שם."],["6104","93","<b>בעל הרצון</b>: ראה גם בענין בעל הרצון לעיל ע' סז ובהערה 10."],["6105","94","<b>רצון אותיות צינור</b>: ראה זהר הרקיע לזהר בראשית נא, א (כה, ב). מאמרי אדה\"א בראשית ע' לו. וש\"נ."],["6106","95","<b>הקב\"ה מנענע בראשו</b>: ברכות ג, סע\"א."],["6107","96","<b>גולגלתא. . רצון</b>: ראה לקו\"ת שלח מח, ב. ר\"ה נד, ב. תו\"ח בא ח\"א צ, א."],["6108","97","<b>ש\"ע נהורין</b>: ראה זהר אד\"ר נשא קכח, ב. ע\"ח שער א\"א שי\"ג, פי\"ד. אוה\"ת מטות ע' א'רעב. המשך תער\"ב ח\"ב ע' א'רה."],["6109","98","<b>משכני אחריך נרוצה</b>: שה\"ש א, ד."],["6110","99","<b>והרוח תשוב אל האלקים</b>: קהלת יב, ז."],["6111","100","<b>כי תשוב אלי תשוב</b>: ירמי' ד, א [ושם: אם. בדילוג]."]]],[4801940522,"<b>כי</b> תהלתי אתה הנה ענין תהלה הוא מלשון הילול ושבח שהוא בחי' גילוי ההעלם וכמשל שמשבחים אדם בחכמתו ומדותיו שעי\"ז מעוררים עצמי' שכלו ומדותיו לבא לידי גילוי<sup data-n=\"6112\">101</sup> ולהשפיע למקבל משא\"כ כשאינם משבחים אותו נשארים בהעלם הגם שישנם בו, כך למעלה כתיב לך ה' הגדולה<sup data-n=\"6113\">102</sup> שבחי' המדות דגדולה וגבורה כו' המה בטלים ונכללים בעצמו' ולכן אינם עולים בשם גדולה וגבורה כלל, אך כאשר נש\"י משבחים ומהללים אותו אזי מעוררים בחי' חו\"ב שבעצמי' שיבואו לידי גילוי ועי\"ז מתגלה ג\"כ בבחי' המדות מרכד\"ר [שהוא בחי' ת\"ת עד חסד שבמל' דאצי' כו'] עד סוכד\"ר עד שהמדות עולים בשם להקרות גדולה וגבורה בה\"א<sup data-n=\"6114\">103</sup> כו', וזהו כל הנשמה תהלל י\"ה<sup data-n=\"6115\">104</sup> שהו\"ע גילוי ההעלם דחו\"ב שבעצמי' שעי\"ז נעשה הגילוי בעלמין סתימין שהם ג\"כ בחי' גילוי לגבי העצם דסדכ\"ס<sup data-n=\"6116\">106</sup> ואח\"כ ע\"י ו\"ה נעשה הגילוי בעלמין דאתגליין<sup data-n=\"6117\">105</sup> עד בחי' המל', וזהו אימתי גדול<sup data-n=\"6118\">107</sup> כשהוא בעיר אלקינו כו', אך עיקר גילוי ההעלם הוא מצד שמרומם בחי' החכ' ומדות לבחי' העצמי' ממש שעי\"ז מחדש אותם מבחי' העצמי' דלאו מכל אינון מדות כלל<sup data-n=\"6119\">108</sup> ועי\"ז ממילא מתגלים מהעלמם ונמצא שמה שמתגלה בחכמתו ומדותיו הוא בחי' גילוי העצם ממש. והנה כח זה בנש\"י לעורר בחי' החכמה ומדות שבעצמי' ע\"י רוממותם לבחי' העצמי' וכמאמר מי כהוי' אלקינו<sup data-n=\"6120\">109</sup> בכל קראנו אליו כו' ולכן ביכולתם להגיע עד בחי' העצמי' ממש, וזהו יותר משהעגל רוצה כו' פרה רוצה להניק<sup data-n=\"6121\">110</sup> אך אעפי\"כ מוכרח להיות העגל רוצה, כך ע\"י פנימית הרצון שבנש\"י מעוררים למעלה פנימי' הרצון להיות נמשך בחכמתו ומדותיו בבחי' א\"ס ממש, אעפ\"י שאין ערוך מרצון שלמטה לגבי רצה\"ע שהוא בחי' א\"ס מ\"מ הרצון התחתון מעורר רצה\"ע [וכמאמר פתחי לי כחודה של מחט<sup data-n=\"6122\">111</sup> ואני אפתח לכם כפתחו של אולם כו', וזהו כי תהילתי אתה כי כל כוונתו ורצונו הוא לבחי' אתה הוי' לבדך שיהי' בבחי' אתה לנוכח בגילוי ולכן ביכולתו לעורר העצמי' כו' וד\"ל, [ועי\"ז יהי' נמשך ג\"כ בחי' רפאיני והושיעני שהם שתי מדות עצמות קו השמאל וקו הימין שבעצמי' כו' וד\"ל.",[["6112","101","<b>שמשבחים אדם. . שכלו ומדותיו לבא לידי גילוי</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תסד. וש\"נ. המשך והחרים תרל\"א ע' מט ואילך."],["6113","102","<b>לך הוי' הגדולה</b>: דהי\"א כט, יא."],["6114","103","<b>גדולה וגבורה בה\"א</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ס\"ע רכד ואילך. וש\"נ במדבר ח\"ב ע' שס וע' תקעה ואילך."],["6115","104","<b>כל הנשמה תהלל י\"ה</b>: תהלים קנ, ו."],["6116","106","<b>דסדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["6117","105","<b>בעלמין סתימין. . בעלמין דאתגליין</b>: ת\"ז בהקדמה יז, א."],["6118","107","<b>אימתי גדול</b>: ראה זהר פקודי רלה, א. ויקרא ה, א. מאמרי אדה\"א נ\"ך ע' פ. וש\"נ. סה\"מ תרכ\"ז ס\"ע ר. וש\"נ. פלח הרמון ח\"ש עד, ב."],["6119","108","<b>דלאו מכל אינון מדות כלל</b>: ראה ת\"ז בהקדמה יז, ב."],["6120","109","<b>מי כהוי' אלקינו</b>: ואתחנן ד, ז [בדילוג]."],["6121","110","<b>יותר משהעגל. . פרה רוצה להניק</b>: ראה פסחים קיב, א. מאמרי אדה\"א דברים ח\"א ע' רפז. וש\"נ. תו\"ח ויצא קסט, ג ובהערה 35. לעיל ע' א וע' ה."],["6122","111","<b>פתחי לי כחודה של מחט</b>: ראה ס' חרדים בהקדמה. לקו\"ש ויקהל ח\"א ע' 191 הערה 17. סה\"מ תרל\"ח ע' תסד ובהערה 57."]]],[4801940141,"<b>יום ג' לסדר בהעלותך תר\"ח</b>\n<b>רפאיני</b> ה' וארפא<sup data-n=\"6123\">1</sup>. הושיעני ואוושעה כי תהילתי אתה<sup data-n=\"6124\">2</sup>. להבין הכפל ל' וארפא ואוושעה. דלכאורה הוא מיותר כיוון שירפא ה' אותו בוודאי ירפא. וכן כאשר יושיע<sup data-n=\"6125\">3</sup> ה' אותו בוודאי יו‘וש’ע. הנה יש להקדים ענין בקשה זאת שהנביא מבקש בשביל כללות ישראל שהגם שהיא חולת אה'<sup data-n=\"6126\">4</sup> בגלותא מ\"מ ישלח ה' לה רפואה למכתה האנושה כו' וכמ\"ש ואף גם זאת לא מאסתים<sup data-n=\"6127\">5</sup> כו'. והנה שרש ענין המחלה מפרש הנביא בתחילה והוא במש\"א כי עזבו מקור מ\"ח<sup data-n=\"6128\">6</sup> את ה'. והנה להבין את המשל שדימה שם הוי' למקור מים חיים יש בזה ב' טעמים, הא' להיות שמים חיים נק' מים הנובעים בתמידות בכל עת מים חדשים, והיינו כדוגמת הנהר הנובע מן המעיין שאעפ\"י שהמעיין הוא קטן מ\"מ נובע ממנו נהר גדול בלי שיעור, והיינו מפני שהמעיין נובע מן התהום שהוא מקורא דלית לי' סופא לכן אעפ\"י שנביעת המעיין מצומצמת היא שאינו נובע בו רק טיפין מ\"מ בכל עת ורגע נובע בו טיפין חדשים בלי שיעור מחמת כח התהום הבלתי מוגבל השופע בו בתמידות לכן ממילא יוכל לימשך ממנו נהר גדול שהולך ג\"כ בתמידות בלי הפסק כי כח המעיין בנחל כמ\"ש השולח מעיינים בנחלים<sup data-n=\"6129\">7</sup>, והמעיין נביעתו בלתי מוגבל מצד כח התהום השופע בו לכן גם הנחל הולך בלי הפסק. וכמאמר כל הנחלים הולכים<sup data-n=\"6130\">8</sup> ל' הוה להיות שההילוך שלהם הוא בלתי הפסק כלל.\n<b>כ\"ה</b> למעלה עד\"ז כתיב ונהר יוצא מעדן כי נהר הוא בחי' בינה שנמשך לאורך ורוחב מבחי' החכמה<sup data-n=\"6131\">9</sup> כי החכמה הוא בחי' יו\"ד<sup data-n=\"6132\">11</sup> דש' הוי' שהוא בבחי' אין ומאין דחכמה שופע לבחי' היש<sup data-n=\"6133\">12</sup> דבינה<sup data-n=\"6134\">10</sup> שנק' ה'<sup data-n=\"6135\">13</sup> [ואין הכוונה שהבינה בעצמה היא בחי' יש רק שהיא בחי' מקור היש דבי\"ע משא\"כ החכמה היא בחי' מקור האין",[["6123","1","<b>רפאיני ה' וארפא</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ הוא כנראה הנדפס באוה\"ת בחוקותי כרך ב ע' תרצ [נדפס גם באוה\"ת ירמי' כרך א ע' שנה ואילך]. ועם הוספות — במהדורת תשנ\"ג וראה בהנסמן במ\"מ לשם. ראה גם סה\"מ תרל\"ה ח\"ב ע' רצט [ובהנסמן במ\"מ לשם]. המאמר שנדפס לפנ\"ז."],["6124","2","<b>רפאיני ה'. . כי תהילתי אתה</b>: ירמי' יז, יד."],["6125","3","<b>הכפל ל'. . וכן כאשר יושיע</b>: ראה אוה\"ת בחוקותי כאן ע' תרצ: וקושי' זו הקשה ג\"כ בזהר ח\"ג בהשמטות סי' יו\"ד דף ש\"ה ע\"א [בדפוס קאפוסט תקס\"ט, ולפנינו דש, סע\"ב]. נעתק באוה\"ת ירמי' כרך א' ע' שס."],["6126","4","<b>כללות ישראל. . חולת אה'</b>: נסמן לקמן הערה 64."],["6127","5","<b>ואף גם זאת לא מאסתים</b>: בחוקותי כו, מד [בדילוג]."],["6128","6","<b>כי עזבו מקור מ\"ח</b>: ירמי' יז, יג."],["6129","7","<b>השולח מעיינים בנחלים</b>: תהלים קד, י."],["6130","8","<b>כל הנחלים הולכים</b>: קהלת א, ז."],["6131","9","<b>ונהר יוצא מעדן. . החכמה</b>: בראשית ב, י. ראה גם לעיל ס\"ע שעח ובהערה 101."],["6132","11","<b>החכמה. . יו\"ד</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["6133","12","<b>החכמה. . אין. . היש דבינה</b>: ראה הנסמן בביאוה\"ז להצ\"צ כרך ב ע' תתרא. מאמרי אדה\"א בראשית ע' ב. דרושי חתונה ח\"ב ע' תעג. סה\"מ תרכ\"ט ע' רעח."],["6134","10","<b>נהר. . בינה</b>: זהר (אדרא דמשכנא) משפטים קכג, ב."],["6135","13","<b>דבינה שנק' ה'</b>: נסמן בהערה 11."]]],[4801940205,"השופע אין בבי\"ע כו' וד\"ל]. והיחוד דחו\"ב הוא בחי' יחוד תמידי<sup data-n=\"6136\">14</sup> שתמיד שופע השפע מבחי' חכמה לבינה והוא כדוגמת המעיין השופע בנהר בתמידות והיינו להיות שהחכמה מקבל מבחי' הכתר, שהוא בחי' א\"ס [והוא כדוגמת התהום כו']. לכן מתחדש השפע בבחי' החכמה בתמידות. ומן החכמה לבינה. ואח\"כ נמשך השפע בבחי' הוי\"ו דש' הוי' שהוא בחי' המדות דאצי' ומשם נמשך בבחי' המל' הנק' ה' אחרונה דש' הוי' ומשם מתחדשת השפע מאין ליש בנבראים. וזהו ענין המחדש בטובו<sup data-n=\"6137\">15</sup> בכי\"ו תמיד מע\"ב וכמבואר בכהאריז\"ל שחידוש מע\"ב בכל עת ורגע הוא מצד שמתחדש השפע במקורו בכל עת שפע חדשה שהוא בחי' יחוד או\"א אשר יחודם תמידי לצורך קיום חיות העולמות כו' וזהו טעם א' שבחי' שם הוי' נק' מקומ\"ח שהשפע הנובע מחכ' לבינה נק' מים חיים שזהו מבחי' היו\"ד לבחי' ה' ושפע זאת נובע מבחי' המקור שהוא בחי' הכתר הנרמז בקוש\"י<sup data-n=\"6138\">16</sup> דשם הוי' כו' וד\"ל. ולכן תרג' יונתן ע\"פ אותי עזבו מקומ\"ח<sup data-n=\"6139\">17</sup>, ית<sup data-n=\"6140\">18</sup> פולחני שבקו די בדילי' אנא מייתי עליהון יקרא כמבוע דמיין דלא פסקי<sup data-n=\"6141\">19</sup> מוהי<sup data-n=\"6142\">20</sup>. ונמצא שמה שנק' מיים חיים הוא ע\"ש תמידית הנביעה שנובע בתמידית בכל עת שפע חדשה כו'. ולכן המקור השופע השפעה זאת [שהוא בחי' אא\"ס שבכתר] נק' מקור מ\"ח כו'.\n<b>והטעם</b> הב' שדימה שם הוי' למקור מים חיים היינו שהוא מקור מים חיים הנובעים מלמטלמ\"ע כי הנה אנו רואים שהנחלים הולכים אל הים, וקודם שהם נופלים אל הים הם ראויים לשתי' ואחר שהם מתערבים בים הם בלתי ראויים לשתי' כי מי הים מלוחים ואח\"כ הם שבים ללכת [ויש בזה ב' דיעות<sup data-n=\"6143\">21</sup> הא' שהולכים מן הים מתחת לארץ ועולים מתתא לעילא דרך כדור הארץ עד שהם<sup data-n=\"6144\">22</sup> נובעים למעלה והולכים ע\"פ הארץ וע\"י הליכתם דרך כדור הארץ נמתקו ונעשים ראויים לשתי'. ודיעה הב' שהמים הולכים עד הנהר היוצא מעדן ומשם הם שבים דרך נהר פרת ונהר פרת מקלח תחת הקרקע ועולה מלמטלמ\"ע דרך כדור הארץ, וע\"י כל הנחלים עולים מתתא לעילא וחוזרים ונובעים ע\"פ הארץ, ויהי' איך שיהי' לב' הדיעות הם מתעלמים בכדור הארץ ונובעים ע\"פ הארץ ואז נעשים ראויים לשתי' כמקדם כו'] ע\"פ הקרקע ואז נעשים ראויים לשתי' כמקדם, נמצא שיש בהם גילוי והעלם וגילוי שמתחלה בעת שהולכין מן הנהר היוצא מעדן כו' הם בחי' גילוי ואח\"כ כשמתערבים בים הם מתעלמים בבחי' העלם, ואח\"כ ע\"י שמתעלמים בכדור הארץ הם נגלים כבתחילה בנחלים ע\"י המעיינות ולכן נק' מים חיים ע\"ש גילויים מן ההעלם, והמקור",[["6136","14","<b>והיחוד דחו\"ב. . תמידי</b>: ראה לקמן הערה 33."],["6137","15","<b>המחדש בטובו</b>: ברכת יוצר. ראה גם סידור קול יעקב במקומו."],["6138","16","<b>הכתר הנרמז בקוש\"י</b>: ראה זהר ויקרא י, ב. פרדס שער שם בן ד' שי\"ט, פ\"ב. הנסמן במאמרי אדה\"א קונטרסים ע' תכז."],["6139","17","<b>אותי עזבו מקור מ\"ח</b>: נסמן לקמן בהערה 72."],["6140","18","<b>ית</b>: א ובת\"י ליתא."],["6141","19","<b>פסקי</b>: בתרגום: פסיק. אד: פסקין — והוא לשון התרגום עה\"פ יז, יג (שבהערה 6). וראה גם בהערה הבאה."],["6142","20","<b>מוהי</b>: ליתא בתרגום כאן. והובא בתרגום עה\"פ יז, יג. וראה בהערה שלפנ\"ז אד."],["6143","21","<b>ב' דיעות</b>: ראה גם אוה\"ת כאן ע' תרצא. בהמאמר שלפנ\"ז ובהערות 11-13."],["6144","22","<b>הם</b>: ניתוסף ע\"פ א."]]],[4801940262,"הממשיך אותם מן ההעלם הזה נק' מקור מים חיים. כ\"ה ע\"ד דוגמא זאת למעלה יש ב' מיני שפע, מעילא לתתא [הנק' או\"י] ומתתא לעילא [הנק' או\"ח] וש' הוי' הוא מקור ב' מיני שפע הנ\"ל. והנה כבר נת' איך שהוא מקור לשפע הנמשכת מעילא לתתא בהתחדשות כנ\"ל.\n<b>אך</b> להבין השפע שמלמטה למעלה ואיך שם הוי' הוא מקור אלי', י\"ל מאמר אתה ה' לבדך<sup data-n=\"6145\">23</sup> כו' אתה עשית את השמים ושמי השמים וכל כו' הארץ כו' הימים וכל אשר בהם כו'. והנה אתה הוי' לבדך הוא<sup data-n=\"6146\">24</sup> בבחי' אצי' ששם אא\"ס הוא בבחי' גילוי רב ועצום עד אשר לא נגלה כ\"א הוא לבדו ואין בלתו [כי בספי' א' בזוהר איהו וחיוהי חד איהו וגרמוהי חד<sup data-n=\"6147\">25</sup>, ואפי' בחי' הנשמות הגם שכבר נפרדו מן הקו\"ח כמבואר באגה\"ק במאמר איהו וחיוהי<sup data-n=\"6148\">26</sup> מ\"מ הם בתכלית הביטול במציאות עד שאינם נראים ליש כלל נמצא שבאצי' אינו מתגלה כ\"א אא\"ס כמ\"ש לבדו כו']. וזהו אתה הוי' כי באצי' מאיר שם הוי' היו\"ד הוא בחי' חכ' שנמשל למעיין והה' הוא בחי' בינה שנמשך לאו\"ר כנהר הנמשך מן המעיין כו'. וזהו ג\"כ ונהר יוצא מעדן כו'. ואח\"כ בחי' הוי\"ו הוא בחי' מדות דאצי' וה' אחרונה הוא בחי' מל' דאצי' והם בחי' ז'<sup data-n=\"6149\">27</sup> נחלים המתחלקים מנהר היוצא מעדן כו' ונמצא שבאצי' אינו רק גילוי שם הוי' ואין זולתו כו'. ואח\"כ נמשך השפע מאצי' לבריאה שעז\"א אתה עשית את השמים ושמי השמים [שזהו ו\"ס<sup data-n=\"6150\">28</sup> דבריאה חב\"ד ומדות כו'] וכל צבאם הם השרפים האומרים קדוש<sup data-n=\"6151\">29</sup> ולהיות שמשיגים קדושתו של הקב\"ה [ולכן נאמר עליהם שרפים עומדים ממעל לו<sup data-n=\"6152\">30</sup> כדוגמת השכל המקיף את המושכל ומשיגו שאז השכל הוא ממעל למושכל ומקיפו כו' וד\"ל ממכי\"ק<sup data-n=\"6153\">31</sup> ] לכן אין בהם תערובות יש ופסולת עדיין ניכר, והטעם של השגה והביטול שלהם הוא מחמת שהם ראשית הבריאה מאין ליש לכן הם קרובים אל האין ויש להם השגה בבחי' האין בדרך רוממות והבדלה ולכן אומרים קדוש, ועוד דאימא עילאה מקננא בכורסייא<sup data-n=\"6154\">32</sup> ונמצא שפנימיותם הוא אור אימא עילאה, וידוע דחו\"ב הם תרין ריעין דל\"מ<sup data-n=\"6155\">33</sup> ולכן יש להם השגה בבחי' האין דחכמה בדרך רוממות והפלאה, ולכן הם בתכלית הביטול ואינו ניכר בהם תערובות יש ולכן נמשל השפע שלהם כדוגמת שפע הנחלים הראוים לשתי' כו' [וכידוע דנוגה דבריאה רובו טוב<sup data-n=\"6156\">34</sup> ומיעוטו",[["6145","23","<b>אתה הוי' לבדך</b>: נחמי' ט, ו [בדילוג. שמי — ראה גם במאמר שלפנ\"ז על יד הערה 14]."],["6146","24","<b>הוא</b>: ניתוסף ע\"פ א."],["6147","25","<b>איהו וחיוהי חד איהו וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."],["6148","26","<b>באגה\"ק במאמר איהו וחיוהי</b>: ס\"כ (קל, א)."],["6149","27","<b>ז'</b>: ד: בין השיטין תוקן ד."],["6150","28","<b>ו\"ס</b>: א: י\"ס."],["6151","29","<b>השרפים האומרים קדוש</b>: ישעי' ו, ג. ראה הערה 39."],["6152","30","<b>שרפים עומדים ממעל לו</b>: ישעי' שם, ב. ראה גם לעיל ע' רכה ואילך."],["6153","31","<b>ממכי\"ק</b>: ממאמר כתב יד קדשו (של הצ\"צ). התוכן — ראה גם אוה\"ת כאן ס\"ע תרצא ואילך. לעיל מאמר ד\"ה והתהלכתי תרכ\"ב הערה 50."],["6154","32","<b>דאימא עילאה מקננא בכורסייא</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["6155","33","<b>תרין ריעין דל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. תו\"ח בראשית כא, ב ובהערה 8."],["6156","34","<b>דנוגה דבבריאה רובו טוב</b>: ראה ע\"ח שער ק\"נ שמ\"ט, פ\"ו. מאמרי אדה\"א דברים ח\"ד ע' א'תצג. וש\"נ. אוה\"ת נח כרך ג' ע' 1200 ואילך."]]],[4801940315,"רע וממילא המועט בטל ברוב כו', אבל באצי' לא יגורך רע<sup data-n=\"6157\">35</sup> כלל כי אפי' הנוגה שנגד אצי' מקומו בבריאה<sup data-n=\"6158\">36</sup> כי באצי' הוא תכלית הביטול אפי' בנשמות מצד שיש להם בחי' ראי' בבחי' האין כמאמר אודון מתקרי חכים הרואה את הנולד<sup data-n=\"6159\">37</sup> כו' משא\"כ בשרפים אינו נק' רק ביטול היש כו' וכמשל ההפרש בין המשיג גדולת המלך מרחוק ובין הרואה את המלך עצמו שהרואה בטל למהותו, וממילא נעשה בו ביטול המהות משא\"כ המשיג אינו בטל רק להתפשטותו לכן גם בו אינו רק ביטול ההתפשטות כו' וד\"ל], ואח\"כ כאשר נמשך השפעה מבריאה ליצי' ושם אינם משיגים קדושתו כלל אפי' בדרך רוממות והפלאה [שזהו התפשטות המהות כנ\"ל] והיינו איך שהוא קדוש ומובדל והוא לבדו הוא ואין בלתו, רק שמשיגים התפשטות החיות שלו<sup data-n=\"6160\">38</sup> בעולמות להחיות<sup data-n=\"6161\">39</sup>ם, ולכן או' ברוך, ולכן התפעלות המלאכים שביצי' הוא ברעש ומורגש ונמצא שיש בהם תערובות יש [ולכן נוגה דיצי' חצי' טוב וחצי' רע כו'<sup data-n=\"6162\">40</sup>], ועז\"נ הימים וכל אשר בהם [שזהו בחי' י\"ס דיצי' והמלאכים הנק' חיות הקודש], ולכן נמשלו למי הים שמלוחים המה ואינם ראויים לשתי', והיינו מצד תערובות הפסולת שבהם, ואח\"כ כאשר נתעלם שפע היצי' בעשי' והעיקר בעשי' הגשמי' בנשמות שבגופים אז מתברר השפע מן הפסולת המעורבת בה והיינו ע\"י שהם מהפכים חושך לאור ע\"י התומ\"צ שמקיימים ושפע הזאת עולה מלמטלמ\"ע. ועז\"א אתה הוא האלקים אשר בחרת באברם<sup data-n=\"6163\">41</sup> כו' ונמצא שיש בכאן גילוי והעלם וגילוי, והגילוי הוא<sup data-n=\"6164\">42</sup> השפע שבאצי' ובריאה שנמשך מעילא לתתא כנ\"ל וההעלם הוא בעולם היצי' כו' ואח\"כ ע\"י התעלמותם בעשי' שנק' ארץ [שעז\"א הארץ וכל אשר עליה כו'] חוזרים ומתגלים ועולים מתתא לעילא, ושפע זאת העולה מתתא לעילא נק' מים חיים, וידוע שכל<sup data-n=\"6165\">43</sup> מיני בירורים ועליות שעולים ע\"י קיום המצות שנש\"י מקיימים מ\"מ עיקר הכח והעוז הוא מצד כח הא\"ס המתלבש בהם למטה הנותן בהם כח ועוז לעשות חיל. נמצא שמצד בחי' זאת נק' שם הוי' מקור מים חיים מלמטלמ\"ע כו' וד\"ל.\n<b>וזהו</b> וצדקה כנחל איתן<sup data-n=\"6166\">44</sup> כי כל המצות נק' בשם צדקה<sup data-n=\"6167\">45</sup>, והכוונה שהשפע המתבררת ע\"י המצות ועולה מלמטה למע' עולה עד מקור השפע בתחילתה בבחי' החכמה כמו שהיא נמשכת מאין דכתר ומעורר שם שפע חדשה וממילא נמשך התחדשות השפע בבינה שהיא בחי' נחל איתן<sup data-n=\"6168\">46</sup> כו' מבוע דמיא דלא פסקין מוהי",[["6157","35","<b>לא יגורך רע</b>: תהלים ה, ה. ראה לקו\"ת במדבר ג, ג."],["6158","36","<b>הנוגה שנגד אצי' מקומו בבריאה</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תנג וע' תעה. וש\"נ. הנחות תקע\"ז ע' קז. תו\"ח נח נא, א ובהערה 2. לעיל ע' תכא."],["6159","37","<b>אודון </b>[אד: אידן]<b>. . הרואה את הנולד</b>: ראה תמיד לב, א."],["6160","38","<b>שלו</b>: ניתוסף ע\"פ אד. ובכת\"י זה הניח מקום פנוי."],["6161","39","<b>או' ברוך. . חיות</b>: יחזקאל ג, יב. ברכת יוצר. ראה חולין צב, רע\"א ובתוד\"ה ברוך."],["6162","40","<b>ועז\"א אתה. . כו'</b>: אד: ליתא."],["6163","41","<b>אתה הוא. . באברם</b>: נחמי' ט, ז [בדילוג]."],["6164","42","<b>הוא</b>: ניתוסף ע\"פ א."],["6165","43","<b>שכל</b>: א: אשר כל."],["6166","44","<b>וצדקה כנחל איתן</b>: עמוס ה, כד."],["6167","45","<b>כל המצות נק' בשם צדקה</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' עדרת. וש\"נ. תו\"ח שמות ח\"א יד, א ובהערה 628."],["6168","46","<b>בבינה. . נחל איתן</b>: ראה גם המאמר שלפנ\"ז על יד הערה *45."]]],[4801940364,"כו'. ועוד יתפרש וצדקה כנחל איתן כי הנה אותיות איתן הם משמשות לעתיד<sup data-n=\"6169\">47</sup> כידוע והיינו גילוי השפע שיתגלה לע\"ל דכתיב ישכיל עבדי<sup data-n=\"6170\">48</sup> היינו שיתגלה מבחי' המשכיל מקור החכמה שהיא בחי' אין האמיתי [למע' מבחי' גילוי החכמה מאין], בבחי' הבינה<sup data-n=\"6171\">49</sup> הנק' איתן וכמ\"ש משכיל לאיתן<sup data-n=\"6172\">50</sup> כו'. וזהו וצדקה כנחל איתן היינו שבאמת נתעורר עכשיו זה הגילוי ע\"י המצות רק שלע\"ע נעלם השפע בלבוש המצות רק שלע\"ל יתגלה מתוך הלבוש ונמצא שהצדקה הוא כמו נחל איתן שיתגלה לע\"ל כו'. וזהו מי צרר מים בשמלה<sup data-n=\"6173\">51</sup>, מים<sup data-n=\"6174\">52</sup> הוא בחי' השפע החדשה הנמשכת מבחי' החכמה [ולמעלה יותר מבחי' מקור החכמה], ע\"י התעוררות מעהמ\"צ ואח\"כ נמשכים בבינה ומתלבשת השפע בלבושי המצות, וזהו מ\"י שהוא בחי' בינה<sup data-n=\"6175\">53</sup> צרר מים דחכמה בשמלה ע\"י לבושי המצות כו' וד\"ל. והנה ע\"י שפע זאת העולה מתתא לעילא ע\"י המצות מתרוממת גם הנשמה ועולה למעל' מע' [כמ\"ש וצדקה תרומם גוי<sup data-n=\"6176\">54</sup> כו']. וזהו והיתה נפש אדוני צרורה<sup data-n=\"6177\">55</sup> בצרור החיים את הוי' כי צרור החיים הוא בחי' בינה<sup data-n=\"6178\">56</sup> שבה צרור החיות הנמשך מבחי' הח\"ע והנשמה עולה ומתקשרת בשפע זאת ע\"י המצות כו' וד\"ל. והנה בחי' זאת נק' שביעי<sup data-n=\"6179\">57</sup> רקיע השביעי כמאמר המד\"ר כל השביעות חביבין<sup data-n=\"6180\">58</sup> כו' וזהו השפע הנמשך מבחי' הכתר בחו\"ב ועיקר התגלותו הוא בבינה כידוע דהתגלות עתיק הוא בבינה<sup data-n=\"6181\">59</sup> וזהו סולו לרוכב בערבות<sup data-n=\"6182\">60</sup> בי\"ה שמו, וזהו צרור החיים כו' וד\"ל. והנה ע\"ד הנ\"ל בשפע שלמעלה שיש בה בחי' גילוי והעלם וגילוי כן הוא בנפש בעבודה שבלב, שמתחילה ע\"י התפי' שמתבונן בעומק דעתו ובינתו עד שממשיך בנפשו בחי' ראי' דחכמה להיות רואה את הנולד הוא בחי' גילוי ומעורר עי\"ז ג\"כ למעלה בחי' יחוד חו\"ב, ואח\"כ ג\"כ ע\"י לימוד תושב\"פ שזמנה אחר התפילה<sup data-n=\"6183\">61</sup> ממשיך גילוי יותר נעלה מבחי' משכיל לאיתן כנ\"ל, וזהו והאיתני\"ם<sup data-n=\"6184\">62</sup> אותיות תנאי\"ם<sup data-n=\"6185\">63</sup> שהם ממשיכים ההשפעה מבחי' משכיל לבחי' איתן ע\"ש שהם המחדשים הלכות דתושבע\"פ ולכן נק' איתנים כו' ואח\"כ בעסקו בעניני העוה\"ז נעשה העלם, אך אח\"כ כשמקיים המצות חוזר ומתגלה מן ההעלם מתתא",[["6169","47","<b>אותיות איתן הם משמשות לעתיד</b>: ראה גם קו\"א לתניא קסא, א. לקו\"ת ר\"פ ראה."],["6170","48","<b>ישכיל עבדי</b>: ישעי' נב, יג."],["6171","49","<b>הבינה</b>: ניתוסף ע\"פ אד."],["6172","50","<b>משכיל לאיתן</b>: תהלים פט, א."],["6173","51","<b>מי צרר מים בשמלה</b>: משלי ל, ד."],["6174","52","<b>מים</b>: ניתוסף ע\"פ אד."],["6175","53","<b>מ\"י שהוא בחי' בינה</b>: זהר משפטים קיז, ב. לקו\"ת פקודי ד, ג. תו\"ח פקודי ח\"ב תמג, ד ובהערה 78."],["6176","54","<b>וצדקה תרומם גוי</b>: משלי יד, לד [ושם צדקה — ראה גם לעיל ע' שנג ובהערה 88]."],["6177","55","<b>והיתה נפש אדוני צרורה</b>: שמו\"א כה, כט."],["6178","56","<b>צרור החיים. . בינה</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"ח בערכו. אוה\"ת שמואל כרך א ע' ל ואילך."],["6179","57","<b>שביעי</b>: ניתוסף ע\"פ אד."],["6180","58","<b>כל השביעות חביבין</b>: ראה ויק\"ר פכ\"ט, יא."],["6181","59","<b>דהתגלות עתיק הוא בבינה</b>: מובא בכ\"מ בשם הע\"ח — ראה תו\"ח לך פא, ב ואילך. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' ד. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["6182","60","<b>סולו לרוכב בערבות</b>: תהלים סח, ה."],["6183","61","<b>לימוד תושב\"פ שזמנה אחר התפילה</b>: ראה רש\"י ותוס' ברכות ה, ב. לקו\"ת חוקת סב, סע\"ג. מסעי פח, ג. ואתחנן ג, סע\"ג ואילך. ברכה צו, ב ובהוספות להערות וציונים שם. שה\"ש כ, ד. תו\"ח תצוה שנ, ג. וש\"נ. אוה\"ת בראשית כרך ו ע' 2044."],["6184","62","<b>והאיתני\"ם</b>: מיכה ו, ב."],["6185","63","<b>והאיתני\"ם אותיות תנאי\"ם</b>: זהר סבא משפטים קי, ב. רע\"מ תצא רעח ב. ת\"ז תכ\"א מג, סע\"ב."]]],[4801940410,"לעילא כו', ומעורר שפע יותר נעלה מבחי' משכיל הנ\"ל בגילוי בבחי' איתן כנ\"ל בענין וצדקה כנחל איתן כו' וד\"ל.\n<b>והנה</b> בגלות נאמר סמכוני באשישות כו' כי חולת אהבה אני<sup data-n=\"6186\">64</sup>, כי הנה ענין החולה שאבד חוש הטעם ולא יכול לטעום שום טעם במאכל, והיינו מצד שיש לו אש זרה המנגד לאש הטבעי שהוא חום הטבעי שממנו עיקר החיות כו', כ\"ה בבחי' אלקות הנה יש בחי' אש דקדושה שהוא ענין אשה<sup data-n=\"6187\">66</sup> ואיש אש ה'<sup data-n=\"6188\">65</sup> ואש י', אש ה' הוא רשפי אש התשוקה לצאת מגדר הכלי בבחי' מי לי בשמים<sup data-n=\"6189\">67</sup> ועמך לא חפצתי כו' ואח\"כ נמשך השפע מלמעלמ\"ט ג\"כ בבחי' רשפי אש שזהו בחי' אש י' כו'. אך לעו\"ז יש אש זרה דק\"נ, והיינו רשפי אש שבתאוות היתר, כי הנה תאוות היתר הוא ג\"כ קליפה [וראי' שכאשר משה עלה למרום בתכלית הקדושה גם לחם לא אכל<sup data-n=\"6190\">68</sup> כו'], אך נק' ק\"נ וסמוכה לקדושה ולכן יכולה להכלל בקדושה והיינו כאשר אוכל לעבודת ה' כו', אך כאשר אוכל למלאות תאוותו ברשפי אש וחום התאווה אז יורד ק\"נ ונכללת בגקה\"ט ולכן נק' אז בשם זונה [כמאמר ולא תתורו כו' אשר אתם זונים<sup data-n=\"6191\">70</sup> כו'] ותרגומו נפקת ברא<sup data-n=\"6192\">69</sup>, היינו שיצאה חוץ לגבולה שהיא סמוכה לקדושה ונכללה ברע גמור בגקה\"ט כו' וזהו ענין אש זרה כו'. והנה בחי' אש ה' דקדושה הוא בחי' הצמאון צמאה לך נפשי<sup data-n=\"6193\">71</sup> כו', והוא בחי' רצוא שהוא בחי' העלאה מלמטלמ\"ע כו', ואח\"כ נמשך מלמעלמ\"ט מבחי' מים חיים הנ\"ל לרוות הצמאון עד שנעשה בחי' שוב מן הרצוא והיינו התענוג האלקי שמרווה הצמאון רשפי אש אלקי כו'. והנה כ\"ה יש מים דקליפה שהוא בחי' תענוגי עוה\"ז המרווים צמאון רשפי אש זרה הנ\"ל ונמצא שע\"י שיש לו אש זרה בתענוגי עוה\"ז עי\"ז מרווה צמאונו בתענוגי עוה\"ז, ועי\"ז אובד חוש התענוג להתענג באלקות כו', וזה כי שתים רעות עשה עמי אותי עזבו מקור מים חיים<sup data-n=\"6194\">72</sup> ע\"י אש זרה לחצוב להם בארות נשברים שזהו לרוות צמאונו בתענוגי עוה\"ז שנק' בארות נשברים ע\"ש שנמשכו מבחי' שביה\"כ כו' וזהו מארז\"ל רעה אחת שהיא כשתים<sup data-n=\"6195\">73</sup>, היינו האש זרה והדביקות בתענוגי עוה\"ז, שזהו שתים רעות, אך אעפי\"כ רעה אחת היא כי הא בהא תליא כו'. והנה לתקן אש זרה ע\"ז מבקש הנביא בעד כללות ישראל רפאיני ה', והיינו ע\"י שימשיך אש יותר עליון בנש\"י, ועי\"ז ממילא יתרפא מבחי' החולי דאש זרה הנ\"ל.",[["6186","64","<b>סמכוני. . חולת אהבה אני</b>: שה\"ש ב, ה."],["6187","66","<b>ואיש. . ואש יו\"ד</b>: ראה סוטה שם. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אשה. תו\"ח בשלח ח\"א רלח, ב. וש\"נ."],["6188","65","<b>אשה. . אש ה'</b>: ראה סוטה יז, א. זהר בראשית מח, ב. ביאוה\"ז נח ז, ב. תו\"ח שבהערה הבאה."],["6189","67","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם לעיל ע' רמט ובהערה 83."],["6190","68","<b>משה. . לחם לא אכל</b>: ראה תשא לד, כח. עקב ט, יח. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצו."],["6191","70","<b>ולא תתורו. . זונים</b>: שלח טו, לט."],["6192","69","<b>זונה. . נפקת ברא</b>: וישב לח, טו ובת\"א ות\"י שם. ראה מאמרי אדה\"א הנחות תקע\"ז ע' קנז. וש\"נ."],["6193","71","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["6194","72","<b>כי שתים. . אותי עזבו מקור מים חיים</b>: ירמי' ב, יג [בדילוג]."],["6195","73","<b>רעה אחת שהיא כשתים</b>: ראה תענית ה, סע\"א ואילך."]]],[4801940452,"<b>וביאור</b> הדברים הנה יש בחי' אש דקדושה אשר ממנו נעשה מקור לאש הגיהנם כמארז\"ל מזיעתן של חיות הקודש<sup data-n=\"6196\">74</sup> נמשך נהר דינור ויורד על ראש רשעים בגהינם, כמו ע\"ד דוגמא למטה מן ההתפעלות בעבודת הוי' יכעוס על המנגד לאלקים חיים<sup data-n=\"6197\">75</sup> הגם שהכעס שלו הוא קנאה שמתקנא בעד אלקות מ\"מ כעס הוא פסולת רק שהוא פסולת דקדושה, וכך למעלה מבחי' התפעלות חיות הקודש שמתפעלים באהוי\"ר מבחי' אלקים חיים ומלך עולם<sup data-n=\"6198\">76</sup>, ממילא נמשך רוגז על המנגד ומסתיר לבחי' אלקות, ורוגז זה נמשך ע\"י לבושי החשמל המלביש לכל נברא שנק' העור שלו, וזהו מקור כל הדינין קשין הנמשכים על ראש רשעים בגיהנם, והנה כל אלו הדינים קשין אינם נמשכים רק מבחי' חיות הקודש שהם מלאכים דיצי' שהם קרובים לבחי' הרע [כנ\"ל דנוגה דיצי' חצי' טוב וחצי' רע] לכן מתפעלים ברוגז עליו ולכן אמרו מזיעתן של חיות דוקא, אבל יש בחי' אש השרפים שהוא בחי' השלהבת י\"ה כי להיות שהשגתם הוא בחי' קדושתו של הקב\"ה, לכן ההתפעלות שלהם הוא בלתי הרגש כלל להיותה כלולה בעומק ההשגה [ולכן נק' עומדים ל' ביטול<sup data-n=\"6199\">77</sup> כו', משא\"כ חיות הקודש מתפעלים ברעש ומורגש כו'] לכן היא מרוממת ומובדלת לגמרי מבחי' הרע כי אין מהם שורש ומקור לרע להיותם מופשטים מבחי' הרגש כו', והיא הנותנת שאינם מתפעלים ג\"כ ברוגז על הרע [כענין וירא און ולא יתבונן<sup data-n=\"6200\">78</sup> להיותו מרומם ממנו לזאת לא יתפעל ממנו הגם שרואה אותו כו'] ונמצא שמן האש שלהם לא יסתעף שום דינים קשים כו'. וזהו הטעם דלא תבערו אש<sup data-n=\"6201\">79</sup> בכל מושבותיכם ביום השבת, היינו שלא לעורר האש שממנו נמשך דינים קשים שהוא אש הגיהנם, כי הגיהנם נח ג\"כ ביום השבת<sup data-n=\"6202\">80</sup> כי השבת הוא עונג אלקי שבמוח שאינו מסתעף ממנו שום יניקה לרע כו', אבל בבהמ\"ק מבערים אש בשביל הקרבנות אפי' ביום השבת, להיות שהאש דשם הוא אש דשרפים ואינו מסתעף ממנו שום גבורות קשות כו' וד\"ל. והנה שורש אש השרפים הוא מבחי' בינה<sup data-n=\"6203\">81</sup> עילאה כי אימא מקננא בכורסייא וחו\"ב הם תרין רעין כו', ומבחי' בינה מקור הרפואות<sup data-n=\"6204\">82</sup> כידוע וזהו רפאינו<sup data-n=\"6205\">83</sup> ה' כו' [ואפ\"ל שמבחי' אשה<sup data-n=\"6206\">84</sup> אש ה' נמשך אש דחיות ואופנים ויוכל להיות התגברות אש זרה, משא\"כ בחי' איש אש יו\"ד שזהו גבו' דאבא הנמשכים בבינה משם נמשך הרפואה לרפאותו מאש זרה ע\"י אש אוכלת, אש<sup data-n=\"6207\">85</sup> וכענין הבלא מפיק הבלא<sup data-n=\"6208\">86</sup> כו' וד\"ל], וארפא",[["6196","74","<b>מזיעתן של חיות הקודש</b>: ראה חגיגה יג, סע\"ב. סה\"מ תרל\"ח ר\"ע קמב ובהערה 779. מאמר גור ארי' תר\"מ פ\"ב. וש\"נ."],["6197","75","<b>לאלקים חיים</b>: ואתחנן ה, כג."],["6198","76","<b>אלקים חיים ומלך עולם</b>: ברכת יוצר."],["6199","77","<b>עומדים ל' ביטול</b>: ראה לקו\"ת נשא כ, ג. לעיל ע' קנט ובהערה 52."],["6200","78","<b>וירא און ולא יתבונן</b>: איוב יא, יא."],["6201","79","<b>דלא תבערו אש</b>: ויקהל לה, ג."],["6202","80","<b>הגיהנם נח ג\"כ ביום השבת</b>: ראה סנהדרין סה, ב וברש\"י שם. זהר יתרו פח, ב. מאמרי אדה\"א דברים ח\"ג ע' קיח. וש\"נ."],["6203","81","<b>השרפים. . בינה</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ס\"ע א'רח ואילך."],["6204","82","<b>בינה מקור הרפואות</b>: ראה גם אוה\"ת (יהל אור) תהלים ע' יח. יו\"כ ע' א'תקנו. ירמי' ע' א'שנו [נדפס גם ב] בחוקותי כאן [מהדורת תשנ\"ג] ר\"ע תרצז."],["6205","83","<b>רפאינו</b>: אינו ברור בהכת\"י. אד: רפאני."],["6206","84","<b>אשה</b>: ניתוסף ע\"פ אד."],["6207","85","<b>אש אוכלת אש</b>: יומא כא, ב. ראה גם סה\"מ תרל\"ח ע' חצר."],["6208","86","<b>הבלא מפיק הבלא</b>: שבת מא, א."]]],[4801940489,"אח\"כ מעצמי כי אחר התשובה שהוא בחי'<sup data-n=\"6209\">87</sup> הרפואה דאש זרה הנמשכת מלמעלה משם הוי' צריך לחזק א\"ע בעבודת ה' על להבא בבחי' אתכפיא ואתהפכא, וענין אתכפי' הוא לקדש א\"ע במותר לו<sup data-n=\"6210\">88</sup> או ללמוד יותר מרגילותו, וזאת יוכל<sup data-n=\"6211\">89</sup> לעשות דוקא כאשר יומשך מלמעלה כח וחיזוק לזה כי איך יכולים לכלות קליפה וס\"א רק כשנמשך אור מלמעלה משם הוי' אז מעט אור דוחה הרבה מן החושך<sup data-n=\"6212\">90</sup> ואז ממילא אוכל להתגבר עליו לגמרי כו' ולכן כאשר יהי' רפאיני ה' דוקא אז וארפא מעצמי כו'.\n<b>הושיעני</b> ואוושעה, הנה כתיב ויקרא ה' ה'<sup data-n=\"6213\">91</sup> שיש בחי' הוי' באצי' שנק' שם הוי' ע\"ש שהוא מהווה מאין ליש והוא בחי' מקור מ\"ח הנ\"ל שזהו בחי' קוש\"י שבשם הוי' שהוא המקור דמים חיים כנ\"ל, אך יש בחי' הוי' שהוא למעלה מהשתל' דאבי\"ע רק השגות<sup data-n=\"6214\">92</sup> המהות להיות שם הוי' שמוכרח להיות ג\"כ ע\"י צמצום והתפשטות המשכה והתפשטות עד שיתגלה שם הוי' דאצי' [והוא בבחי' א\"ק] וזהו הושיעני המשכת ש\"ע נהורין<sup data-n=\"6215\">93</sup> שהוא בחי' הפנת המהות כענין וישע ה'<sup data-n=\"6216\">94</sup> כו' ואז ואוושעה אוכל לעורר מלמט'<sup data-n=\"6217\">95</sup> למעלה ג\"כ המשכת שם הוי' הנ\"ל ע\"י שאעשה בי בחי' צמצום והתפשטות והיינו ביטול הרצון להיות סומ\"ר עי\"ז גורמים למעלה המשכת היו\"ד דש' הוי' וע\"י וע\"ט שהוא בחי' התפשטות אגרום למעלה בחי' המשכת הה', וכ\"ז בהוי' הא' אך דווקא לאחר שתושיעני מלמעלה ע\"י המשכת ש\"ע נהורין הנ\"ל אז ואוושעה כו' וד\"ל. כי תהילתי אתה, הנה תהלה יש ב' פי' הא' מלשון הילול ושבח והב' מלשון תוס' אור כענין בהלה נרי<sup data-n=\"6218\">96</sup> עלי ראשי כו', ושני הפי' עולים בקנה א' כידוע שכאשר מהללים את האדם בחכמתו ומדותיו אזי מרוממים החכמה והמדות לעצמי' נפשו ומוסיפים אורות בהם מעצמי' נפשו ועי\"ז ממילא נמשך השפעה מחכמה ומדותיו לזולתו כך הוא הענין של ההילול ושבח למעלה להוסיף אורות בי\"ס דאצי' וממילא יהי' הגילוי למטה כו' ולזה אמר נתינת טעם לכל הנ\"ל דרפאיני והושיעני כו' כי כל תהילתי שאני ממשיך אורות אין הכוונה לעצמי ולגרמי רק בחי' אתה שכולל ב' ענינים הא' אתה הוי' לבדך והב' בחי' אתה לנוכח שהוא ההתגלות למטה וזהו כוונתו שיהי' גילוי אתה ה' לבדיך למטה בעשי' בכדי שיושלם<sup data-n=\"6219\">97</sup> כוונה שלך להיות לו דירה בתחתונים א\"כ כיון שאין כוונתי לעצמי רק להשלים הכוונה שלך א\"כ מהראוי שתרפאיני ותושיעני כו' וד\"ל.",[["6209","87","<b>בחי'</b>: ניתוסף ע\"פ א."],["6210","88","<b>לקדש א\"ע במותר לו</b>: ספרי ראה יד, כא. יבמות כ, א. ראה שע\"ת נז, ב ובהערה 20."],["6211","89","<b>יוכל</b>: אד: אוכל. וראה בסמוך בפנים."],["6212","90","<b>מעט אור דוחה הרבה מן החושך</b>: ראה חובת הלבבות שער יחוד המעשה פ\"ה. תניא פי\"ב."],["6213","91","<b>ויקרא ה' ה'</b>: תשא לד, ו. ראה גם לקו\"ת ר\"ה נט, א ואילך."],["6214","92","<b>השגות</b>: אד: הטיית."],["6215","93","<b>ש\"ע נהורין</b>: ראה זהר אד\"ר נשא קכח, ב. ע\"ח שער א\"א שי\"ג, פי\"ד. אוה\"ת מטות ע' א'רעב. המשך תער\"ב ח\"ב ע' א'רה."],["6216","94","<b>וישע ה'</b>: בראשית ד, ד. ראה גם לעיל ע' קמו ובהערה 65."],["6217","95","<b>מלמט'</b>: ניתוסף ע\"פ א."],["6218","96","<b>בהלה נרי </b>[א: בהלו נרו]: איוב כט, ג."],["6219","97","<b>שיומשך</b>: א: שיושלם."]]]]});
